var e=JSON.parse(`[[2601,"Основні оператори RxJS включають map задля перетворення даних, filter задля фільтрації, switchMap задля перемикання на новий потік, mergeMap задля паралельної обробки, catchError задля обробки помилок й debounceTime задля затримки. Їх застосовують у ланцюжку через pipe, щоб керувати асинхронними подіями.","Основні оператори RxJS й їхнє застосування\\nRxJS надає потужні оператори для роботи з асинхронними потоками даних (Observable). Вони дають змогу перетворювати, фільтрувати й комбінувати потоки й обробляти в них помилки, що особливо корисно в Angular і React, щоб керувати подіями, HTTP-запитами й станами.\\n\\nПопулярні оператори\\n\\n- map — він перетворює кожне значення потоку; наприклад, видобуває поле з об'єкта.\\n- filter — він пропускає лише ті значення, які задовольняють умову.\\n- switchMap — він скасовує попередній внутрішній Observable, коли надходить нове значення; він ідеальний для пошуку.\\n- mergeMap — він обробляє всі внутрішні Observable паралельно; він придатний для незалежних запитів.\\n- catchError — він перехоплює помилки й повертає резервний Observable.\\n- debounceTime — він затримує emit, доки не пройде пауза; він корисний для полів введення.\\n\\nПриклад коду\\n\\nВисновок\\nОператори RxJS незамінні задля реактивного програмування, вони полегшують керування складними асинхронними сценаріями — автодоповненням, обробкою кліків або послідовними запитами. Їхнє використання покращує читабельність і надійність коду.","import { fromEvent, of } from 'rxjs';\\nimport { map, filter, debounceTime, switchMap, catchError } from 'rxjs/operators';\\n\\nconst input = document.getElementById('search');\\nconst search$ = fromEvent(input, 'input').pipe(\\n  map(event => event.target.value),\\n  filter(value => value.length > 2),\\n  debounceTime(300),\\n  switchMap(query => fetch(\`/api/search?q=\${query}\`).then(res => res.json())),\\n  catchError(err => of({ error: err.message }))\\n);\\n\\nsearch$.subscribe(data => console.log(data));"],[2602,"Є два основні підходи: серверна й клієнтська обробка даних. За серверної пагінації бекенд повертає лише поточну сторінку, а фронтенд надсилає параметри фільтрації й сортування. Клієнтська пагінація придатна для невеликих наборів даних, коли всі дані завантажують одразу й обробляють на боці браузера. Вибір залежить від обсягу даних і від вимог до продуктивності.","Основні підходи до роботи з таблицями\\nРозробляючи фронтенд-застосунки, робота з табличними даними потребує вибору стратегії обробки фільтрації, сортування й пагінації. Є два основні підходи: серверний і клієнтський. Кожний із них має власні переваги й обмеження.\\n\\nСерверна обробка даних\\nЗа серверного підходу всі операції виконують на бекенді. Фронтенд надсилає HTTP-запити з параметрами: номером сторінки, розміром сторінки, полями для сортування, фільтрами. Бекенд повертає лише запитану порцію даних плюс загальну кількість записів.\\n\\nКлієнтська обробка даних\\nЗа клієнтського підходу всі дані завантажують одним запитом, а фільтрацію, сортування й пагінацію виконують у браузері. Це придатно для таблиць із невеликим обсягом даних (до кількох тисяч записів).\\n\\nГібридний підхід\\nЧасто використовують поєднання: початкове завантаження із серверною пагінацією, а потім клієнтську фільтрацію вже завантажених даних. Це дає змогу скоротити кількість запитів, зберігши продуктивність.\\n\\nВибір підходу залежить від обсягу даних, частоти оновлень й вимог до UX. Для великих таблиць (10 000+ записів) серверна пагінація краща. Для невеликих довідкових списків або конфігурацій достатньо клієнтської обробки.","// An example of a request to an API with parameters\\nconst fetchUsers = async (page, pageSize, filters) => {\\n  const params = new URLSearchParams({\\n    page,\\n    pageSize,\\n    sortBy: 'name',\\n    sortOrder: 'asc',\\n    search: filters.search || ''\\n  });\\n  const response = await fetch(\`/api/users?\${params}\`);\\n  const data = await response.json();\\n  return {\\n    items: data.users,\\n    total: data.totalCount\\n  };\\n};\\n\\n// An example of client-side filtering and pagination\\nconst filterAndPaginate = (data, page, pageSize, searchTerm) => {\\n  const filtered = data.filter(item =>\\n    item.name.toLowerCase().includes(searchTerm.toLowerCase())\\n  );\\n  const start = (page - 1) * pageSize;\\n  return {\\n    items: filtered.slice(start, start + pageSize),\\n    total: filtered.length\\n  };\\n};"],[2603,"Redux Observable — middleware для Redux, який використовує RxJS, щоб обробляти асинхронні дії й побічні ефекти. Він дає змогу створювати «епіки» — функції, які приймають потік дій і повертають новий потік дій. Це полегшує роботу зі складними асинхронними сценаріями, як-от скасуванням запитів або debounce.","Що таке Redux Observable?\\nRedux Observable — middleware для Redux, який інтегрує бібліотеку RxJS, щоб керувати побічними ефектами. Замість писати складну логіку у творцях дій або в редюсерах, ви визначаєте «епіки» — функції, які приймають потік усіх дій (action$) і повертають новий потік дій. Це дає змогу обробляти асинхронні операції, як-от HTTP-запити, таймери або WebSocket'и, використовуючи потужні оператори RxJS.\\n\\nЯк він працює?\\nЕпіки — чисті функції, які отримують потік дій і повертають потік дій. Вони не змінюють стану безпосередньо, а лише диспатчать нові дії. Наприклад, можна створити епік, який слухає дію FETCH_USER, робить запит до API й диспатчить FETCH_USER_SUCCESS або FETCH_USER_FAILURE.\\n\\nЧому використовувати Redux Observable?\\nRedux Observable особливо корисний, коли потрібно керувати складними асинхронними потоками, як-от скасуванням запитів, debounce, throttle або поєднанням кількох джерел даних. RxJS надає багатий набір операторів для роботи з часом і подіями, що робить код декларативнішим і простішим для тестування.\\n\\nПриклад використання\\nПрипустімо, у вас є поле пошуку, яке надсилає запити на кожному введенні. Без Redux Observable ви робили б debounce вручну, але з RxJS це робиться просто:\\n\\nТут debounceTime(300) затримує обробку на 300 мс, а switchMap скасовує попередній запит, якщо надійшов новий.\\n\\nВисновок\\nRedux Observable варто застосовувати, коли ваш застосунок потребує складної асинхронної логіки, як-от скасування запитів, поєднання потоків або роботи в реальному часі. Він робить код передбачуванішим і тестованішим, але потребує розуміння RxJS.","import { ofType } from 'redux-observable';\\nimport { ajax } from 'rxjs/ajax';\\nimport { map, switchMap, catchError } from 'rxjs/operators';\\nimport { of } from 'rxjs';\\n\\nconst fetchUserEpic = (action$) =>\\n  action$.pipe(\\n    ofType('FETCH_USER'),\\n    switchMap((action) =>\\n      ajax.getJSON(\`/api/users/\${action.payload}\`).pipe(\\n        map((response) => ({\\n          type: 'FETCH_USER_SUCCESS',\\n          payload: response,\\n        })),\\n        catchError((error) =>\\n          of({\\n            type: 'FETCH_USER_FAILURE',\\n            payload: error.message,\\n          })\\n        )\\n      )\\n    )\\n  );\\n\\nconst searchEpic = (action$) =>\\n  action$.pipe(\\n    ofType('SEARCH'),\\n    debounceTime(300),\\n    switchMap((action) =>\\n      ajax.getJSON(\`/api/search?q=\${action.payload}\`).pipe(\\n        map((response) => ({\\n          type: 'SEARCH_SUCCESS',\\n          payload: response,\\n        }))\\n      )\\n    )\\n  );"],[2604,"Втрата пам'яті виникає, коли глобальний об'єкт зберігає посилання на обробник події, який посилається на видалений DOM-елемент. Щоб цього уникнути, потрібно явно видалити обробник через removeEventListener перед видаленням елемента. Також можна використати слабкі посилання (WeakRef) або очистити посилання в глобальному об'єкті після того, як елемент видалили.","Проблема втрати пам'яті при видаленні DOM-елемента\\nКоли ви видаляєте DOM-елемент із документа, але глобальний об'єкт (наприклад, window або глобальна змінна) і далі зберігає посилання на обробник події, прив'язаний до цього елемента, виникає втрата пам'яті. Обробник події замикається над посиланням на елемент, і збирач сміття не може звільнити пам'ять, оскільки все ще є активне посилання на елемент через ланцюжок: глобальний об'єкт → обробник → елемент.\\n\\nЯк це трапляється на практиці\\nПодивімося на приклад: ви додаєте обробник кліку до кнопки й зберігаєте його в глобальному масиві. Після того як кнопку видалили з DOM, обробник залишається в масиві, тримаючи посилання на видалений елемент.\\n\\nСпособи розв'язання\\n\\n- Явне видалення обробника: перед видаленням елемента викличте removeEventListener, передавши ту саму функцію-обробник.\\n- Очищення глобального посилання: після того як елемент видалили, видаліть обробник із глобального об'єкта (наприклад, встановіть його в null або видаліть із масиву).\\n- Використання WeakRef: у сучасних браузерах можна зберігати слабке посилання на обробник, яке не перешкоджає збиранню сміття.\\n\\nВисновок\\nЩоб запобігати втратам пам'яті, завжди видаляйте обробники подій перед видаленням DOM-елементів, особливо якщо їх зберігають у глобальних структурах даних. Це критично для довгоживучих застосунків (SPA) й у роботі з динамічними інтерфейсами.","const handlers = [];\\nconst button = document.getElementById('myButton');\\nconst handler = () => console.log('click');\\nbutton.addEventListener('click', handler);\\nhandlers.push(handler);\\n// We remove the element\\nbutton.remove();\\n// The handler is still in handlers, so the element is not removed from memory\\n\\n// The solution: we remove the handler before removing the element\\nbutton.removeEventListener('click', handler);\\nbutton.remove();\\n// Or we clear the global reference\\nhandlers = handlers.filter(h => h !== handler);"],[2605,"Так, задля офлайн-режиму запити кешують за допомогою Service Worker і Cache API. Стратегія «Cache First» дає змогу спочатку перевірити кеш і зробити мережевий запит, коли даних немає. Це дає застосункові змогу працювати без інтернету й прискорює завантаження.","Кешування запитів задля офлайн-режиму\\nЩоб вебзастосунок міг працювати без інтернету, використовують поєднання Service Worker і Cache API. Service Worker — скрипт, який працює у фоні й перехоплює мережеві запити. Він дає змогу реалізувати різні стратегії кешування, як-от «Cache First» (спочатку кеш, потім мережа) або «Network First» (спочатку мережа, а кеш при помилці).\\n\\nПриклад реалізації\\n\\nДе це застосовують\\n\\n- Прогресивні вебзастосунки (PWA) для мобільних пристроїв\\n- Застосунки з нестабільним інтернет-з'єднанням (наприклад, карти, новини)\\n- Прискорення завантаження повторних відвідувань\\n\\nВисновок: кешування запитів через Service Worker потрібне, щоб створювати надійні офлайн-застосунки. Воно покращує користувацький досвід і зменшує навантаження на мережу, особливо в умовах поганого з'єднання.","// service-worker.js\\nself.addEventListener('install', (event) => {\\n  event.waitUntil(\\n    caches.open('my-cache-v1').then((cache) => {\\n      return cache.addAll([\\n        '/',\\n        '/styles.css',\\n        '/script.js',\\n        '/offline.html'\\n      ]);\\n    })\\n  );\\n});\\n\\nself.addEventListener('fetch', (event) => {\\n  event.respondWith(\\n    caches.match(event.request).then((cachedResponse) => {\\n      // We return the cache if it is there\\n      if (cachedResponse) {\\n        return cachedResponse;\\n      }\\n      // Otherwise we make a network request\\n      return fetch(event.request).catch(() => {\\n        // If the network is unavailable, we show the offline page\\n        return caches.match('/offline.html');\\n      });\\n    })\\n  );\\n});"],[2606,"У React задля керування станом використовують локальний стан, Context API й бібліотеки на кшталт Redux, MobX і Zustand. Redux заснований на архітектурі Flux: єдиний стор, незмінний стан, чисті функції-редюсери й однонапрямлений потік даних. Дії диспатчать, редюсери створюють новий стан, а компоненти підписуються на зміни.","Підходи до керування станом у React\\nУ React-застосунках стан може бути локальним (useState, useReducer) або глобальним. Задля глобального стану використовують Context API, вбудований у React, або спеціалізовані бібліотеки: Redux, MobX, Zustand, Recoil, Jotai. Вибір залежить від складності застосунку: для простих проєктів достатньо Context API; для великих — Redux або MobX.\\n\\nАрхітектура Redux\\nRedux реалізує патерн Flux із єдиним джерелом істини — стором. Стан доступний лише для читання, а зміни відбуваються через чисті функції-редюсери. Потік даних однонапрямлений: компонент диспатчить дію, дія доходить до редюсера, редюсер створює новий стан, а стор повідомляє підписників.\\n\\nПриклад коду\\n\\nВисновок\\nRedux придатний для великих застосунків із безліччю взаємопов'язаних частин стану, де важливі передбачуваність і зневадження. Для невеликих проєктів краще використовувати Context API або легші бібліотеки, як-от Zustand.","// action types\\nconst ADD_TODO = 'ADD_TODO';\\n\\n// action creator\\nconst addTodo = (text) => ({\\n  type: ADD_TODO,\\n  payload: text\\n});\\n\\n// reducer\\nconst todosReducer = (state = [], action) => {\\n  switch (action.type) {\\n    case ADD_TODO:\\n      return [...state, { text: action.payload, completed: false }];\\n    default:\\n      return state;\\n  }\\n};\\n\\n// store\\nimport { createStore } from 'redux';\\nconst store = createStore(todosReducer);\\n\\n// dispatch\\nstore.dispatch(addTodo('Learn Redux'));"],[2607,"Підняття стану (lifting state up) — патерн у React, за якого стан, спільний для кількох компонентів, переносять у їхнього найближчого спільного предка. Батьківський компонент керує цим станом і передає його дочірнім компонентам через пропси, а також надає функції, щоб його змінювати. Це дає змогу синхронізувати дані між компонентами, не використовуючи глобального стора. Патерн робить потік даних передбачуваним і полегшує зневадження.","Що таке підняття стану?\\nПідняття стану — фундаментальний патерн у React, який використовують, коли два або більше компонентів мають синхронізувати свої дані. Замість зберігати стан у кожному компоненті окремо, його переносять (підіймають) у найближчого спільного батька. Батько стає єдиним джерелом істини й передає дані й колбеки для зміни стану вниз через пропси.\\n\\nЯк це працює?\\nПодивімося на приклад: два компоненти \`TemperatureInput\`, щоб вводити температуру в Цельсіях і у Фаренгейтах. Якби кожний зберігав власний стан, вони не змогли б синхронізуватися. Рішення — підняти стан у компонент \`Calculator\`:\\n\\nТут \`Calculator\` зберігає єдину частину стану (\`temperature\` і \`scale\`) й передає її в обидва \`TemperatureInput\`. Коли значення в будь-якому з полів змінюється, викликають відповідний колбек, який оновлює стан у батькові, й обидва поля перемальовуються синхронно.\\n\\nДе його застосовують?\\nПатерн використовують у будь-якій ситуації, у якій компоненти одного рівня мають обмінюватися даними: формах із залежними полями, списках із фільтрацією, панелях інструментів тощо. Це альтернатива глобальним менеджерам стану (Redux, Context) для простих випадків.\\n\\nВисновок\\nПідняття стану — простий, ефективний спосіб керувати спільними даними в React без зовнішніх бібліотек. Воно робить потік даних однонапрямленим і передбачуваним, що полегшує розуміння й зневадження застосунку. Використовуйте його, коли кілька компонентів потрібно синхронізувати, але потреби в глобальному сторі немає.","function TemperatureInput({ scale, temperature, onTemperatureChange }) {\\n  return (\\n    <fieldset>\\n      <legend>{scale === 'c' ? 'Celsius' : 'Fahrenheit'}</legend>\\n      <input value={temperature}\\n             onChange={(e) => onTemperatureChange(e.target.value)} />\\n    </fieldset>\\n  );\\n}\\n\\nfunction Calculator() {\\n  const [temperature, setTemperature] = useState('');\\n  const [scale, setScale] = useState('c');\\n\\n  const handleCelsiusChange = (value) => {\\n    setTemperature(value);\\n    setScale('c');\\n  };\\n\\n  const handleFahrenheitChange = (value) => {\\n    setTemperature(value);\\n    setScale('f');\\n  };\\n\\n  const celsius = scale === 'f' ? tryConvert(temperature, toCelsius) : temperature;\\n  const fahrenheit = scale === 'c' ? tryConvert(temperature, toFahrenheit) : temperature;\\n\\n  return (\\n    <div>\\n      <TemperatureInput scale=\\"c\\" temperature={celsius} onTemperatureChange={handleCelsiusChange} />\\n      <TemperatureInput scale=\\"f\\" temperature={fahrenheit} onTemperatureChange={handleFahrenheitChange} />\\n    </div>\\n  );\\n}"],[2608,"Валідація багатокрокових форм потребує керування станом кожного кроку плюс загальної валідації на надсиланні. Проблеми включають синхронізацію даних між кроками, обробку повернення назад і складні правила валідації. Тестування включає юніт-тести для кожного кроку, інтеграційні тести для потоку й тести граничних випадків.","Валідація багатокрокових форм — процес перевірки даних на кожній стадії введення, а також на фінальному надсиланні. Основна складність полягає в тому, що дані можуть бути неповними на проміжних кроках, але все одно мають бути коректними задля переходу до наступного кроку. Це потребує гнучкої системи валідації, яка враховує контекст поточного кроку.\\n\\nОсновні проблеми\\n\\n- Синхронізація стану: дані кожного кроку мають бути узгодженими з рештою. Наприклад, якщо на першому кроці обрали країну, то на другому кроці список міст має оновитися.\\n- Повернення назад: користувач може повернутися до попереднього кроку й змінити дані, що може впливати на валідність наступних кроків.\\n- Складні правила: валідація може залежати від даних із різних кроків — наприклад, перевірка віку залежно від обраної ролі.\\n\\nПідходи до реалізації\\nОдин поширений підхід — використати єдиний об'єкт стану для всієї форми й валідувати лише поля поточного кроку. Задля керування станом можна використати бібліотеки на кшталт React Hook Form або Formik. Приклад у React:\\n\\nТестування\\nЩоб тестувати багатокрокові форми, використовуйте:\\n- Юніт-тести: вони перевіряють валідацію кожного кроку в ізоляції.\\n- Інтеграційні тести: вони перевіряють повний потік: переходи між кроками, повернення назад, надсилання форми.\\n- Тести граничних випадків: порожні поля, неправильні формати даних, повторне надсилання.\\n\\nВисновок: багатокрокові форми потребують уважного керування станом і валідацією. Використовуйте спеціалізовані бібліотеки, щоб це полегшити, й проводьте тестування на всіх рівнях, аби уникати регресій.","const [formData, setFormData] = useState({});\\nconst [currentStep, setCurrentStep] = useState(0);\\n\\nconst validateStep = (step) => {\\n  const fields = steps[step].fields;\\n  return fields.every(field => formData[field] !== undefined && formData[field] !== '');\\n};\\n\\nconst handleNext = () => {\\n  if (validateStep(currentStep)) {\\n    setCurrentStep(prev => prev + 1);\\n  }\\n};"],[2609,"Є кілька популярних бібліотек задля валідації форм. Yup і Zod використовують для схем валідації, часто з React Hook Form. Joi — потужна бібліотека для Node.js. Formik надає вбудовану валідацію. Вибір залежить від екосистеми й від вимог проєкту.","Бібліотеки задля валідації форм\\nВалідація форм — ключова частина користувацького досвіду, яка запобігає надсиланню некоректних даних. Є безліч бібліотек, які полегшують цей процес. Найпопулярніші включають Yup, Zod і Joi, а також інтеграції з React Hook Form і Formik.\\n\\nОсновні бібліотеки\\n\\n- Yup — легка бібліотека, щоб створювати схеми валідації; її часто використовують із React Hook Form. Вона підтримує ланцюжки методів і власні повідомлення про помилки.\\n- Zod — сучасна альтернатива Yup із TypeScript-орієнтованим API, яка забезпечує строгу типізацію й кращу продуктивність.\\n- Joi — потужна бібліотека для Node.js, популярна в бекенд-розробці, з багатим набором правил валідації.\\n- React Hook Form — сама по собі не бібліотека валідації, але вона інтегрується з Yup, Zod й іншими, щоб керувати формами й валідацією.\\n- Formik — бібліотека задля керування формами в React; вона має вбудовану валідацію через Yup або через власні функції.\\n\\nПриклад коду з Yup і React Hook Form\\n\\nВисновок\\nВибір бібліотеки залежить від технологічного стека: для React-проєктів із TypeScript краща Zod; для простих форм — Yup; а для бекенду на Node.js — Joi. Ці інструменти прискорюють розробку й покращують надійність застосунку.","import { useForm } from 'react-hook-form';\\nimport { yupResolver } from '@hookform/resolvers/yup';\\nimport * as yup from 'yup';\\n\\nconst schema = yup.object().shape({\\n  email: yup.string().email('Invalid email').required('Required'),\\n  password: yup.string().min(6, 'Min 6 chars').required(),\\n});\\n\\nfunction MyForm() {\\n  const { register, handleSubmit, errors } = useForm({\\n    resolver: yupResolver(schema),\\n  });\\n  const onSubmit = (data) => console.log(data);\\n  return (\\n    <form onSubmit={handleSubmit(onSubmit)}>\\n      <input {...register('email')} />\\n      {errors.email && <p>{errors.email.message}</p>}\\n      <input type=\\"password\\" {...register('password')} />\\n      <button type=\\"submit\\">Submit</button>\\n    </form>\\n  );\\n}"],[2610,"Це питання оцінює ваш досвід відображення даних у користувацькому інтерфейсі. Кандидат має розповісти про створення графіків, таблиць і складних форм. Важливо показати розуміння продуктивності, доступності й зручності таких компонентів.","Досвід відображення даних в UI\\nВідображення даних у користувацькому інтерфейсі — ключова задача фронтенд-розробника. Воно включає створення графіків, таблиць, складних форм й інших візуальних елементів, щоб подавати інформацію. Важливо не лише правильно відобразити дані, а й забезпечити продуктивність, доступність і зручність.\\n\\nОсновні аспекти\\n\\n- Графіки й діаграми: використовують бібліотеки на кшталт Chart.js, D3.js, Recharts або ECharts. Важливо вміти налаштовувати осі, легенди й анімації й обробляти великі обсяги даних.\\n- Таблиці: складні таблиці із сортуванням, фільтрацією, пагінацією й редагуванням осередків. Популярні бібліотеки: React Table, AG Grid, Handsontable.\\n- Складні форми: багатокрокові форми, динамічні поля, валідація, власні елементи керування (наприклад, вибір дати або автодоповнення).\\n\\nПриклад коду: проста таблиця із сортуванням у React\\n\\nВисновок\\nДосвід відображення даних в UI потрібний, щоб створювати інформативні, зручні інтерфейси. Застосовуйте спеціалізовані бібліотеки для складних компонентів й завжди враховуйте продуктивність у роботі з великими обсягами даних.","import React, { useState } from 'react';\\n\\nconst Table = ({ data }) => {\\n  const [sortField, setSortField] = useState(null);\\n  const [sortOrder, setSortOrder] = useState('asc');\\n\\n  const sortedData = [...data].sort((a, b) => {\\n    if (sortField) {\\n      const compare = a[sortField] > b[sortField] ? 1 : -1;\\n      return sortOrder === 'asc' ? compare : -compare;\\n    }\\n    return 0;\\n  });\\n\\n  const handleSort = (field) => {\\n    setSortOrder(sortField === field && sortOrder === 'asc' ? 'desc' : 'asc');\\n    setSortField(field);\\n  };\\n\\n  return (\\n    <table>\\n      <thead>\\n        <tr>\\n          <th onClick={() => handleSort('name')}>Name</th>\\n          <th onClick={() => handleSort('age')}>Age</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        {sortedData.map((row, idx) => (\\n          <tr key={idx}>\\n            <td>{row.name}</td>\\n            <td>{row.age}</td>\\n          </tr>\\n        ))}\\n      </tbody>\\n    </table>\\n  );\\n};\\n\\nexport default Table;"],[2611,"У JavaScript і React для роботи з датами часто використовують бібліотеки moment.js, date-fns і dayjs. Moment.js надає широку функціональність, але вважається застарілою. date-fns пропонує модульні функції для роботи з датами. dayjs — легка альтернатива зі схожим API.","Бібліотеки для роботи з датами в JS/React\\nРобота з датами в JavaScript може бути важкою через особливості часових поясів, форматування й обчислень. Щоб полегшити ці задачі, розробники використовують спеціалізовані бібліотеки. Найпопулярніші з них: moment.js, date-fns і dayjs.\\n\\nMoment.js\\nMoment.js довго була стандартом для роботи з датами. Вона надає зручний API, щоб парсити, форматувати, маніпулювати й відображати дати. Однак бібліотека вважається застарілою через свій великий розмір і проблеми з продуктивністю. Розробники рекомендують переходити на сучасніші альтернативи.\\n\\ndate-fns\\ndate-fns — модульна бібліотека, яка дає змогу імпортувати лише потрібні функції, що зменшує розмір бандла. Вона пропонує чисті функції, без мутації початкових об'єктів. date-fns добре підходить для сучасних проєктів, де важливі продуктивність і tree shaking.\\n\\nDay.js\\nDay.js — легка бібліотека (приблизно 2 КБ), яка має API, схожий на moment.js. Вона підтримує плагіни, щоб розширювати функціональність, як-от відносний час або часові пояси. Day.js ідеальна для проєктів, де потрібний мінімальний розмір бандла.\\n\\nВисновок\\nВибір бібліотеки залежить від вимог проєкту: для великих застосунків з акцентом на продуктивності використовуйте date-fns; для невеликих проєктів із простими задачами — dayjs; а щоб підтримувати старий код — moment.js. У React ці бібліотеки часто застосовують, щоб форматувати дати в компонентах, працювати з календарями або відображати часові позначки.","// An example of the usage of moment.js\\nconst moment = require('moment');\\nconst now = moment();\\nconsole.log(now.format('YYYY-MM-DD')); // 2025-03-27\\n\\n// An example of the usage of date-fns\\nimport { format, addDays } from 'date-fns';\\nconst today = new Date();\\nconst tomorrow = addDays(today, 1);\\nconsole.log(format(tomorrow, 'yyyy-MM-dd')); // 2025-03-28\\n\\n// An example of the usage of dayjs\\nimport dayjs from 'dayjs';\\nconst now = dayjs();\\nconsole.log(now.format('YYYY-MM-DD')); // 2025-03-27"],[2612,"Щоб працювати зі складними таблицями, зазвичай використовують бібліотеки на кшталт React Table або AG Grid. Фільтрацію й сортування можна виконувати на клієнті або на сервері. Редагування реалізують через керування станом рядків й осередків. Важливо належно організувати стан таблиці й обробку змін.","Базові концепції\\nСкладні таблиці потребують керування станом даних, фільтрації, сортування й редагування. Це зазвичай реалізують за допомогою спеціалізованих бібліотек, які беруть на себе логіку рендерингу й обробки подій.\\n\\nФільтрація й сортування\\nФільтрація може бути клієнтською (для невеликих наборів даних) або серверною (для великих обсягів). Сортування зазвичай виконують за одним або за кількома стовпцями. Приклад із React Table:\\n\\nРедагування\\nРедагування осередків або рядків потребує керування станом редагування. Можна використати вбудоване (inline) редагування, де осередок стає полем введення на кліку. Приклад у React:\\n\\nВисновок\\nВикористання готових бібліотек для складних таблиць прискорює розробку й зменшує кількість багів. Вони надають гнучкі API задля кастомізації й інтеграції з будь-яким керуванням станом. Рекомендують застосовувати такі рішення для таблиць із великою кількістю даних і зі складною логікою взаємодії.","import { useTable, useFilters, useSortBy } from 'react-table';\\n\\nfunction Table({ columns, data }) {\\n  const {\\n    getTableProps,\\n    getTableBodyProps,\\n    headerGroups,\\n    rows,\\n    prepareRow,\\n  } = useTable(\\n    { columns, data },\\n    useFilters,\\n    useSortBy\\n  );\\n\\n  return (\\n    <table {...getTableProps()}>\\n      <thead>\\n        {headerGroups.map(headerGroup => (\\n          <tr {...headerGroup.getHeaderGroupProps()}>\\n            {headerGroup.headers.map(column => (\\n              <th {...column.getHeaderProps(column.getSortByToggleProps())}>\\n                {column.render('Header')}\\n                <span>{column.isSorted ? (column.isSortedDesc ? ' 🔽' : ' 🔼') : ''}</span>\\n                <div>{column.canFilter ? column.render('Filter') : null}</div>\\n              </th>\\n            ))}\\n          </tr>\\n        ))}\\n      </thead>\\n      <tbody {...getTableBodyProps()}>\\n        {rows.map(row => {\\n          prepareRow(row);\\n          return (\\n            <tr {...row.getRowProps()}>\\n              {row.cells.map(cell => (\\n                <td {...cell.getCellProps()}>{cell.render('Cell')}</td>\\n              ))}\\n            </tr>\\n          );\\n        })}\\n      </tbody>\\n    </table>\\n  );\\n}\\n\\nfunction EditableCell({ value: initialValue, row, column, updateMyData }) {\\n  const [value, setValue] = React.useState(initialValue);\\n  const onBlur = () => updateMyData(row.index, column.id, value);\\n\\n  return (\\n    <input\\n      value={value}\\n      onChange={e => setValue(e.target.value)}\\n      onBlur={onBlur}\\n    />\\n  );\\n}"],[2613,"Серверний стан — дані, які зберігаються на сервері й потребують асинхронних запитів, щоб їх отримати або оновити (наприклад, список користувачів). Клієнтський стан — дані, які існують лише в переглядачі й не синхронізуються із сервером (наприклад, стан UI, форма введення). Основна різниця — у джерелі істини: серверним станом керує сервер, а клієнтським — локальне сховище. Для серверного стану часто використовують бібліотеки на кшталт React Query або RTK Query, а для клієнтського — Redux чи Context API.","Різниця між серверним і клієнтським керуванням станом\\nУ сучасних вебзастосунках дані можуть зберігатися і на сервері, і на клієнті. Розуміння різниці між цими підходами критично важливе задля архітектури застосунку, продуктивності й легкості підтримки.\\n\\nКлієнтський стан\\nКлієнтський стан — дані, які існують лише в переглядачі користувача й не потребують синхронізації із сервером. Приклади:\\n- Поточний обраний елемент у списку, що розкривається\\n- Стан модального вікна (відкрите/закрите)\\n- Дані форми, яку ще не надіслано\\n- Тема оформлення (світла/темна)\\n\\nЩоб керувати клієнтським станом, часто використовують глобальні сховища на кшталт Redux, Zustand або Context API. Ці дані не потребують асинхронних операцій задля читання й запису — вони доступні одразу.\\n\\nСерверний стан\\nСерверний стан — дані, які зберігаються на сервері й потребують асинхронних запитів (наприклад, через REST API або GraphQL), щоб їх отримати, оновити чи вилучити. Приклади:\\n- Список товарів в інтернет-крамниці\\n- Профіль користувача\\n- Історія замовлень\\n\\nСерверний стан не перебуває під повним контролем клієнта: інші користувачі або фонові процеси можуть змінити дані на сервері. Тому клієнт має вміти синхронізуватися із сервером, обробляти стани завантаження й помилок і кешувати дані задля оптимізації.\\n\\nКлючові відмінності\\n\\n- Джерело істини: для серверного стану — сервер, для клієнтського — локальне сховище.\\n- Синхронізація: серверний стан потребує асинхронних запитів й обробки кешу; клієнтський — синхронний.\\n- Керування: серверним станом часто керують спеціалізовані бібліотеки (React Query, SWR, RTK Query), а клієнтським — Redux, Zustand або Context.\\n- Кешування: серверний стан потребує стратегій інвалідації кешу, а клієнтський — ні.\\n\\nВисновок: поділ на серверний і клієнтський стан допомагає уникати надлишкових запитів до сервера й робить архітектуру простішою. Використовуйте спеціалізовані бібліотеки для серверного стану, щоб автоматизувати кешування й синхронізацію, а для клієнтського — легкі рішення, які не потребують асинхронності.","// An example of client state with Redux Toolkit\\nconst uiSlice = createSlice({\\n  name: 'ui',\\n  initialState: { isModalOpen: false },\\n  reducers: {\\n    toggleModal(state) {\\n      state.isModalOpen = !state.isModalOpen;\\n    }\\n  }\\n});\\n// The change happens instantly, without requests to the server\\n\\n// An example of server state with React Query\\nfunction useProducts() {\\n  return useQuery({\\n    queryKey: ['products'],\\n    queryFn: () => fetch('/api/products').then(res => res.json()),\\n    staleTime: 5 * 60 * 1000, // the data counts as fresh for 5 minutes\\n  });\\n}\\n// The data is loaded from the server asynchronously and cached"],[2614,"Стандартний фронтенд-стек включає HTML, CSS, JavaScript, фреймворки (React, Vue, Angular), бандлери (Webpack, Vite) й менеджери пакетів (npm, yarn). Telegram Mini Apps — вебзастосунки, які запускають усередині Telegram, з обмеженим доступом до API пристрою, але зі змогою взаємодіяти з користувачем через бота. Особливості: використання Telegram Web App SDK, робота через iframe, обмежений розмір і потреба адаптуватися до мобільних пристроїв.","Стек frontend-розробки\\nТиповий фронтенд-стек включає кілька ключових компонентів. Основа — HTML, CSS і JavaScript, які забезпечують структуру, стилізацію й логіку. Щоб полегшити розробку, використовують фреймворки на кшталт React, Vue.js або Angular. Збирачі модулів — наприклад, Webpack чи Vite — допомагають поєднати файли й оптимізувати продуктивність. Менеджери пакетів (npm, yarn) керують залежностями. Додатково застосовують препроцесори CSS (Sass, Less) й інструменти задля тестування (Jest, Cypress).\\n\\nTelegram Mini Apps\\nTelegram Mini Apps — вебзастосунки, які запускають усередині месенджера Telegram через особливий інтерфейс. Вони працюють в iframe і взаємодіють з користувачем через бота. Основні особливості:\\n- Використання Telegram Web App SDK задля доступу до функцій Telegram (наприклад, надсилання даних, робота з клавіатурою).\\n- Обмежений розмір застосунку (до 1 МБ для статичних файлів).\\n- Потреба адаптуватися до мобільних пристроїв, адже більшість користувачів заходять зі смартфонів.\\n- Відсутність прямого доступу до API пристрою (камери, геолокації) без дозволу користувача.\\n\\nПриклад простого Mini App у React:\\n\\nУ цьому прикладі SDK використовують, щоб ініціалізувати застосунок і відобразити кнопку. Mini Apps часто застосовують для ігор, опитувань, крамниць або сервісів, де потрібний швидкий доступ без установлення.\\n\\nВисновок: знання фронтенд-стека потрібне, щоб створювати сучасні вебзастосунки, а Telegram Mini Apps — нішева, але зростаюча область, де важливо враховувати обмеження платформи й використовувати спеціалізовані SDK.","import React, { useEffect } from 'react';\\nimport WebApp from '@twa-dev/sdk';\\n\\nfunction App() {\\n  useEffect(() => {\\n    WebApp.ready();\\n    WebApp.MainButton.setText('Click me');\\n    WebApp.MainButton.show();\\n  }, []);\\n\\n  return <h1>Hello, Telegram!</h1>;\\n}\\n\\nexport default App;"],[2615,"Оператори RxJS поділяють на кілька категорій: оператори створення (of, from, interval), перетворення (map, switchMap, mergeMap), фільтрації (filter, take, debounceTime), поєднання (combineLatest, merge, forkJoin), а також оператори обробки помилок (catchError, retry) й утиліти (tap, delay). Кожна група розв'язує власну задачу в роботі з Observable.","Основні категорії операторів RxJS\\nОператори RxJS — функції, які дають змогу маніпулювати потоками даних, створеними Observable. Їх поділяють на кілька груп залежно від задачі, яку вони виконують. Розуміння цих категорій допомагає писати чистий, декларативний код задля асинхронних операцій.\\n\\nОператори створення\\nЦі оператори створюють нові Observable з різних джерел: значень, масивів, подій або промісів.\\n\\nОператори перетворення\\nВони змінюють кожне значення в потоці або перетворюють один Observable на інший.\\n\\nОператори фільтрації\\nВони дають змогу пропускати лише ті значення, які задовольняють умову, або обмежувати кількість значень.\\n\\nОператори поєднання\\nВони об'єднують кілька Observable в один.\\n\\nОператори обробки помилок й утиліти\\nВони дають змогу обробляти помилки й виконувати побічні ефекти.\\n\\nВисновок: оператори RxJS — потужний інструмент для роботи з асинхронними потоками. Їхнє належне використання дає змогу писати декларативний, легко тестований код, що легко підтримувати, особливо в застосунках із великою кількістю подій, запитів або потоків даних.","import { of, from, interval } from 'rxjs';\\n\\nof(1, 2, 3).subscribe(console.log); // 1, 2, 3\\nfrom([4, 5, 6]).subscribe(console.log); // 4, 5, 6\\ninterval(1000).subscribe(console.log); // 0, 1, 2, ... every second\\n\\nimport { map, switchMap } from 'rxjs/operators';\\n\\nof(1, 2, 3).pipe(\\n  map(x => x * 10)\\n).subscribe(console.log); // 10, 20, 30\\n\\n// switchMap cancels the previous inner Observable\\nfromEvent(input, 'input').pipe(\\n  switchMap(value => fetchData(value))\\n).subscribe(console.log);\\n\\nimport { filter, take, debounceTime } from 'rxjs/operators';\\n\\nof(1, 2, 3, 4, 5).pipe(\\n  filter(x => x % 2 === 0),\\n  take(2)\\n).subscribe(console.log); // 2, 4\\n\\nfromEvent(input, 'input').pipe(\\n  debounceTime(300)\\n).subscribe(console.log); // it waits 300 ms after the last input\\n\\nimport { combineLatest, merge, forkJoin } from 'rxjs';\\n\\ncombineLatest([obs1$, obs2$]).subscribe(([val1, val2]) => {\\n  console.log(val1, val2);\\n});\\n\\nmerge(obs1$, obs2$).subscribe(console.log); // the values from both streams as they appear\\n\\nforkJoin({ a: obs1$, b: obs2$ }).subscribe(console.log); // it waits for all of them to complete\\n\\nimport { catchError, retry, tap } from 'rxjs/operators';\\n\\nhttp$.pipe(\\n  retry(3),\\n  catchError(err => of('fallback')),\\n  tap(value => console.log('Received:', value))\\n).subscribe(console.log);"],[2616,"Контрольований input у React — елемент, значення якого зберігається у стані компонента й оновлюється через обробник onChange. Значення input беруть зі стану, а не з DOM. Це дає React змогу повністю контролювати введення даних. Приклад: \`<input value={value} onChange={e => setValue(e.target.value)} />\`.","Що таке контрольований input?\\nКонтрольований input — елемент форми, значенням якого керує стан React-компонента. Замість того щоб спиратися на внутрішній стан DOM, React бере на себе керування значенням поля введення через властивість \`value\` й обробник \`onChange\`. Це робить поведінку форми передбачуваною й легкою задля тестування.\\n\\nЯк це працює?\\nНа кожній зміні тексту в input викликають функцію \`onChange\`, яка оновлює стан компонента. Далі React перемальовує компонент, й input отримує нове значення зі стану. Отже, джерелом істини є стан React, а не DOM.\\n\\nПриклад коду\\n\\nДе це застосовують?\\nКонтрольовані компоненти використовують у формах, де потрібна валідація, динамічне оновлення інших полів або надсилання даних на сервер. Вони дають повний контроль над введенням, що полегшує реалізацію складної логіки.\\n\\nВисновок\\nВикористовуйте контрольований input, коли значенням поля треба керувати через React — наприклад, задля валідації або для інтеграції з іншими компонентами. Це стандартний підхід у React-застосунках.","import React, { useState } from 'react';\\n\\nfunction ControlledInput() {\\n  const [text, setText] = useState('');\\n\\n  const handleChange = (event) => {\\n    setText(event.target.value);\\n  };\\n\\n  return (\\n    <input\\n      type=\\"text\\"\\n      value={text}\\n      onChange={handleChange}\\n    />\\n  );\\n}"],[2617,"Щоб отримати доступ до значення неконтрольованого input у React, використовують хук useRef. Створіть ref за допомогою useRef і передайте його в атрибут ref елемента input. Далі значення можна отримати через inputRef.current.value — наприклад, коли форму надсилають або на кліку по кнопці.","Неконтрольовані компоненти в React\\nУ React компоненти можуть бути контрольованими або неконтрольованими. Неконтрольовані компоненти зберігають свій стан у DOM, а не в стані React. Це зручно, коли не потрібно відстежувати кожну зміну введення, а треба отримати значення лише в певний момент — наприклад, коли форму надсилають.\\n\\nВикористання useRef\\nЗадля доступу до DOM-елемента неконтрольованого input використовують хук \`useRef\`. Він створює об'єкт ref, який можна прив'язати до елемента через атрибут \`ref\`. Після цього значення input доступне через \`ref.current.value\`.\\n\\nПриклад коду\\n\\nУ цьому прикладі input не контролює React — його значенням керує переглядач. Коли форму надсилають, ми отримуємо значення через ref.\\n\\nКоли це застосовувати\\nНеконтрольовані компоненти з ref зручні для простих форм, для інтеграції з не-React-кодом або коли валідація в реальному часі не потрібна. Однак для складних форм із динамічною валідацією краще використовувати контрольовані компоненти.","import React, { useRef } from 'react';\\n\\nfunction MyForm() {\\n  const inputRef = useRef(null);\\n\\n  const handleSubmit = (e) => {\\n    e.preventDefault();\\n    alert('The value: ' + inputRef.current.value);\\n  };\\n\\n  return (\\n    <form onSubmit={handleSubmit}>\\n      <input type=\\"text\\" ref={inputRef} defaultValue=\\"\\" />\\n      <button type=\\"submit\\">Send</button>\\n    </form>\\n  );\\n}"],[2618,"Атрибут key допомагає React ідентифікувати елементи списку на оновленні. Він дає React змогу мінімізувати перемалювання, зіставляючи старі й нові елементи. Індекс масиву можна використовувати як key лише тоді, коли список статичний і не змінюється. У динамічних списках це може призвести до помилок у стані й у продуктивності.","Призначення атрибута key\\nАтрибут \`key\` у React використовують, щоб ідентифікувати кожний елемент у списку під час рендерингу. Він допомагає алгоритму звірення оновлювати DOM ефективно, визначаючи, які елементи додали, вилучили або змінили. Без унікального ключа React може перемалювати весь список, що знижує продуктивність.\\n\\nЧому індекс масиву — погана ідея?\\nВикористання індексу масиву як ключа може призвести до проблем, якщо список динамічний: елементи додають, вилучають або переупорядковують. Наприклад, коли елемент вилучають із середини списку, індекси зсуваються, і React може зіставити старі й нові елементи неправильно, що спричинить помилки в стані (наприклад, втрату фокусу в input).\\n\\nКоли можна використовувати індекс?\\nІндекс можна використовувати лише для статичних списків, які не змінюються після рендерингу (наприклад, список констант). У решті випадків краще застосовувати унікальні ідентифікатори з даних.\\n\\nВисновок: використовуйте унікальні, стабільні ключі для динамічних списків, щоб уникати багів й забезпечити високу продуктивність React-застосунків.","// Bad: the index as the key\\n{items.map((item, index) => <li key={index}>{item}</li>)}\\n\\n// Good: a unique id\\n{items.map(item => <li key={item.id}>{item.name}</li>)}"],[2619,"Для роботи зі стилями я використовував препроцесори Sass і Less, методологію BEM для іменування класів, CSS Modules для ізоляції стилів у компонентах і CSS-in-JS бібліотеки, як-от styled-components. Ці інструменти допомагають організувати код, уникати конфліктів і прискорювати розробку.","Інструменти для роботи зі стилями\\nУ сучасній веброзробці стилізація виходить за межі звичайного CSS. Щоб покращити ефективність і підтримуваність коду, використовують різні інструменти й підходи. Розглянемо основні.\\nПрепроцесори\\nSass і Less — це препроцесори, які розширюють можливості CSS. Вони додають змінні, вкладеність, міксини й функції, що робить код модульнішим і зручнішим для повторного використання.\\n\\nМетодології\\nBEM (Block Element Modifier) — методологія іменування класів, яка допомагає структурувати CSS і уникати конфліктів. Кожен клас описує роль елемента: блок, елемент або модифікатор.\\n\\nCSS Modules\\nCSS Modules генерують унікальні імена класів автоматично, що не дає їм перетинатися між різними компонентами. Це особливо корисно в React-застосунках.\\n\\nCSS-in-JS\\nБібліотеки, як-от styled-components, дозволяють писати CSS прямо всередині JavaScript. Це дає можливість використовувати динамічні стилі на основі props і стану.\\n\\nВисновок: вибір інструмента залежить від проєкту. Для великих проєктів із командою підходять Sass і BEM; для компонентних архітектур — CSS Modules або styled-components. Головне — тримати стилі читабельними й масштабованими.","// An example in Sass\\n$primary-color: #3498db;\\n\\n.button {\\n  background-color: $primary-color;\\n  &:hover {\\n    background-color: darken($primary-color, 10%);\\n  }\\n}\\n\\n<div class=\\"card card--featured\\">\\n  <h2 class=\\"card__title\\">A heading</h2>\\n  <p class=\\"card__text\\">Some text</p>\\n</div>\\n\\n// styles.module.css\\n.button {\\n  background: blue;\\n}\\n\\n// Component.jsx\\nimport styles from './styles.module.css';\\n<button className={styles.button}>Click</button>\\n\\nimport styled from 'styled-components';\\n\\nconst Button = styled.button\`\\n  background: \${props => props.primary ? 'blue' : 'gray'};\\n  color: white;\\n\`;"],[2620,"Кастомний хук useFetch інкапсулює логіку HTTP-запиту. Він повертає дані, прапорець завантаження й об'єкт помилки. Використовуйте useState, щоб зберігати стани, й useEffect, щоб виконувати запит, коли URL змінюється. Це полегшує повторне використання коду й робить компоненти чистішими.","Що таке useFetch і для чого він потрібний\\nКастомний хук useFetch — функція, яка обгортає логіку виконання HTTP-запиту й керування його станами (завантаження, успіх, помилка). Замість того щоб дублювати код із fetch, useState і useEffect у кожному компоненті, ви створюєте один хук, який можна використовувати повторно. Це покращує читність, тестованість й легкість підтримки коду.\\n\\nЯк реалізувати useFetch?\\nХук приймає URL і необов'язкові параметри запиту. Усередині він використовує useState, щоб зберігати дані, стан завантаження й помилку, й useEffect, щоб виконувати запит, коли URL змінюється. Важливо обробити скасування запиту (очищення), аби уникати втрат пам'яті й оновлення стану після того, як компонент демонтували.\\n\\nЯк використовувати хук у компоненті?\\nПросто викличте useFetch із потрібним URL і деструктуруйте повернені значення. Залежно від станів можна показати спінер, повідомлення про помилку або відобразити дані.\\n\\nВисновок\\nКастомний хук useFetch — потужний патерн, щоб централізувати логіку HTTP-запитів у React-застосунках. Він зменшує дублювання коду, покращує читність і полегшує тестування. Використовуйте його всюди, де дані треба отримувати з API, особливо у великих проєктах із безліччю запитів.","import { useState, useEffect } from 'react';\\n\\nfunction useFetch(url, options = {}) {\\n  const [data, setData] = useState(null);\\n  const [loading, setLoading] = useState(true);\\n  const [error, setError] = useState(null);\\n\\n  useEffect(() => {\\n    let cancelled = false;\\n    setLoading(true);\\n    setError(null);\\n\\n    fetch(url, options)\\n      .then(res => {\\n        if (!res.ok) throw new Error(\`HTTP error! status: \${res.status}\`);\\n        return res.json();\\n      })\\n      .then(json => {\\n        if (!cancelled) {\\n          setData(json);\\n          setLoading(false);\\n        }\\n      })\\n      .catch(err => {\\n        if (!cancelled) {\\n          setError(err.message);\\n          setLoading(false);\\n        }\\n      });\\n\\n    return () => { cancelled = true; };\\n  }, [url]);\\n\\n  return { data, loading, error };\\n}\\n\\nfunction UserList() {\\n  const { data, loading, error } = useFetch('https://api.example.com/users');\\n\\n  if (loading) return <div>Loading...</div>;\\n  if (error) return <div>Error: {error}</div>;\\n\\n  return (\\n    <ul>\\n      {data.map(user => <li key={user.id}>{user.name}</li>)}\\n    </ul>\\n  );\\n}"],[2621,"Оптимістичне оновлення — техніка, за якої інтерфейс оновлюють одразу після дії користувача, не чекаючи на відповідь сервера. Це робить застосунок відгукливішим. Щоб індикувати фонове оновлення, можна використати спінери, тости або часові позначки. Якщо запит закінчується помилкою, зміни відкочують і показують користувачеві сповіщення.","Що таке оптимістичні оновлення?\\nОптимістичне оновлення — підхід, за якого користувацький інтерфейс (UI) оновлюють одразу після виконання дії, виходячи з припущення, що запит до сервера буде успішним. Це покращує відчуття швидкості застосунку, адже користувач не чекає на відповідь від сервера. Однак, якщо запит закінчується помилкою, зміни треба відкотити й сповістити користувача.\\n\\nЯк індикувати фонове оновлення?\\nЩоб індикувати фонове оновлення, можна використати кілька способів:\\n- Спінери або смужки прогресу — вони показують, що операція триває.\\n- Тости або сповіщення — вони повідомляють про успіх чи помилку після завершення.\\n- Часові позначки — вони показують, коли дані оновлювали останнього разу.\\n- Блокування повторних дій — воно запобігає повторним надсиланням до завершення запиту.\\n\\nПриклад реалізації в React\\n\\nВисновок\\nОптимістичні оновлення варто застосовувати в застосунках, де важлива відгукливість інтерфейсу — наприклад, у соціальних мережах або в месенджерах. Індикація фонового оновлення допомагає користувачеві зрозуміти стан системи й уникати плутанини, коли можливі помилки.","import { useState } from 'react';\\n\\nfunction TodoApp() {\\n  const [todos, setTodos] = useState([]);\\n  const [loading, setLoading] = useState(false);\\n\\n  const addTodo = async (text) => {\\n    const optimisticTodo = { id: Date.now(), text, completed: false };\\n    setTodos(prev => [...prev, optimisticTodo]);\\n    setLoading(true);\\n\\n    try {\\n      const response = await fetch('/api/todos', {\\n        method: 'POST',\\n        body: JSON.stringify({ text }),\\n      });\\n      if (!response.ok) throw new Error('Failed');\\n      const savedTodo = await response.json();\\n      setTodos(prev => prev.map(t => t.id === optimisticTodo.id ? savedTodo : t));\\n    } catch {\\n      setTodos(prev => prev.filter(t => t.id !== optimisticTodo.id));\\n      alert('An error while adding the task');\\n    } finally {\\n      setLoading(false);\\n    }\\n  };\\n\\n  return (\\n    <div>\\n      {loading && <span>Saving...</span>}\\n      <ul>{todos.map(t => <li key={t.id}>{t.text}</li>)}</ul>\\n    </div>\\n  );\\n}"],[2622,"SWR використовує стратегію stale-while-revalidate, яка може призводити до відображення застарілих даних, поки відбувається оновлення. Проблеми виникають із частими мутаціями даних, коли кеш не встигає оновитися вчасно, або коли повторної валідації немає. Також можливі конфлікти під час паралельних запитів і неправильна робота оптимістичних оновлень.","Проблеми актуальності даних у SWR\\nSWR (stale-while-revalidate) — стратегія кешування, за якої спочатку показують закешовані (можливо, застарілі) дані, а потім у фоні виконують запит на оновлення. Це може призводити до ситуацій, у яких користувач бачить неактуальну інформацію.\\n\\nОсновні нюанси\\n\\n- Затримка оновлення: якщо дані змінюються часто, користувач може бачити застарілі дані, доки повторна валідація не завершиться.\\n- Відсутність автоматичної повторної валідації: за замовчуванням SWR не оновлює дані, якщо вікно не у фокусі або зазначений час не минув. Це може призводити до тривалого відображення застарілих даних.\\n- Конфлікти під час мутацій: з оптимістичними оновленнями (коли UI оновлюють до відповіді сервера) можливі розбіжності, якщо сервер поверне помилку або інші дані.\\n- Проблеми з паралельними запитами: якщо кілька компонентів запитують ті самі дані, SWR може створити кілька запитів, що збільшує навантаження й може призводити до неузгодженості.\\n\\nПриклад коду\\n\\nЯк мінімізувати проблеми\\n\\n- Налаштуйте \`refreshInterval\` задля періодичного оновлення.\\n- Використовуйте \`mutate\` задля ручного оновлення після мутацій.\\n- Увімкніть \`revalidateOnFocus\` і \`revalidateOnReconnect\`.\\n- Для критичних даних використовуйте \`dedupingInterval\`, щоб запобігти дублюванню запитів.\\n\\nВисновок: SWR зручна, щоб кешувати й швидко відображати дані, але вона потребує уважного налаштування параметрів валідації й обробки мутацій, аби уникати проблем з актуальністю. Застосовуйте її в проєктах, де невелика затримка в оновленні даних припустима, й поєднуйте її з ручною синхронізацією для критичних операцій.","import useSWR from 'swr';\\n\\nfunction Profile() {\\n  const { data, error } = useSWR('/api/user', fetcher, {\\n    revalidateOnFocus: true,\\n    refreshInterval: 5000, // an update every 5 seconds\\n  });\\n\\n  if (error) return <div>A loading error</div>;\\n  if (!data) return <div>Loading...</div>;\\n  return <div>Hello, {data.name}</div>;\\n}"],[2623,"Щоб типізувати компоненти з HTML-атрибутами, використовуйте інтерфейси на кшталт React.HTMLAttributes або розширюйте їх. Рефи типізують через React.RefObject або через useRef із зазначеним типом елемента. Це забезпечує типову безпеку в роботі з DOM і з пропсами.","Типізація компонентів з HTML-атрибутами й рефами\\nУ React, коли створюють компоненти, які обгортають нативні HTML-елементи, важливо належно типізувати пропси, щоб зберегти підтримку стандартних атрибутів (наприклад, className, id, onClick). TypeScript надає вбудовані типи на кшталт React.HTMLAttributes і React.InputHTMLAttributes, які можна розширювати, щоб додавати власні пропси. Рефи використовують задля прямого доступу до DOM-елементів, і їх треба типізувати за допомогою React.RefObject або React.MutableRefObject.\\n\\nПриклад типізації компонента з HTML-атрибутами\\nНехай ми створюємо компонент CustomInput, який приймає всі стандартні атрибути input плюс додатковий проп label. Ми використовуємо перетин типів:\\n\\nТепер компонент приймає всі атрибути input (placeholder, value, onChange тощо) плюс label.\\n\\nТипізація рефів\\nРефи типізують за допомогою дженерика в useRef. Наприклад, задля доступу до input:\\n\\nТип HTMLInputElement гарантує, що ми можемо викликати методи, специфічні для input (focus, select).\\n\\nПередавання рефів у дочірні компоненти\\nЩоб передати ref у функційний компонент, використовуйте React.forwardRef:\\n\\nЦе дає батьківському компонентові змогу керувати фокусом або значенням дочірнього input.\\n\\nВисновок\\nТипізація HTML-атрибутів і рефів у React із TypeScript покращує надійність коду, запобігаючи помилкам типів у роботі з DOM. Використовуйте вбудовані типи React і forwardRef задля гнучкого передавання рефів. Це особливо корисно у великих проєктах із безліччю UI-компонентів.","import React from 'react';\\n\\ninterface CustomInputProps extends React.InputHTMLAttributes<HTMLInputElement> {\\n  label: string;\\n}\\n\\nconst CustomInput: React.FC<CustomInputProps> = ({ label, ...inputProps }) => {\\n  return (\\n    <div>\\n      <label>{label}</label>\\n      <input {...inputProps} />\\n    </div>\\n  );\\n};\\n\\nimport React, { useRef } from 'react';\\n\\nconst MyComponent: React.FC = () => {\\n  const inputRef = useRef<HTMLInputElement>(null);\\n\\n  const focusInput = () => {\\n    inputRef.current?.focus();\\n  };\\n\\n  return (\\n    <div>\\n      <input ref={inputRef} type=\\"text\\" />\\n      <button onClick={focusInput}>Focus</button>\\n    </div>\\n  );\\n};\\n\\nconst FancyInput = React.forwardRef<HTMLInputElement, { placeholder: string }>(\\n  (props, ref) => {\\n    return <input ref={ref} placeholder={props.placeholder} />;\\n  }\\n);\\n\\n// The usage\\nconst parentRef = useRef<HTMLInputElement>(null);\\n<FancyInput ref={parentRef} placeholder=\\"Type here\\" />;"],[2624,"Якщо тип компонента змінився (наприклад, із div на span або з одного класу на інший), React повністю демонтує старий компонент і монтує новий, навіть якщо зазначено той самий key. Стан не зберігається, адже це різні типи. Key допомагає зберегти стан лише тоді, коли компоненти того самого типу переупорядковують або оновлюють.","Поведінка React, коли тип компонента змінюється\\nReact використовує тип компонента як основний ідентифікатор задля порівняння під час звірення. Якщо тип елемента змінюється (наприклад, \`<div>\` замінюють на \`<span>\` або один функційний компонент на інший), React вважає, що це цілковито різні елементи, й виконує повне демонтування старого й монтування нового. Це означає, що весь локальний стан, ефекти й DOM-вузли попереднього компонента знищують.\\n\\nРоль key\\nАтрибут \`key\` допомагає React ідентифікувати елементи серед компонентів того самого типу (наприклад, у списку). Однак, коли тип компонента змінюється, key не впливає на рішення React: тип має пріоритет. Навіть якщо зазначено той самий key, React усе одно створить компонент заново, адже типи різні.\\n\\nПриклад\\n\\nКоли key допомагає\\nKey ефективний, коли тип компонента не змінюється, а його позиція в списку — так, або коли елементи додають чи вилучають. Наприклад, у сортуванні масиву компонентів того самого типу key дає React змогу зберегти стан кожного елемента, зіставляючи їх за key.\\n\\nВисновок\\nЗміна типу компонента завжди призводить до втрати стану, незалежно від key. Key корисний лише для компонентів того самого типу в динамічних списках. Використовуйте key задля стабільної ідентифікації елементів того самого типу, аби уникати зайвого створення заново.","// Component A and B are different types\\nfunction A() { return <div>A</div>; }\\nfunction B() { return <div>B</div>; }\\n\\n// When switching from A to B the state will not be preserved\\n{condition ? <A key=\\"same\\" /> : <B key=\\"same\\" />}"],[2625,"React використовує поверхневе порівняння, щоб визначати зміни пропсів. Воно порівнює посилання на об'єкти плюс примітивні значення. Якщо посилання на об'єкт не змінилося, React вважає пропси однаковими. Це дає змогу уникати надлишкових повторних рендерів, коли використовують React.memo або PureComponent.","Як React порівнює пропси\\nReact використовує поверхневе порівняння, щоб перевіряти зміни пропсів. Це означає, що порівнюють лише посилання на об'єкти й примітивні значення, а не їхній вміст. Якщо проп — об'єкт або масив, React перевіряє, чи змінилося посилання на цей об'єкт, а не його внутрішні поля.\\n\\nПриклад поверхневого порівняння\\nПодивімося на компонент, обгорнутий у React.memo:\\n\\nЯк це працює\\nReact.memo і PureComponent реалізують метод shouldComponentUpdate, який виконує поверхневе порівняння всіх пропсів. Якщо всі пропси залишилися тими самими (за посиланням), компонент не рендериться повторно. Це особливо корисно, щоб оптимізувати продуктивність у великих списках або з частими оновленнями батьківського компонента.\\n\\nПрактичне застосування\\nПоверхневе порівняння ефективне для примітивних типів (чисел, рядків, булевих значень) й для немутабельних об'єктів. Якщо ви передаєте об'єкти, які змінюються часто, рекомендують використовувати useMemo або useCallback, щоб стабілізувати посилання:\\n\\nВисновок\\nПоверхневе порівняння — швидкий, ефективний спосіб уникати надлишкових повторних рендерів у React. Його варто застосовувати в компонентах, які перемальовуються часто, але отримують стабільні пропси. Для глибоких об'єктів використовуйте стабілізацію посилань через хуки або бібліотеки немутабельності.","const MyComponent = React.memo(({ data }) => {\\n  console.log('render');\\n  return <div>{data.value}</div>;\\n});\\n\\n// With such a call the component does not re-render:\\nconst data = { value: 1 };\\n<MyComponent data={data} />\\n<MyComponent data={data} /> // the reference is the same\\n\\n// But with this one it does re-render:\\n<MyComponent data={{ value: 1 }} />\\n<MyComponent data={{ value: 1 }} /> // different references\\n\\nconst memoizedData = useMemo(() => ({ value: 1 }), []);\\n<MyComponent data={memoizedData} />"],[2626,"У React, щоб реалізувати таку форму, використовують контрольований компонент: значення select зберігають у стані, й на його основі умовно рендерять додаткові поля. Коли select змінюється, стан оновлюється, що спричиняє перемалювання з потрібними полями. Це дає змогу гнучко змінювати структуру форми, не маніпулюючи DOM напряму.","Динамічні форми з умовним рендерингом\\nКоли форма має змінюватися залежно від вибору користувача, використовують підхід контрольованих компонентів плюс умовний рендеринг. Стан зберігає поточне значення select, й на його основі відображають відповідні поля введення.\\n\\nПриклад реалізації\\nПодивімося на форму, у якій на вибір «email» з'являється поле для електронної пошти, а на вибір «phone» — поле для номера телефону з маскою.\\n\\nКлючові моменти\\n\\n- Стан форми зберігають у React-компоненті, що робить його передбачуваним.\\n- Коли select змінюється, стан оновлюється, і React перемальовує лише ті частини, які змінилися.\\n- Важливо скидати залежні поля, коли тип змінюється, аби уникати некоректних даних.\\n\\nВисновок\\nТакий підхід застосовують у складних формах, анкетах і налаштуваннях, де набір полів залежить від попереднього вибору. Він забезпечує чистоту коду й легкість підтримки.","import React, { useState } from 'react';\\n\\nfunction DynamicForm() {\\n  const [contactType, setContactType] = useState('email');\\n  const [contactValue, setContactValue] = useState('');\\n\\n  const handleTypeChange = (e) => {\\n    setContactType(e.target.value);\\n    setContactValue(''); // the reset of the value when the type changes\\n  };\\n\\n  return (\\n    <form>\\n      <select value={contactType} onChange={handleTypeChange}>\\n        <option value=\\"email\\">Email</option>\\n        <option value=\\"phone\\">Phone</option>\\n      </select>\\n      {contactType === 'email' ? (\\n        <input\\n          type=\\"email\\"\\n          value={contactValue}\\n          onChange={(e) => setContactValue(e.target.value)}\\n          placeholder=\\"Enter email\\"\\n        />\\n      ) : (\\n        <input\\n          type=\\"tel\\"\\n          value={contactValue}\\n          onChange={(e) => setContactValue(e.target.value)}\\n          placeholder=\\"Enter phone\\"\\n        />\\n      )}\\n    </form>\\n  );\\n}"],[2627,"React Native надає API задля роботи з нативними можливостями через вбудовані модулі й сторонні бібліотеки. Задля доступу до файлової системи використовують react-native-fs, а для камери — react-native-camera або expo-camera. Дозволи треба запитувати через PermissionsAndroid або Permissions API. Ці модулі дають змогу виконувати операції, недоступні у вебі, зберігаючи єдину кодову базу.","Робота з нативними можливостями в React Native\\nReact Native дає змогу взаємодіяти з нативними функціями пристрою, як-от файловою системою, камерою, геолокацією й іншими, через систему нативних модулів. Цього досягають за допомогою моста, який пов'язує JavaScript-код із нативними API iOS й Android. Щоб полегшити розробку, використовують популярні сторонні бібліотеки, які надають готові інтерфейси.\\n\\nФайлова система\\nЩоб працювати з файловою системою, застосовують бібліотеку \`react-native-fs\`. Вона дає змогу читати, записувати й вилучати файли й керувати каталогами. Приклад запису файлу:\\n\\nКамера\\nЗадля доступу до камери використовують \`react-native-camera\` або \`expo-camera\` (якщо проєкт на Expo). Бібліотека надає компонент \`RNCamera\`, який можна вбудувати в інтерфейс. Приклад:\\n\\nДозволи\\nЗадля доступу до нативних функцій треба запитувати дозволи. На Android використовують \`PermissionsAndroid\`, а на iOS — \`Permissions\` із бібліотеки \`react-native-permissions\`. Приклад запиту дозволу на камеру на Android:\\n\\nВисновок\\nВикористання нативних модулів у React Native дає змогу створювати застосунки з повним доступом до можливостей пристрою, зберігаючи єдину кодову базу для iOS й Android. Це особливо корисно для застосунків, які потребують роботи з файлами, медіа або сенсорами, де вебтехнології обмежені.","import RNFS from 'react-native-fs';\\n\\nconst path = \`\${RNFS.DocumentDirectoryPath}/example.txt\`;\\nRNFS.writeFile(path, 'Hello, World!', 'utf8')\\n  .then(() => console.log('File written'))\\n  .catch(err => console.error(err));\\n\\nimport { RNCamera } from 'react-native-camera';\\n\\nconst CameraView = () => (\\n  <RNCamera\\n    style={{ flex: 1 }}\\n    type={RNCamera.Constants.Type.back}\\n    captureAudio={false}\\n  />\\n);\\n\\nimport { PermissionsAndroid } from 'react-native';\\n\\nasync function requestCameraPermission() {\\n  try {\\n    const granted = await PermissionsAndroid.request(\\n      PermissionsAndroid.PERMISSIONS.CAMERA\\n    );\\n    if (granted === PermissionsAndroid.RESULTS.GRANTED) {\\n      console.log('Camera permission granted');\\n    }\\n  } catch (err) {\\n    console.warn(err);\\n  }\\n}"],[2628,"Щоб зібрати React Native застосунок, треба налаштувати підпис: для Android створити keystore й зазначити його в gradle.properties, а для iOS налаштувати сертифікати й provisioning profile в Xcode. Далі запустіть команди: для Android cd android && ./gradlew bundleRelease, для iOS npx react-native run-ios --configuration Release. Після збирання можна вивантажити білд у Google Play Console або в App Store Connect.","Загальний процес збирання й підпису React Native застосунку\\nЗбирання React Native застосунку задля релізу включає кілька стадій: налаштування підпису (code signing), налаштування збирання й генерацію фінального артефакту (APK/AAB для Android, IPA для iOS). Підпис потрібний, щоб ідентифікувати розробника й забезпечити цілісність застосунку.\\n\\nAndroid: keystore і Gradle\\nДля Android треба створити keystore — файл із ключем підпису. Створіть його через keytool:\\n\\nПокладіть файл у теку android/app. Далі у файлі android/gradle.properties додайте:\\n\\nУ android/app/build.gradle налаштуйте signingConfigs:\\n\\nЗберіть AAB (рекомендовано для Google Play):\\n\\nAPK можна отримати командою ./gradlew assembleRelease.\\n\\niOS: сертифікати й provisioning profile\\nДля iOS потрібна Apple Developer Program. У Xcode: оберіть проєкт, вкладку Signing & Capabilities, увімкніть Automatically manage signing (або налаштуйте вручну). Переконайтеся, що у вас є Distribution Certificate й App Store Provisioning Profile. Зберіть архів:\\n\\nАбо через Xcode: Product > Archive. Після архівування відкриється Organizer, де можна вивантажити білд в App Store Connect.\\n\\nПідготовка до релізу\\nПеред збиранням оновіть версію в package.json і налаштуйте іконки й екран запуску. Для Android також налаштуйте versionCode і versionName в android/app/build.gradle, а для iOS — в Info.plist і в налаштуваннях General у Xcode.\\n\\nВисновок: належне налаштування підпису й збирання — критична стадія перед публікацією. Використовуйте автоматичне керування підписом для iOS і зберігайте keystore у безпеці для Android. Це забезпечить успішне вивантаження в крамниці застосунків.","keytool -genkey -v -keystore my-release-key.keystore -alias my-key-alias -keyalg RSA -keysize 2048 -validity 10000\\n\\nMYAPP_UPLOAD_STORE_FILE=my-release-key.keystore\\nMYAPP_UPLOAD_KEY_ALIAS=my-key-alias\\nMYAPP_UPLOAD_STORE_PASSWORD=*****\\nMYAPP_UPLOAD_KEY_PASSWORD=*****\\n\\nsigningConfigs {\\n    release {\\n        storeFile file(MYAPP_UPLOAD_STORE_FILE)\\n        storePassword MYAPP_UPLOAD_STORE_PASSWORD\\n        keyAlias MYAPP_UPLOAD_KEY_ALIAS\\n        keyPassword MYAPP_UPLOAD_KEY_PASSWORD\\n    }\\n}\\nbuildTypes {\\n    release {\\n        signingConfig signingConfigs.release\\n    }\\n}\\n\\ncd android && ./gradlew bundleRelease\\n\\nnpx react-native run-ios --configuration Release"],[2629,"Спочатку виконується console.log у тілі батьківського компонента, потім той, що в тілі дочірнього. Після того як DOM змонтовано, викликають useEffect: спочатку батьківський, потім дочірній. Це тому, що рендеринг компонентів відбувається згори вниз, а ефекти йдуть знизу вгору після того, як рендеринг завершився.","Порядок виконання console.log у React\\nКоли React рендерить компоненти, він спочатку виконує код у тілі функції компонента (включно з console.log) для батька, а потім для дочірніх компонентів. Після того як усі компоненти відрендерено й DOM оновлено, React запускає хуки useEffect у порядку від дітей до батьків.\\n\\nПриклад коду\\n\\nПорядок виведення\\n\\n- Parent render\\n- Child render\\n- Child effect\\n- Parent effect\\n\\nЦе пояснюється тим, що рендеринг іде згори вниз, а ефекти виконуються після того, як усі компоненти змонтовано, починаючи з найглибшого.\\n\\nВисновок: розуміння цього порядку важливе задля зневадження й належного використання useEffect, особливо в роботі з побічними ефектами, які залежать від дочірніх компонентів.","function Parent() {\\n  console.log('Parent render');\\n  useEffect(() => {\\n    console.log('Parent effect');\\n  }, []);\\n  return <Child />;\\n}\\n\\nfunction Child() {\\n  console.log('Child render');\\n  useEffect(() => {\\n    console.log('Child effect');\\n  }, []);\\n  return null;\\n}"],[2630,"React використовує декларативний підхід. Ви описуєте, як має виглядати UI залежно від стану, а React сам піклується про оновлення DOM. В імперативному підході ви пишете покрокові інструкції, як змінити інтерфейс. Декларативний код простіше читати, тестувати й підтримувати.","Декларативний проти імперативного підходу в React\\nReact побудований на декларативному підході. Це означає, що розробник описує бажаний стан інтерфейсу, а React бере на себе задачу його досягти. Замість того щоб писати послідовність команд задля зміни DOM, ви просто декларуєте, як має виглядати UI із певними даними.\\n\\nПриклад порівняння\\nПодивімося на задачу: показати список елементів і вирізнити активний.\\n\\nІмперативний підхід (на чистому JavaScript):\\n\\nДекларативний підхід (React):\\n\\nУ React ви просто описуєте структуру UI на основі пропсів і стану. React сам обчислює різницю між попереднім і новим віртуальним DOM й ефективно оновлює реальний DOM.\\n\\nПереваги декларативного підходу\\n\\n- Код передбачуваніший, і його легше зневаджувати\\n- Менше шансів внести баги через ручне керування DOM\\n- Він полегшує повторне використання компонентів\\n- Він дає змогу зосередитися на логіці застосунку, а не на деталях оновлення інтерфейсу\\n\\nВисновок: декларативний підхід React робить розробку UI продуктивнішою й менш схильною до багів. Його варто застосовувати в будь-якому проєкті, де важливі легкість підтримки й масштабованість інтерфейсу.","const list = document.getElementById('list');\\nconst items = ['A', 'B', 'C'];\\nitems.forEach((text, index) => {\\n  const li = document.createElement('li');\\n  li.textContent = text;\\n  if (index === activeIndex) {\\n    li.classList.add('active');\\n  }\\n  list.appendChild(li);\\n});\\n\\nfunction ItemList({ items, activeIndex }) {\\n  return (\\n    <ul>\\n      {items.map((text, index) => (\\n        <li key={index} className={index === activeIndex ? 'active' : ''}>\\n          {text}\\n        </li>\\n      ))}\\n    </ul>\\n  );\\n}"],[2631,"Якщо мемоїзація окремих карток неможлива, використовуйте віртуалізацію списку (наприклад, react-window), щоб рендерити лише видимі елементи. Також можна застосувати useMemo задля фільтрації або сортування даних і обгорнути сам компонент списку в React.memo. Якщо дані оновлюються надто часто, розгляньте debounce або throttle, щоб зменшити кількість оновлень.","Проблема зайвих перемалювань\\nКоли дані у сховищі (наприклад, Redux або Zustand) оновлює сторонній застосунок, щоразу відбувається повторний рендер усього списку карток. Якщо мемоїзація окремих карток неможлива (наприклад, через динамічні пропси або складну логіку), доводиться оптимізувати на рівні списку.\\n\\nОсновні стратегії\\n\\n- Віртуалізація списку: бібліотеки на кшталт react-window або react-virtualized рендерять лише видимі елементи. Це радикально зменшує кількість DOM-вузлів і перемалювань.\\n- React.memo для списку: обгорніть компонент списку в React.memo, щоб він перемальовувався лише тоді, коли його пропси змінюються. Якщо пропси — масив об'єктів, використовуйте useMemo, щоб стабілізувати посилання.\\n- Debounce/throttle: якщо дані оновлюються частіше, ніж це потрібно UI, обмежте частоту оновлень за допомогою debounce (наприклад, lodash.debounce).\\n\\nПриклад коду\\n\\nВисновок\\nКоли мемоїзація окремих карток неможлива, використовуйте віртуалізацію в поєднанні з React.memo й useMemo задля стабілізації даних. Це особливо корисно для великих списків (100+ елементів) із частими оновленнями зі сторонніх джерел.","import { useMemo } from 'react';\\nimport { FixedSizeList } from 'react-window';\\n\\nconst CardList = ({ items }) => {\\n  // We stabilize the reference to the array\\n  const stableItems = useMemo(() => items, [items.length]);\\n\\n  const Row = ({ index, style }) => (\\n    <div style={style}>\\n      <Card data={stableItems[index]} />\\n    </div>\\n  );\\n\\n  return (\\n    <FixedSizeList\\n      height={600}\\n      itemCount={stableItems.length}\\n      itemSize={120}\\n    >\\n      {Row}\\n    </FixedSizeList>\\n  );\\n};\\n\\nexport default React.memo(CardList);"],[2632,"Virtual DOM не прив'язаний до реального дерева DOM. createPortal дає змогу рендерити дочірні елементи в іншому DOM-вузлі, але Virtual DOM усе одно керує ними як частиною батьківського компонента. React оновлює портал через власний механізм звірення, ігноруючи ієрархію реального DOM.","Як Virtual DOM працює з createPortal\\nУ React Virtual DOM — абстрактне подання користувацького інтерфейсу, яке не залежить від реальної структури DOM. Коли ви використовуєте \`createPortal\`, ви повідомляєте React, що певний елемент треба змонтувати в іншому DOM-контейнері, але у Virtual DOM він залишається частиною батьківського компонента.\\n\\nПриклад коду\\n\\nУ цьому прикладі \`Modal\` рендерять у \`#modal-root\`, але у Virtual DOM він залишається дочірнім елементом \`App\`. React керує оновленнями портала через власний алгоритм порівняння (звірення), який працює на рівні Virtual DOM, а не реального DOM.\\n\\nКлючові аспекти\\n\\n- Virtual DOM не змінює своєї ієрархії, коли використовують портали — портал залишається частиною батьківського компонента в дереві Virtual DOM.\\n- React оновлює портал так само, як звичайні елементи: коли стан або пропси змінюються, він перемальовує лише потрібні частини.\\n- Події й контекст React (наприклад, Context API) працюють через Virtual DOM, тому портал може отримувати контекст від батьківського компонента, навіть якщо фізично він в іншому місці DOM.\\n\\nВисновок\\ncreatePortal — потужний інструмент, щоб рендерити модальні вікна, підказки або інші елементи поза основним потоком DOM, тимчасом як Virtual DOM зберігає логічну структуру застосунку, що полегшує керування станом і подіями.","import { createPortal } from 'react-dom';\\n\\nfunction Modal({ children }) {\\n  return createPortal(\\n    <div className=\\"modal\\">{children}</div>,\\n    document.getElementById('modal-root')\\n  );\\n}\\n\\nfunction App() {\\n  return (\\n    <div>\\n      <h1>Main App</h1>\\n      <Modal>\\n        <p>This is in a portal</p>\\n      </Modal>\\n    </div>\\n  );\\n}"],[2633,"Так, можна. Задля цього треба обгорнути функційний компонент у forwardRef і використати всередині хук useImperativeHandle, який дає змогу зазначити, що саме буде доступним через ref. Наприклад, можна повернути об'єкт із потрібними методами або даними. Це дає контроль над публічним API компонента.","Як ref працює з функційними компонентами\\nЗа замовчуванням функційні компоненти не підтримують ref, адже в них немає екземпляра класу. Однак React надає механізм, щоб кастомізувати ref, за допомогою поєднання \`forwardRef\` й \`useImperativeHandle\`.\\n\\nПриклад реалізації\\n\\nЯк це працює\\n\\n- \`forwardRef\` передає ref від батька в дочірній компонент як другий аргумент.\\n- \`useImperativeHandle\` визначає, які властивості й методи будуть доступні через ref.\\n- У батькові ви можете викликати ці методи так, наче це екземпляр класового компонента.\\n\\nВисновок\\nВикористовуйте \`useImperativeHandle\` із \`forwardRef\`, коли задля функційного компонента треба надати зовнішній інтерфейс — наприклад, щоб керувати фокусом чи анімаціями або викликати внутрішні методи з батька.","import React, { forwardRef, useImperativeHandle, useState } from 'react';\\n\\nconst Child = forwardRef((props, ref) => {\\n  const [count, setCount] = useState(0);\\n\\n  useImperativeHandle(ref, () => ({\\n    increment: () => setCount(c => c + 1),\\n    getCount: () => count\\n  }));\\n\\n  return <div>{count}</div>;\\n});\\n\\nfunction Parent() {\\n  const childRef = useRef();\\n\\n  return (\\n    <>\\n      <Child ref={childRef} />\\n      <button onClick={() => childRef.current.increment()}>+</button>\\n    </>\\n  );\\n}"],[2634,"forwardRef — функція в React, яка дає змогу передати ref від батьківського компонента до дочірнього. Її використовують, коли потрібний доступ до DOM-елемента всередині дочірнього компонента — наприклад, задля фокусу, анімації або інтеграції з бібліотеками. Без forwardRef ref не переспрямовують через компонент, адже він не є пропсом.","Що таке forwardRef?\\nforwardRef — функція з бібліотеки React, яка дає компонентові змогу прийняти ref і передати його далі, звичайно DOM-елементові або іншому компонентові. За замовчуванням ref не передають через пропси, тому forwardRef використовують, щоб його переспрямувати.\\n\\nКоли це потрібно?\\n\\n- Керування фокусом на input усередині власного компонента.\\n- Інтеграція з бібліотеками, які потребують прямого доступу до DOM (наприклад, анімації або сторонні UI-бібліотеки).\\n- Вимірювання розміру або позиції елемента.\\n\\nПриклад коду\\n\\nЯк це працює?\\nКомпонент, обгорнутий у forwardRef, отримує другий аргумент — ref. Цей ref можна прив'язати до будь-якого DOM-елемента всередині компонента. Батько використовує useRef() і передає його як проп ref. React переспрямовує ref через forwardRef автоматично.\\n\\nВисновок\\nforwardRef корисний, коли доступ до DOM-елемента всередині компонента-обгортки треба зберегти, не порушуючи інкапсуляції. Використовуйте його задля фокусу, анімацій або інтеграції з бібліотеками, які потребують прямого доступу до DOM.","import React, { forwardRef, useRef } from 'react';\\n\\nconst CustomInput = forwardRef((props, ref) => {\\n  return <input ref={ref} {...props} />;\\n});\\n\\nfunction App() {\\n  const inputRef = useRef(null);\\n\\n  const focusInput = () => {\\n    inputRef.current.focus();\\n  };\\n\\n  return (\\n    <>\\n      <CustomInput ref={inputRef} placeholder=\\"Type here\\" />\\n      <button onClick={focusInput}>Focus Input</button>\\n    </>\\n  );\\n}"],[2635,"У FSD sample використовують, щоб пов'язувати події й сховища без прямих залежностей між модулями. Підписки на події організовують через watch або sample усередині features чи entities, аби уникати циклічних залежностей. Це дає змогу зберегти ізоляцію шарів і полегшує тестування.","Організація samples і підписок в Effector із FSD\\nFeature-Sliced Design (FSD) передбачає строгу ієрархію шарів: shared, entities, features, widgets, pages, app. В Effector важливо, щоб події й сховища не створювали циклічних залежностей між шарами. Задля цього використовують sample, який дає змогу декларативно пов'язати джерела з цільовим елементом, без прямого імпорту.\\n\\nПриклад використання sample\\nНехай в entities/user є сховище $user і подія fetchUserFx. У features/auth ми хочемо оновити користувача на успішній авторизації. Замість того щоб викликати fetchUserFx із features напряму, ми використовуємо sample:\\n\\nТут sample підписується на успішне завершення loginFx і запускає fetchUserFx. Це зберігає напрям залежності: features -> entities, а не навпаки.\\n\\nПідписки через watch\\nЗадля зневадження або побічних ефектів можна використати watch, але у FSD рекомендують уникати watch усередині бізнес-логіки, адже це може призводити до неявних зв'язків. Краще використовувати sample задля явних зв'язків.\\n\\nВисновок\\nВикористання sample у FSD допомагає тримати чисту архітектуру, уникаючи циклічних залежностей і роблячи зв'язки між модулями явними. Це полегшує рефакторинг і тестування, особливо у великих проєктах.","// features/auth/model.ts\\nimport { createEvent, sample } from 'effector';\\nimport { $user, fetchUserFx } from 'entities/user';\\n\\nexport const loginFx = createEffect(async (data) => {\\n  // the authorization logic\\n});\\n\\nsample({\\n  clock: loginFx.done,\\n  target: fetchUserFx,\\n});\\n\\n// An example of watch for logging\\nimport { $user } from 'entities/user';\\n\\n$user.watch((user) => {\\n  console.log('User updated:', user);\\n});"],[2636,"Повільне завантаження SPA на холодному старті звичайно спричиняють великий розмір бандла, відсутність кешування й неоптимізовані ресурси. Рішення включає розділення коду, ліниве завантаження модулів, мініфікацію й стиснення файлів і використання серверного рендерингу (SSR), щоб прискорити перше малювання.","Причини повільного завантаження SPA на холодному старті\\nОсновна проблема — великий єдиний JavaScript-бандл, який завантажують і виконують, перш ніж відобразити вміст. На холодному старті (перший візит або після того, як кеш очистили) переглядач завантажує всі ресурси з нуля, що збільшує час до інтерактивності (TTI). Додаткові чинники: неоптимізовані зображення, відсутність стиснення, скрипти, які блокують рендеринг.\\n\\nМетоди оптимізації\\n\\n- Code Splitting — розбиття бандла на частини за допомогою динамічних імпортів. Наприклад, у React Router:\\n\\n- Lazy Loading — відкладене завантаження зображень і компонентів, які не видно у початковому вікні.\\n- Стиснення й мініфікація — використання Gzip/Brotli на сервері, вилучення надлишкових пробілів і коментарів.\\n- Серверний рендеринг (SSR) — генерація HTML на сервері задля швидкого першого малювання (Next.js, Nuxt.js).\\n- Кешування — налаштування HTTP-заголовків Cache-Control і Service Worker, щоб кешувати статичні файли.\\n\\nВисновок\\nЗастосовуйте розділення коду й ліниве завантаження, щоб зменшити початковий бандл, використовуйте SSR для критичного вмісту й налаштуйте кешування. Це особливо корисно для великих SPA з безліччю маршрутів і модулів.","const Home = React.lazy(() => import('./Home'));\\nconst About = React.lazy(() => import('./About'));\\n\\n<Suspense fallback={<div>Loading...</div>}>\\n  <Routes>\\n    <Route path=\\"/\\" element={<Home />} />\\n    <Route path=\\"/about\\" element={<About />} />\\n  </Routes>\\n</Suspense>"],[2637,"React.memo запобігає повторному рендеру компонента, якщо його пропси не змінилися. useCallback мемоїзує функцію, щоб її посилання залишалося стабільним між рендерами. useMemo мемоїзує результат обчислення. Коли функцію передають у компонент, обгорнутий у React.memo, то без useCallback кожний рендер батька створює нову функцію, що порушує мемоїзацію дочірнього компонента.","Як працюють useMemo, useCallback і React.memo\\nReact.memo — HOC (Higher-Order Component), який запам'ятовує результат рендера компонента й перемальовує його лише тоді, коли пропси змінюються. Він використовує поверхневе порівняння попередніх і нових пропсів. Якщо пропси не змінилися, React.memo повертає закешований результат, уникаючи надлишкового рендера.\\n\\nuseCallback — хук, який повертає мемоїзовану версію функції. Він приймає функцію плюс масив залежностей. Поки залежності не змінюються, useCallback повертає те саме посилання на функцію. Це критично, адже в JavaScript кожна нова функція — новий об'єкт у пам'яті.\\n\\nuseMemo — хук, щоб мемоїзувати результати обчислень. Він приймає обчислювальну функцію плюс масив залежностей. Результат обчислення кешують й обчислюють заново лише тоді, коли залежності змінюються.\\n\\nЧому важливо обгортати функції в useCallback, коли їх передають у React.memo\\nКоли батьківський компонент перемальовується, усі функції, оголошені всередині нього, створюють заново. Якщо ви передаєте таку функцію як проп у дочірній компонент, обгорнутий у React.memo, то на кожному рендері батька дочірній компонент отримує нове посилання на функцію. React.memo на своєму поверхневому порівнянні бачить, що проп змінився (старе посилання !== нове посилання), й перемальовує дочірній компонент, незважаючи на те, що логіка функції не змінилася.\\n\\nПриклад:\\n\\nУ цьому прикладі без useCallback кожний клік по Increment спричиняв би перемалювання Child, навіть якщо onClick не змінюється. З useCallback посилання стабільне, і Child не перемальовується даремно.\\n\\nВисновок\\nВикористовуйте useCallback для функцій, які передають у компоненти, обгорнуті в React.memo, щоб зберегти вигоду від мемоїзації. Це особливо важливо у великих списках, у складних формах або в компонентах із важким рендером. Однак обгортати кожну функцію не варто — застосовуйте оптимізацію лише там, де вона справді потрібна задля продуктивності.","import React, { useState, useCallback } from 'react';\\n\\nconst Child = React.memo(({ onClick }) => {\\n  console.log('Child rendered');\\n  return <button onClick={onClick}>Click</button>;\\n});\\n\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n\\n  // Without a useCallback: every render creates a new function\\n  const handleClick = useCallback(() => {\\n    console.log('Clicked');\\n  }, []);\\n\\n  return (\\n    <>\\n      <p>Count: {count}</p>\\n      <button onClick={() => setCount(c => c + 1)}>Increment</button>\\n      <Child onClick={handleClick} />\\n    </>\\n  );\\n}"],[2638,"Пропси в React немутабельні й не можуть змінитися самі по собі. Їх передають із батьківського компонента, і вони змінюються лише на його повторному рендері. Щоб компонент рендерився лише тоді, коли пропси змінюються, використовуйте React.memo для функційних компонентів або shouldComponentUpdate для класових. Ці методи виконують поверхневе порівняння пропсів і запобігають надлишковим повторним рендерам.","Немутабельність пропсів\\nПропси в React — немутабельні дані, які передають із батьківського компонента в дочірній. Вони не можуть змінитися всередині самого компонента — це фундаментальне правило React. Якщо пропси виглядають так, наче вони змінилися, це означає, що батьківський компонент виконав повторний рендер і передав нові значення.\\n\\nЧому це важливо\\nНемутабельність гарантує передбачуваність потоку даних і полегшує зневадження. Компонент завжди отримує пропси як свої вхідні дані й не має їх модифікувати. Якщо дані треба змінити, це роблять через стан або через колбеки, передані в пропсах.\\n\\nКонтроль повторних рендерів\\nЗа замовчуванням React повторно рендерить компонент на будь-якій зміні стану або пропсів батька. Щоб оптимізувати продуктивність і рендерити компонент лише тоді, коли його власні пропси змінюються, використовуйте:\\n- React.memo — для функційних компонентів. Він запам'ятовує результат рендера й виконує поверхневе порівняння пропсів.\\n- shouldComponentUpdate — для класових компонентів. Це метод життєвого циклу, який повертає true або false, зазначаючи, чи треба оновити компонент.\\n\\nПриклад із React.memo\\n\\nУ цьому прикладі \`ChildComponent\` обгорнутий у \`React.memo\`. На натисканні кнопки змінюється лише стан \`count\` у батькові, а проп \`name\` залишається тим самим. Завдяки \`React.memo\` дочірній компонент не рендериться повторно, що видно з відсутності повідомлення в консолі.\\n\\nПриклад із shouldComponentUpdate\\n\\nТут \`shouldComponentUpdate\` порівнює поточний проп \`name\` із новим. Якщо вони рівні, метод повертає \`false\`, і повторного рендера не відбувається.\\n\\nВисновок\\nПропси ніколи не змінюються самі по собі — це немутабельні дані. Щоб запобігти надлишковим повторним рендерам, використовуйте \`React.memo\` або \`shouldComponentUpdate\`. Ці інструменти особливо корисні у великих застосунках із глибоко вкладеними компонентами, де оптимізація продуктивності критична.","import React from 'react';\\n\\nconst ChildComponent = React.memo(({ name }) => {\\n  console.log('Child rendered');\\n  return <div>Hello, {name}!</div>;\\n});\\n\\nfunction Parent() {\\n  const [count, setCount] = React.useState(0);\\n  return (\\n    <div>\\n      <ChildComponent name=\\"Alice\\" />\\n      <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>\\n    </div>\\n  );\\n}\\n\\nclass ChildComponent extends React.Component {\\n  shouldComponentUpdate(nextProps) {\\n    return nextProps.name !== this.props.name;\\n  }\\n\\n  render() {\\n    console.log('Child rendered');\\n    return <div>Hello, {this.props.name}!</div>;\\n  }\\n}"],[2639,"Стан React-компонента не залежить від його розміщення в DOM. Навіть якщо компонент рендерять через портал в іншому DOM-вузлі, його стан залишається прив'язаним до логічного дерева React-компонентів. Портал впливає лише на те, де відображають HTML, а не на життєвий цикл або стан компонента.","Як state працює з порталами\\nПортал у React дає змогу рендерити дочірні елементи в іншій частині дерева DOM, поза батьківським компонентом. Однак це не впливає на стан компонента. Стан залишається прив'язаним до логічного дерева React, а не до фізичного DOM.\\n\\nПриклад\\n\\nУ цьому прикладі компонент Modal рендерять у #modal-root, але його станом count керують так само, наче він усередині батька. Події, життєвий цикл і контекст React працюють як звичайно.\\n\\nВисновок\\nПортали корисні для модальних вікон, підказок й інших елементів, які мають бути поза потоком документа, однак зберігати повну інтеграцію зі станом і контекстом React.","import React, { useState } from 'react';\\nimport ReactDOM from 'react-dom';\\n\\nfunction Modal({ children }) {\\n  const [count, setCount] = useState(0);\\n  return ReactDOM.createPortal(\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={() => setCount(count + 1)}>+</button>\\n    </div>,\\n    document.getElementById('modal-root')\\n  );\\n}"],[2640,"Готова бібліотека (наприклад, Material UI) прискорює розробку й надає готові компоненти й доступність, але може обмежувати кастомізацію й збільшувати розмір бандла. Власний UI-кіт дає повний контроль над дизайном і продуктивністю, але потребує більше часу на розробку й підтримку. Вибір залежить від вимог проєкту: швидкість проти унікальності.","Вступ\\nВибір між готовою UI-бібліотекою й власним UI-кітом — одне з ключових архітектурних рішень, коли створюють інтерфейс. Готові бібліотеки на кшталт Material UI, Ant Design або Chakra UI пропонують набір заздалегідь зібраних компонентів із єдиним стилем. Власний UI-кіт розробляють із нуля задля конкретних потреб проєкту.\\n\\nПлюси й мінуси готової бібліотеки\\n\\n- Плюси: швидкий старт, вбудована доступність (a11y), документація, спільнота, менше багів.\\n- Мінуси: обмежена кастомізація, надлишковий код (збільшення бандла), залежність від оновлень, складність інтеграції з унікальним дизайном.\\n\\nПлюси й мінуси власного UI-кіта\\n\\n- Плюси: повний контроль над стилями й поведінкою, мінімальний розмір бандла, точна відповідність дизайн-системі, незалежність від зовнішніх оновлень.\\n- Мінуси: тривала розробка, потреба підтримувати доступність, тестування й документацію, ризик багів.\\n\\nПриклад коду: власний компонент кнопки\\n\\nВисновок\\nВикористовуйте готову бібліотеку для швидких прототипів або для проєктів зі стандартним дизайном. Власний UI-кіт виправданий для великих продуктів з унікальним брендингом і строгими вимогами до продуктивності.","// A custom button with props for the styles\\nconst Button = ({ variant, children }) => {\\n  const baseStyle = { padding: '8px 16px', border: 'none', cursor: 'pointer' };\\n  const variants = {\\n    primary: { backgroundColor: 'blue', color: 'white' },\\n    secondary: { backgroundColor: 'gray', color: 'black' },\\n  };\\n  return <button style={{ ...baseStyle, ...variants[variant] }}>{children}</button>;\\n};"],[2641,"Вибір залежить від складності компонента й від вимог проєкту. Для стандартних рішень (date picker, select) я звичайно використовую готові бібліотеки, адже вони зберігають час і їх перевірила спільнота. Для унікальних або сильно кастомізованих компонентів (складних таблиць) я пишу їх самостійно, щоб забезпечити гнучкість і продуктивність.","Підхід до вибору між готовими бібліотеками й власною розробкою\\nКоли реалізують складні UI-компоненти на кшталт date picker, таблиць із сортуванням і фільтрацією або власних select, важливо оцінити кілька чинників: вимоги до функціональності, потребу в кастомізації, продуктивність і час розробки. Готові бібліотеки (наприклад, React Select, Ant Design, Material-UI) надають перевірені рішення з широкою функціональністю, що прискорює розробку й зменшує кількість багів. Однак вони можуть бути надмірними за розміром або не відповідати специфічним вимогам дизайну.\\n\\nКоли використовувати готові бібліотеки\\n\\n- Стандартні компоненти з типовою поведінкою (date picker, select із пошуком).\\n- Потреба у швидкому прототипуванні або в MVP.\\n- Відсутність строгих вимог до кастомізації вигляду.\\n\\nКоли писати самостійно\\n\\n- Унікальні вимоги до поведінки або вигляду, яких бібліотеки не покривають.\\n- Потреба оптимізувати продуктивність для великих даних (наприклад, віртуалізація таблиць).\\n- Бажання мінімізувати розмір бандла й залежності.\\n\\nПриклад: власний select із віртуалізацією\\n\\nУ цьому прикладі власний select використовує віртуалізацію, щоб працювати з тисячами опцій, що не можна реалізувати ефективно за допомогою стандартних бібліотек без додаткового налаштування.\\n\\nВисновок\\nОптимальний підхід — поєднувати готові бібліотеки для типових задач із власною розробкою для унікальних вимог, що дає змогу балансувати між швидкістю розробки й гнучкістю.","import React, { useState, useRef } from 'react';\\nimport { FixedSizeList as List } from 'react-window';\\n\\nconst VirtualSelect = ({ options }) => {\\n  const [isOpen, setIsOpen] = useState(false);\\n  const [selected, setSelected] = useState(null);\\n  const listRef = useRef();\\n\\n  const handleSelect = (option) => {\\n    setSelected(option);\\n    setIsOpen(false);\\n  };\\n\\n  return (\\n    <div>\\n      <button onClick={() => setIsOpen(!isOpen)}>\\n        {selected ? selected.label : 'Select...'}\\n      </button>\\n      {isOpen && (\\n        <List\\n          height={200}\\n          itemCount={options.length}\\n          itemSize={35}\\n          ref={listRef}\\n        >\\n          {({ index, style }) => (\\n            <div style={style} onClick={() => handleSelect(options[index])}>\\n              {options[index].label}\\n            </div>\\n          )}\\n        </List>\\n      )}\\n    </div>\\n  );\\n};"],[2642,"Функційне оновлення стану (передавання функції в setState з аргументом prev) гарантує, що новий стан обчислюють на основі найактуальнішого попереднього стану. Це критично важливо на кількох послідовних викликах setState або в роботі з асинхронним кодом, адже React може групувати оновлення. Використання prevState запобігає помилкам, пов'язаним із застарілими значеннями в замиканнях.","Проблема асинхронності setState\\nУ React метод setState асинхронний. Це означає, що стан не оновлюється одразу після того, як setState викликали. React може згрупувати кілька викликів setState в одне оновлення, щоб покращити продуктивність (батчинг). Якщо ви використовуєте звичайне присвоювання — наприклад, \`setCount(count + 1)\`, — то значення \`count\` беруть із поточного замикання, яке може бути застарілим на момент фактичного оновлення.\\n\\nЯк працює функційне оновлення\\nФункційна форма \`setCount(prev => prev + 1)\` передає в setState функцію, яка отримує попередній стан (prev) як свій аргумент. React гарантує, що prev буде найактуальнішим значенням на момент виконання оновлення, навіть якщо було кілька послідовних викликів.\\n\\nПриклад із кількома викликами\\n\\nКоли це особливо важливо\\n\\n- На кількох послідовних оновленнях стану в одному обробнику подій.\\n- У роботі з асинхронними операціями (setTimeout, fetch), де замикання може захопити застаріле значення.\\n- Коли використовують хук useState у функційних компонентах, де ця проблема також актуальна.\\n\\nВисновок\\nФункційне оновлення стану — надійний спосіб гарантувати коректність обчислень, які залежать від попереднього стану. Його варто використовувати всюди, де новий стан обчислюють на основі попереднього, особливо у сценаріях із кількома оновленнями або з асинхронним кодом.","// Wrong: it can lead to the wrong result\\nconst handleClick = () => {\\n  setCount(count + 1); // count = 0\\n  setCount(count + 1); // count = 0 (still 0, from the closure)\\n  // The outcome: count = 1, while 2 was expected\\n};\\n\\n// Right: every call uses the current value\\nconst handleClick = () => {\\n  setCount(prev => prev + 1); // prev = 0 -> 1\\n  setCount(prev => prev + 1); // prev = 1 -> 2\\n  // The outcome: count = 2\\n};"],[2643,"Стейт-менеджери (наприклад, Redux) потрібні, щоб централізовано керувати складним станом застосунку, особливо коли дані використовує багато компонентів. Context API розв'язує схожу задачу, але він менш продуктивний із частими оновленнями, адже спричиняє повторний рендер усіх споживачів. Стейт-менеджери пропонують передбачуваніше оновлення плюс інструменти задля зневадження.","Для чого потрібні стейт-менеджери?\\nУ React стан звичайно локальний для компонента. Коли застосунок зростає, виникає потреба поділитися станом між багатьма компонентами, які часто розташовані далеко одне від одного в дереві. Стейт-менеджери на кшталт Redux, MobX або Zustand надають єдине сховище плюс строгі правила його зміни, що робить потік даних передбачуваним і полегшує зневадження.\\n\\nЧим відрізняється Context?\\nContext API — вбудований механізм React, щоб передавати дані без прокидання пропсів. Його просто використовувати, але він має недоліки: коли значення контексту змінюється, кожний компонент, який його споживає, рендериться повторно, навіть якщо він не використовує ту частину, що змінилася. Це може призводити до проблем із продуктивністю у великих застосунках.\\n\\nПриклад порівняння\\nПодивімося на застосунок із кошиком. Із використанням Context:\\n\\nБудь-який компонент, який використовує \`useContext(CartContext)\`, буде відрендерено повторно на кожному додаванні товару, навіть якщо він показує лише загальну суму.\\n\\nІз Redux:\\n\\nТут \`TotalPrice\` відрендериться повторно лише тоді, коли обчислена сума змінюється, а не на будь-якій зміні кошика.\\n\\nВисновок\\nВикористовуйте Context для простого глобального стану (теми, мови), який змінюється рідко. Для складного, часто оновлюваного стану з безліччю споживачів обирайте стейт-менеджер — це дасть кращу продуктивність і передбачуваність.","const CartContext = React.createContext();\\n\\nfunction CartProvider({ children }) {\\n  const [items, setItems] = useState([]);\\n  const addItem = (item) => setItems(prev => [...prev, item]);\\n  return (\\n    <CartContext.Provider value={{ items, addItem }}>\\n      {children}\\n    </CartContext.Provider>\\n  );\\n}\\n\\n// slice\\nconst cartSlice = createSlice({\\n  name: 'cart',\\n  initialState: { items: [] },\\n  reducers: {\\n    addItem: (state, action) => { state.items.push(action.payload); },\\n  },\\n});\\n\\n// component\\nfunction TotalPrice() {\\n  const total = useSelector(state =>\\n    state.cart.items.reduce((sum, item) => sum + item.price, 0)\\n  );\\n  return <div>Total: {total}</div>;\\n}"],[2644,"Щоб значення оновлювалося лише один раз на монтуванні, треба передати в useEffect порожній масив залежностей. Це гарантує, що ефект виконається лише після першого рендера. Якщо всередині ефекту є таймер, його варто очистити у функції, яку повертають, аби уникати втрат пам'яті.","Проблема повторного виконання ефекту\\nУ React компоненти можуть рендеритися повторно з різних причин: зміни стану, пропсів або контексту. Якщо всередині useEffect не зазначено залежностей, ефект виконуватиметься після кожного рендера, що може призводити до небажаного повторного запуску таймерів або запитів.\\n\\nРішення: порожній масив залежностей\\nПередаючи порожній масив [] як другий аргумент useEffect, ми повідомляємо React, що ефект не залежить від жодних значень і має виконатися лише один раз — після того, як компонент змонтовано. Це ідеально, щоб ініціалізувати дані, підписатися на події або запустити одноразовий таймер.\\n\\nПриклад коду\\n\\nВажливість очищення ефектів\\nФункцію, яку повертають із useEffect, викликають, коли компонент демонтують або перед тим, як ефект виконається знову. У прикладі вище ми очищуємо інтервал, аби уникати втрат пам'яті й спроб оновити стан демонтованого компонента.\\n\\nВисновок\\nВикористовуйте порожній масив залежностей у useEffect, щоб виконувати код лише на монтуванні. Це стандартний патерн, щоб ініціалізувати дані, підписуватися й виконувати одноразові операції в React-компонентах.","import React, { useState, useEffect } from 'react';\\n\\nfunction TimerComponent() {\\n  const [value, setValue] = useState(0);\\n\\n  useEffect(() => {\\n    // This code will run only once, on the mounting\\n    const interval = setInterval(() => {\\n      setValue(prev => prev + 1);\\n    }, 1000);\\n\\n    // The clean-up of the timer on the unmounting\\n    return () => clearInterval(interval);\\n  }, []); // an empty array of dependencies\\n\\n  return <div>{value}</div>;\\n}"],[2645,"Функція очищення в useEffect виконується, коли компонент демонтують або перед тим, як ефект запустять знову. Без неї setInterval продовжить працювати після того, як ви покинете компонент, спричиняючи втрату пам'яті й виконуючи колбеки на компоненті, який уже демонтували. Це може призводити до помилок і до неконтрольованої поведінки.","Призначення функції очищення в useEffect\\nФункція очищення — функція, яку ви повертаєте з колбека useEffect. React викликає її, коли компонент демонтують або перед тим, як ефект запустять знову, коли залежності змінюються. Це дає змогу скасувати підписки, таймери, запити або інші побічні ефекти, аби уникати втрат пам'яті й некоректної поведінки.\\n\\nЩо відбудеться без неї, коли використовують setInterval?\\nЯкщо ви використовуєте setInterval усередині useEffect, не повертаючи функції очищення, інтервал продовжить працювати навіть після того, як компонент вилучили з DOM. Це призводить до:\\n- Втрати пам'яті — інтервал ніколи не зупиниться.\\n- Виконання колбеків на демонтованому компоненті, що може спричиняти помилки (наприклад, спробу оновити стан демонтованого компонента).\\n- Неконтрольованого зростання кількості інтервалів на кожному повторному рендері, якщо залежності змінюються.\\n\\nПриклад з очищенням\\n\\nУ цьому прикладі інтервал створюють один раз (порожній масив залежностей) і очищують, коли компонент демонтують. Без return із clearInterval інтервал працював би вічно, навіть якби компонент приховали.\\n\\nВисновок\\nФункція очищення в useEffect обов'язкова для будь-яких довгоживучих побічних ефектів, як-от таймерів, підписок або слухачів подій. Вона запобігає втратам пам'яті й гарантує належне керування ресурсами в React-застосунках.","import { useEffect, useState } from 'react';\\n\\nfunction Timer() {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    const id = setInterval(() => {\\n      setCount(prev => prev + 1);\\n    }, 1000);\\n\\n    // The clean-up function\\n    return () => {\\n      clearInterval(id);\\n    };\\n  }, []);\\n\\n  return <div>{count}</div>;\\n}"],[2646,"Функційна форма setState гарантує, що оновлення стану виконують на основі найактуальнішого попереднього значення. React може групувати кілька викликів setState в один батч, щоб оптимізувати продуктивність. Якщо ви передаєте нове значення напряму, то на кількох послідовних викликах setState в одному обробнику подій кожний наступний виклик використає застарілий стан, що призведе до неправильного результату. Натомість функція отримує попередній стан як свій аргумент, забезпечуючи належне накопичення змін.","Проблема асинхронності setState\\nУ React метод setState асинхронний. Це означає, що стан не оновлюється одразу після того, як setState викликали. React може згрупувати кілька викликів setState в один батч, щоб покращити продуктивність, особливо в обробниках подій й у життєвих циклах компонентів.\\n\\nЧому функційна форма розв'язує проблему\\nКоли ви передаєте в setState об'єкт (нове значення), React просто зливає його з поточним станом. Якщо у вас кілька послідовних викликів setState, кожний із них використає один і той самий початковий стан, а не результат попереднього оновлення. Функційна форма setState приймає функцію, яка отримує попередній стан (prevState) і повертає новий. Це гарантує, що кожне оновлення базується на найсвіжішому стані.\\n\\nПриклад коду\\n\\nКоли це особливо важливо\\n\\n- Коли виконують кілька оновлень стану в одному обробнику подій.\\n- У роботі з асинхронними операціями (наприклад, усередині setTimeout або fetch), де батчинг може не застосовуватися.\\n- У функційних компонентах із хуком useState, де функційну форму також підтримують.\\n\\nВисновок\\nВикористовуйте функційну форму setState всюди, де новий стан залежить від попереднього. Це гарантує коректність оновлень, особливо коли виклики групують, і робить код передбачуванішим й стійкішим до багів.","// Wrong: on several calls the counter will increase by only 1\\nhandleClick = () => {\\n  this.setState({ count: this.state.count + 1 });\\n  this.setState({ count: this.state.count + 1 });\\n  // The result: count will increase by 1 rather than by 2\\n}\\n\\n// Right: the functional form\\nhandleClick = () => {\\n  this.setState(prevState => ({ count: prevState.count + 1 }));\\n  this.setState(prevState => ({ count: prevState.count + 1 }));\\n  // The result: count will increase by 2\\n}"],[2647,"Ні, обгортати весь застосунок у React.memo немає сенсу, й це може навіть погіршити продуктивність. React.memo призначений, щоб запобігати надлишковим повторним рендерам компонентів, які отримують ті самі пропси. Якщо ви обгорнете весь застосунок, то на будь-якій зміні стану будь-де відбудеться повний повторний рендер, адже кореневий компонент майже завжди отримує нові пропси або стан.","Що таке React.memo і як він працює\\nReact.memo — функція вищого порядку, яка мемоїзує результат рендерингу компонента. Вона порівнює попередні й нові пропси (поверхнево) і, якщо вони не змінилися, повертає закешований результат, запобігаючи повторному рендеру. Це корисно для компонентів, які часто отримують ті самі пропси й рендерять важкі піддерева.\\n\\nЧому весь застосунок обгорнути не можна\\nКореневий компонент застосунку звичайно містить стан (наприклад, через useState, useReducer або глобальний стейт-менеджер). На кожній зміні стану кореневий компонент отримує нові пропси або оновлюється сам, тому React.memo не зможе запобігти його повторному рендеру. Ще більше того, порівняння пропсів на верхньому рівні додає надлишкові обчислення без жодної вигоди. Приклад:\\n\\nДе і як застосовувати React.memo\\nReact.memo варто використовувати для компонентів, які:\\n- Рендеряться часто, але отримують стабільні пропси (наприклад, простих презентаційних компонентів).\\n- Містять важкі обчислення або великі піддерева.\\n- Не залежать від контексту або від глобального стану, який змінюється часто.\\n\\nПриклад належного використання:\\n\\nУ такому разі ListItem не рендериться повторно, якщо його конкретний item не змінився.\\n\\nВисновок\\nReact.memo — інструмент задля точкової оптимізації, а не універсальне рішення. Обгортати весь застосунок неефективно, й це може призвести до протилежного ефекту. Використовуйте його лише для компонентів, де він справді дає вигоду, й завжди профілюйте продуктивність до й після того, як його впровадили.","const App = () => {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <button onClick={() => setCount(c => c + 1)}>Click</button>\\n      <ExpensiveChild />\\n    </div>\\n  );\\n};\\n\\nexport default React.memo(App); // Useless, since App re-renders when count changes\\n\\nconst ListItem = React.memo(({ item }) => {\\n  return <li>{item.name}</li>;\\n});\\n\\nconst List = ({ items }) => {\\n  return (\\n    <ul>\\n      {items.map(item => <ListItem key={item.id} item={item} />)}\\n    </ul>\\n  );\\n};"],[2648,"Для UI-бібліотеки найкраще підходить компонентна архітектура з atomic design. Компоненти поділяють на атоми, молекули й організми, що забезпечує повторне використання й гнучкість. Кожний компонент має бути незалежним, приймати пропси й не керувати глобальним станом. Це полегшує тестування й підтримку.","Компонентна архітектура для UI-бібліотеки\\nКоли створюють UI-бібліотеку, важливо обрати архітектуру, яка забезпечить повторне використання, масштабованість і легкість підтримки. Найдоречніший підхід — компонентна архітектура, заснована на принципах atomic design. Вона розбиває інтерфейс на малі, незалежні будівельні блоки.\\n\\nОсновні принципи\\n\\n- Atomic design: компоненти поділяють на атоми (кнопки, поля введення), молекули (групи атомів — наприклад, поле введення з підписом) й організми (складні блоки — наприклад, форму).\\n- Композиція: компоненти мають бути компонованими, щоб їх можна було поєднувати задля створення складних інтерфейсів.\\n- Незалежність: кожний компонент не має залежати від глобального стану або від контексту; усі дані передають через пропси.\\n- Типізація: використання TypeScript задля строгої типізації пропсів покращує документацію й запобігає багам.\\n\\nПриклад коду\\n\\nДе це застосовують\\nТаку архітектуру використовують у популярних бібліотеках, як-от Material-UI, Ant Design і Chakra UI. Вона дає розробникам змогу легко кастомізувати компоненти й створювати однакові інтерфейси.\\n\\nВисновок: компонентна архітектура з atomic design — найкращий вибір для UI-бібліотеки, адже вона забезпечує повторне використання, гнучкість і легкість тестування. Застосовуйте її, коли створюєте дизайн-системи або корпоративні бібліотеки компонентів.","// An atom: a button\\ninterface ButtonProps {\\n  label: string;\\n  onClick: () => void;\\n  variant: 'primary' | 'secondary';\\n}\\n\\nconst Button: React.FC<ButtonProps> = ({ label, onClick, variant }) => {\\n  return <button className={\`btn btn-\${variant}\`} onClick={onClick}>{label}</button>;\\n};\\n\\n// A molecule: an input field with a label\\ninterface InputFieldProps {\\n  label: string;\\n  value: string;\\n  onChange: (value: string) => void;\\n}\\n\\nconst InputField: React.FC<InputFieldProps> = ({ label, value, onChange }) => {\\n  return (\\n    <div>\\n      <label>{label}</label>\\n      <input value={value} onChange={(e) => onChange(e.target.value)} />\\n    </div>\\n  );\\n};"],[2649,"Так, контексти можна вкладати один в один. Кожний Provider створює власну область видимості, й дочірні компоненти можуть отримувати значення від найближчого батьківського Provider того самого типу. Вкладені контексти різних типів працюють незалежно.","Вкладання контекстів у React\\nУ React контексти можна вкладати один в один. Це означає, що ви можете мати кілька компонентів Provider, обгорнутих один навколо одного, кожний з яких надає власне значення. Дочірні компоненти можуть отримувати доступ до будь-якого з цих контекстів, використовуючи відповідний хук useContext або Consumer.\\n\\nЯк це працює\\nКоли компонент викликає useContext(MyContext), React шукає найближчий Provider цього контексту в дереві компонентів. Якщо Provider не знайдено, використовують значення за замовчуванням, передане в createContext. Вкладені контексти різних типів не впливають одне на одне, але, якщо ви вкладаєте Provider одного й того самого контексту, внутрішній Provider перекриває значення для своїх дочірніх елементів.\\n\\nПриклад коду\\n\\nПрактичне застосування\\nВкладені контексти корисні, щоб розділити різні аспекти стану застосунку, як-от тему, автентифікацію, локалізацію або налаштування. Це дає змогу уникати прокидання пропсів і робить код чистішим. Однак варто пам'ятати, що, коли значення контексту змінюється, усі споживачі рендеряться повторно, тому для даних, які змінюються часто, краще використовувати інші інструменти керування станом.\\n\\nВисновок: вкладання контекстів — потужний патерн, щоб організувати глобальний стан у React, і його варто застосовувати для стабільних або рідко змінюваних даних, аби уникати надмірних повторних рендерів.","import React, { createContext, useContext } from 'react';\\n\\nconst ThemeContext = createContext('light');\\nconst UserContext = createContext({ name: 'Guest' });\\n\\nfunction App() {\\n  return (\\n    <ThemeContext.Provider value=\\"dark\\">\\n      <UserContext.Provider value={{ name: 'Alice' }}>\\n        <MainContent />\\n      </UserContext.Provider>\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\nfunction MainContent() {\\n  const theme = useContext(ThemeContext);\\n  const user = useContext(UserContext);\\n  return <p>{user.name} is using the {theme} theme</p>;\\n}"],[2650,"Context у React дає змогу передавати дані (наприклад, тему, мову, користувача) через усе дерево компонентів без явного передавання пропсів на кожному рівні. Це розв'язує проблему прокидання пропсів, коли дані треба переспрямовувати через багато проміжних компонентів. Контекст створюють через createContext, надають через Provider і споживають через useContext або Consumer.","Що таке Context і для чого він потрібний\\nУ React дані звичайно передають згори вниз через пропси. Коли застосунок зростає, виникає ситуація, у якій глибоко вкладеному компонентові потрібні дані, що лежать у корені. Переспрямовувати їх через кожний проміжний компонент незручно, й це засмічує код — це називають прокиданням пропсів. Context розв'язує цю проблему, даючи змогу оголосити дані один раз і зробити їх доступними будь-якому компонентові в піддереві.\\n\\nЯк Context працює\\nContext складається з трьох частин: \`createContext\` створює об'єкт контексту, \`Provider\` обгортає дерево й передає значення, а \`useContext\` (або \`Consumer\`) дає компонентам змогу прочитати це значення. Коли значення в Provider змінюється, усі споживачі перемальовуються автоматично.\\n\\nТут \`Button\` отримує тему напряму, обходячи \`Toolbar\`. Це полегшує підтримку й робить код чистішим.\\n\\nКоли використовувати Context\\nContext ідеальний для глобальних даних, які змінюються рідко: теми оформлення, мови інтерфейсу, даних автентифікації, налаштувань користувача. Для даних, які змінюються часто (наприклад, стану форми), краще використовувати локальний стан або Redux, адже оновлення Context спричиняє перемалювання всіх споживачів, що може бути дорогим.\\n\\nВисновок\\nContext — потужний інструмент, щоб передавати метадані через дерево компонентів без пропсів. Застосовуйте його для глобальних налаштувань і для даних, потрібних багатьом компонентам, але уникайте його для високочастотних оновлень, аби не знижувати продуктивність.","const ThemeContext = React.createContext('light');\\n\\nfunction App() {\\n  return (\\n    <ThemeContext.Provider value=\\"dark\\">\\n      <Toolbar />\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\nfunction Toolbar() {\\n  return <Button />;\\n}\\n\\nfunction Button() {\\n  const theme = React.useContext(ThemeContext);\\n  return <button className={theme}>A button</button>;\\n}"],[2651,"useMemo потрібний, щоб кешувати результат обчислення між рендерами. Його варто використовувати, коли обчислення дороге (наприклад, складне сортування або фільтрація великого масиву) й залежить від пропсів чи стану, які не змінюються часто. Якщо обчислення просте або залежності змінюються на кожному рендері, useMemo лише додасть надлишкову роботу.","Що таке useMemo\\nuseMemo — хук React, який запам'ятовує результат виконання функції й повертає його на повторних рендерах, якщо залежності не змінилися. Це допомагає уникати повторних дорогих обчислень і стабілізувати посилання на об'єкти, що корисно задля оптимізації дочірніх компонентів.\\n\\nКоли його застосовувати\\nВикористовуйте useMemo, коли:\\n- Обчислення займає відчутний час (наприклад, обробка великих масивів, складні математичні операції).\\n- Результат використовують у залежностях інших хуків (наприклад, useEffect) або передають у мемоїзовані дочірні компоненти (React.memo).\\n- Залежності змінюються рідко, й ви хочете зберегти стабільне посилання на об'єкт.\\n\\nНе використовуйте useMemo для простих операцій (поєднання рядків, читання властивості) — це додасть накладні витрати на порівняння залежностей й утримання кешу.\\n\\nПриклад\\n\\nТут фільтрацію виконують лише тоді, коли items або filter змінюється, а не на кожному рендері.\\n\\nВисновок\\nuseMemo — інструмент задля точкової оптимізації. Застосовуйте його свідомо, коли є справжня проблема з продуктивністю або потреба в стабільних посиланнях. У решті випадків віддавайте перевагу простому коду без мемоїзації.","import { useMemo, useState } from 'react';\\n\\nfunction List({ items, filter }) {\\n  const filtered = useMemo(() => {\\n    return items.filter(item => item.name.includes(filter));\\n  }, [items, filter]);\\n\\n  return <ul>{filtered.map(item => <li key={item.id}>{item.name}</li>)}</ul>;\\n}"],[2652,"Actions — об'єкти, які описують намір змінити стан, наприклад { type: 'ADD_TODO', payload: 'купити молоко' }. Reducer — чиста функція, яка приймає поточний стан й action і повертає новий стан. Reducer не змінює початкового стану, а створює новий. Разом вони формують передбачуваний потік даних: компонент викликає action, Redux передає його в reducer, і стан оновлюється.","Основи Redux: actions і reducers\\nУ React Redux часто використовують, щоб керувати складним станом. Ключові концепції — actions і reducers. Actions — прості об'єкти, які описують, що сталося в застосунку. Вони містять обов'язкове поле \`type\` (рядок-ідентифікатор) й необов'язковий \`payload\` (дані). Наприклад, \`{ type: 'INCREMENT', payload: 1 }\`.\\n\\nReducer — чиста функція, яка визначає, як стан змінюється у відповідь на action. Вона приймає два аргументи: поточний стан й action, і повертає новий стан. Важливо, що reducer не мутує початкового стану, а створює його копію зі змінами. Це робить стан передбачуваним і легким задля тестування.\\n\\nПриклад коду\\n\\nУ цьому прикладі action creator повертає об'єкт action, який далі передають у reducer через \`dispatch\`. Reducer обробляє action і повертає новий стан. Такий підхід дає змогу керувати станом централізовано й легко відстежувати зміни.\\n\\nДе це застосовують\\nRedux використовують у великих React-застосунках, де багато компонентів обмінюються даними. Він особливо корисний у роботі із серверними даними, кешуванням, складними формами й спільним редагуванням. Однак для простих застосунків можна обійтися вбудованими \`useState\` або \`useReducer\`.\\n\\nПідсумовуючи: actions і reducers — фундамент Redux. Вони забезпечують передбачуване оновлення стану й полегшують зневадження й тестування. Застосовуйте Redux, коли стан стає складним і потребує глобального доступу від багатьох компонентів.","// an action creator\\nconst increment = (amount) => ({\\n  type: 'INCREMENT',\\n  payload: amount\\n});\\n\\n// a reducer\\nconst counterReducer = (state = 0, action) => {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return state + action.payload;\\n    case 'DECREMENT':\\n      return state - action.payload;\\n    default:\\n      return state;\\n  }\\n};\\n\\n// the usage in a store\\nconst store = createStore(counterReducer);\\nstore.dispatch(increment(5));\\nconsole.log(store.getState()); // 5"],[2653,"Ключі в React допомагають ідентифікувати елементи списку на оновленні. Вони дають React змогу точно зіставити старі й нові елементи, мінімізуючи перемалювання й уникаючи помилок зі станом. Без ключів React може оновити елементи неправильно, що призводить до багів і до зниженої продуктивності.","Для чого потрібні ключі в React?\\nКоли рендерять списки, React використовує алгоритм звірення, щоб порівняти попередній і новий стан віртуального DOM. Ключі — особливі атрибути, які допомагають React унікально ідентифікувати кожний елемент списку. Без ключів React не може точно визначити, який елемент змінили, додали або вилучили, що може призводити до некоректного оновлення інтерфейсу й до втрати стану компонентів.\\n\\nЯк це працює?\\nКоли ви рендерите масив елементів, React очікує, що кожний елемент має унікальний ключ. Цей ключ має бути стабільним й унікальним серед сусідніх елементів. React використовує ключі, щоб зіставляти елементи між рендерами: якщо ключ збігається, React вважає, що це той самий елемент, й оновлює його; якщо ключ новий, він додає елемент; якщо ключ зник, він вилучає елемент.\\n\\nУ цьому прикладі ключ — унікальний ідентифікатор \`id\`. Якщо ви використовуєте індекс масиву як ключ, це може спричиняти проблеми, коли порядок елементів змінюється, адже React зіставить елементи неправильно й може втратити стан (наприклад, текст, уведений в input).\\n\\nПрактичні рекомендації\\n\\n- Використовуйте стабільні унікальні ідентифікатори (наприклад, ID із бази даних) як ключі.\\n- Уникайте використання індексу масиву як ключа, якщо порядок елементів може змінюватися.\\n- Ключі мають бути унікальними лише серед сусідніх елементів, не обов'язково глобально.\\n- Не використовуйте випадкові значення (наприклад, Math.random()) як ключі, адже вони змінюватимуться на кожному рендері, що призведе до повного перемалювання списку.\\n\\nВисновок\\nКлючі — важливий інструмент задля оптимізації й коректності рендерингу списків у React. Вони дають React змогу ефективно оновлювати лише ті елементи, які змінилися, зберігаючи стан і покращуючи продуктивність. Завжди використовуйте стабільні унікальні ключі, аби уникати схованих багів і забезпечити передбачувану поведінку інтерфейсу.","// An example of a list with keys\\nconst items = [\\n  { id: 1, name: 'Apple' },\\n  { id: 2, name: 'Banana' },\\n  { id: 3, name: 'Cherry' }\\n];\\n\\nfunction FruitList() {\\n  return (\\n    <ul>\\n      {items.map(item => (\\n        <li key={item.id}>{item.name}</li>\\n      ))}\\n    </ul>\\n  );\\n}"],[2654,"React-хуки — функції, які дають змогу використовувати стан й інші можливості React у функційних компонентах. Основні хуки: useState, щоб керувати станом, useEffect задля побічних ефектів, useContext задля доступу до контексту, useReducer задля складної логіки стану, useMemo й useCallback задля оптимізації. Є також власні хуки, які створюють, щоб повторно використовувати логіку.","Що таке React-хуки?\\nReact-хуки з'явилися у версії 16.8 і змінили підхід до написання компонентів. Раніше стан і життєвий цикл були доступні лише в класових компонентах, але хуки дають змогу використовувати ці можливості у функційних компонентах. Це зробило код простішим і коротшим, а також покращило повторне використання логіки.\\n\\nОсновні вбудовані хуки\\n\\n- useState — він додає локальний стан. Він повертає масив із поточного значення плюс функції, щоб його оновити.\\n- useEffect — він виконує побічні ефекти (запити, підписки, таймери) після рендера. Можна керувати залежностями, щоб контролювати, коли ефект запускають.\\n- useContext — він дає змогу прочитати значення контексту, створеного через React.createContext, без прокидання пропсів через кожний рівень.\\n- useReducer — альтернатива useState для складнішої логіки стану, заснована на actions (схоже на Redux).\\n- useMemo — він мемоїзує результат обчислення, аби уникати повторних дорогих операцій на кожному рендері.\\n- useCallback — він мемоїзує функцію, щоб її не створювали заново на кожному рендері, якщо залежності не змінилися.\\n- useRef — він створює мутабельний об'єкт, який зберігається між рендерами; його часто використовують задля доступу до DOM-елементів.\\n\\nПриклад використання\\n\\nВласні хуки\\nВи можете створювати власні хуки, щоб вивести повторювану логіку. Наприклад, хук, щоб працювати з localStorage або обробляти форму. Власний хук — звичайна функція, яка використовує інші хуки всередині.\\n\\nВисновок\\nХуки — стандартний спосіб працювати зі станом й ефектами в сучасних React-застосунках. Вони роблять код простішим, покращують читність і дають змогу повторно використовувати логіку. Знання основних хуків обов'язкове для будь-якого React-розробника, а вміння створювати власні хуки — ознака доброго рівня.","import React, { useState, useEffect } from 'react';\\n\\nfunction Timer() {\\n  const [seconds, setSeconds] = useState(0);\\n\\n  useEffect(() => {\\n    const interval = setInterval(() => {\\n      setSeconds(prev => prev + 1);\\n    }, 1000);\\n    return () => clearInterval(interval); // the clean-up on the unmounting\\n  }, []); // an empty array — the effect runs once\\n\\n  return <div>Seconds elapsed: {seconds}</div>;\\n}"],[2655,"Локальний стан використовують для даних, які потрібні лише одному компонентові або його дітям — наприклад, тексту поля введення чи того, чи відкрите модальне вікно. Глобальний стан застосовують, коли дані потрібні багатьом компонентам на різних рівнях дерева — наприклад, даних користувача або кошика. Якщо дані використовують у кількох непов'язаних компонентах або їх часто оновлюють із різних місць, обирайте глобальний стан. У решті випадків локальний стан простіший й ефективніший.","Основна ідея\\nУ React стан — дані, які впливають на відображення компонента. Локальний стан зберігають усередині певного компонента через \`useState\` або \`useReducer\`, і він доступний лише йому й його дочірнім елементам через пропси. Глобальний стан — дані, доступні всьому застосунку або великій його частині, звичайно через контекст або через бібліотеки на кшталт Redux, Zustand чи MobX.\\n\\nКоли використовувати локальний стан\\nЛокальний стан ідеальний для ізольованих даних: значення поля введення, того, чи відкритий список, що розкривається, поточної вкладки. Він не потребує додаткових бібліотек, і його легко читати й тестувати. Якщо дані потрібні лише одному компонентові й його безпосереднім дітям, не виносьте їх назовні — це робить код простішим і зменшує кількість повторних рендерів.\\n\\nКоли використовувати глобальний стан\\nГлобальний стан виправданий, коли дані використовують у кількох непов'язаних компонентах — наприклад, авторизацію, налаштування теми, кошик. Він також корисний, якщо дані часто оновлюють із різних місць й треба уникати прокидання пропсів — передавання пропсів через багато рівнів. Глобальний стан полегшує синхронізацію, але він додає складності й може знижувати продуктивність із частими оновленнями.\\n\\nКритерії вибору\\n\\n- Якщо дані потрібні лише одному компонентові — локальний стан.\\n- Якщо дані потрібні кільком компонентам, але вони поряд одне з одним у дереві — їх можна передати через пропси, але, якщо це стає громіздким, краще глобальний стан.\\n- Якщо дані треба зберігати між сесіями або використовувати в різних частинах застосунку — глобальний стан.\\n- Якщо частота оновлень висока, а дані не критичні для всього застосунку — локальний стан.\\n\\nВисновок\\nПочинайте з локального стану й додавайте глобальний лише тоді, коли виникає справжня потреба. Це збереже код простим і продуктивним. Глобальний стан — потужний інструмент, але його надмірне використання ускладнює архітектуру й ускладнює тестування.","function SearchInput() {\\n  const [query, setQuery] = useState('');\\n  return <input value={query} onChange={e => setQuery(e.target.value)} />;\\n}\\n\\n// An example with Context\\nconst UserContext = createContext(null);\\nfunction App() {\\n  const [user, setUser] = useState(null);\\n  return <UserContext.Provider value={{ user, setUser }}>\\n    <Header />\\n    <Profile />\\n  </UserContext.Provider>;\\n}"],[2656,"Redux не потрібний, коли стан застосунку простий і локальний, коли складного обміну даними між компонентами немає або коли проєкт малий. У таких випадках достатньо useState, useReducer або Context API. Redux виправданий на великому масштабі, зі складною логікою й потребою в передбачуваному стані.","Коли Redux надлишковий\\nRedux — потужний інструмент, але його використання без потреби ускладнює код і збільшує час розробки. Основний сигнал, що Redux не потрібний, — простота стану. Якщо дані використовують лише всередині одного компонента або в кількох сусідніх, краще обійтися локальним станом через \`useState\` або \`useReducer\`.\\n\\nТакож Redux не потрібний, коли проєкт малий або це прототип. Додавання Redux потребує налаштування сховища, редюсерів й actions і підключення провайдера, що створює багато шаблонного коду. Для простих застосунків це невиправдані витрати.\\n\\nАльтернативи Redux\\n\\n- useState — для локального стану компонента.\\n- useReducer — для складнішої логіки всередині компонента.\\n- Context API — щоб передавати дані через дерево компонентів без пропсів, якщо оновлення нечасті.\\n- React Query / SWR — щоб керувати серверним станом і кешуванням.\\n\\nПриклад: коли Redux не потрібний\\n\\nТут немає сенсу приносити Redux — стан ізольований, й інші компоненти його не використовують.\\n\\nКоли Redux справді корисний\\n\\n- Великий застосунок із безліччю компонентів, які поділяють спільний стан.\\n- Складна логіка оновлення стану (наприклад, кошик із безліччю операцій).\\n- Потреба в зневадженні й у time-travel debugging.\\n- Командна розробка, де важливі однаковість і передбачуваність.\\n\\nВисновок: Redux варто застосовувати лише тоді, коли складність керування станом перевищує витрати на його впровадження. Для більшості малих і середніх проєктів достатньо вбудованих засобів React, що робить код простішим і швидшим у розробці.","// A simple application: a login form\\nfunction LoginForm() {\\n  const [email, setEmail] = useState('');\\n  const [password, setPassword] = useState('');\\n  // Local state is enough\\n  return <input value={email} onChange={e => setEmail(e.target.value)} />;\\n}"],[2657,"UI має показати індикатор очікування або оптимістичне оновлення з приміткою про статус. Наприклад, кнопка може стати неактивною з текстом «Збережено, застосовується...», а дані відображають із приміткою «очікує застосування». Це допомагає користувачеві зрозуміти, що дію прийняли, але результат ще не остаточний.","Проблема проміжних станів\\nУ системах, які використовують event sourcing або асинхронну обробку, подію можна зберегти в журналі, але ще не обробити й не застосувати до поточного стану. Користувач, надіславши дію, очікує негайного результату, але система може затримати застосування. Якщо просто не показувати нічого, користувач вирішить, що дія не спрацювала, й повторить її, створюючи дублікати.\\n\\nСтратегії відображення\\n\\n- Оптимістичне оновлення — ми показуємо передбачуваний результат одразу, але позначаємо його як «очікує підтвердження». Наприклад, у списку задач можна додати нову задачу з напівпрозорим тлом й іконкою годинника.\\n- Індикатор прогресу — ми показуємо спінер або смужку прогресу поряд із дією; наприклад, на кнопці «Зберегти» ми змінюємо текст на «Збереження...» й блокуємо повторне натискання.\\n- Рядок статусу або тост — ми виводимо повідомлення «Збережено, застосовується до системи» зі змогою скасувати або повторити.\\n\\nПриклад коду (React)\\n\\nВисновок\\nНалежне відображення проміжних станів критичне задля UX в асинхронних системах. Використовуйте оптимістичні оновлення з явними індикаторами статусу, аби уникати плутанини й повторних дій. Це особливо важливо у фінансових, замовних і спільних застосунках, де затримка застосування може бути відчутною.","function SaveButton({ onSave, isPending }) {\\n  return (\\n    <button onClick={onSave} disabled={isPending}>\\n      {isPending ? 'Saved, being applied...' : 'Save'}\\n    </button>\\n  );\\n}\\n\\n// The usage with a state hook\\nconst [isPending, setPending] = useState(false);\\nconst handleSave = async () => {\\n  setPending(true);\\n  await saveEvent(); // we save the event\\n  // we do not wait for the application, we show the status\\n  setPending(false); // or we leave it true until the confirmation\\n};"],[2658,"Гідратація — це процес, у якому React бере вже відрендерений на сервері HTML і «оживляє» його, підключаючи обробники подій і стан. Це дозволяє сторінці бути інтерактивною без повного перемалювання. У Next.js гідратація відбувається автоматично після завантаження JS-бандла.","Що таке гідратація?\\nГідратація — ключовий механізм у React і Next.js, який зв'язує серверний рендеринг (SSR) із клієнтським. Коли сервер надсилає HTML-розмітку, вона вже містить увесь контент, але не є інтерактивною. Гідратація — це процес, у якому React «оживляє цю статичну розмітку», прив'язуючи до неї віртуальне дерево компонентів, стан і обробники подій.\\nЯк це працює?\\nУ Next.js під час першого запиту сервер генерує HTML і надсилає його клієнтові. Браузер миттєво відображає контент, що покращує SEO й час до першого байта. Потім завантажується JavaScript-бандл, і React виконує гідратацію: він зіставляє наявний DOM із віртуальним деревом і додає інтерактивність. Якщо розмітка збігається, React не перемальовує сторінку, а лише підключає слухачі подій.\\n\\nЧому це має значення?\\nГідратація дозволяє поєднати переваги SSR (швидкий перший відгук, SEO) із перевагами SPA (інтерактивність, плавні переходи). Без неї сторінка була б статичною; з нею — повноцінним застосунком. У Next.js гідратація автоматична, але важливо уникати розбіжностей між серверним і клієнтським рендерингом, інакше React може видавати попередження.\\nВисновок\\nГідратація — міст між серверним і клієнтським рендерингом. Вона необхідна для створення швидких, інтерактивних застосунків на Next.js. Розуміння цього процесу допомагає уникати помилок під час роботи з SSR і оптимізувати продуктивність.","// An example: a component with useState\\nfunction Counter() {\\n  const [count, setCount] = useState(0);\\n  return <button onClick={() => setCount(count + 1)}>{count}</button>\\n}\\n\\n// The server renders the HTML: <button>0</button>\\n// After the hydration React adds the onClick and the state"],[2659,"CSR — це коли переглядач отримує мінімальний HTML і будує сторінку за допомогою JavaScript. SSR — це коли сервер генерує готовий HTML і надсилає його клієнтові. Основна відмінність: у CSR вміст з'являється після того, як JS виконався, а в SSR — одразу. SSR краще для SEO й задля першого малювання, а CSR — для інтерактивних застосунків.","Вступ до рендерингу\\nРендеринг — процес перетворення коду на видиму сторінку. У веброзробці є два основні підходи: клієнтський (CSR) і серверний (SSR). Вони визначають, де саме формують HTML, який бачить користувач.\\n\\nКлієнтський рендеринг (CSR)\\nІз CSR сервер надсилає переглядачеві порожню HTML-оболонку плюс посилання на JavaScript-бандл. Переглядач завантажує JS, виконує його й лише тоді створює вміст. Це основа Single Page Applications (SPA) — наприклад, застосунків у React або Vue.\\n\\nПлюси CSR: швидка навігація після першого завантаження, менше навантаження на сервер, плавні переходи. Мінуси: тривале перше завантаження, погане індексування пошуковими системами, якщо не налаштовано попередній рендеринг.\\n\\nСерверний рендеринг (SSR)\\nІз SSR сервер виконує JavaScript-код, формує повний HTML і надсилає його переглядачеві. Користувач бачить готову сторінку одразу, а JS приєднують задля інтерактивності. Це використовують у Next.js, Nuxt.js й у класичних серверних шаблонах.\\n\\nПлюси SSR: швидке перше малювання, добре SEO, він працює без JavaScript. Мінуси: більше навантаження на сервер, складніше кешування, затримка на кожному запиті.\\n\\nОсновні відмінності\\n\\n- Де формують HTML: у переглядачі (CSR) або на сервері (SSR).\\n- Час до першого вмісту: SSR швидший, CSR потребує, щоб JS завантажили.\\n- SEO: SSR індексують краще, CSR потребує додаткового налаштування.\\n- Інтерактивність: CSR дає плавніший UX після завантаження.\\n\\nВисновок\\nВибір між CSR і SSR залежить від задач. Для контентних сайтів, де важливе SEO, обирайте SSR. Для складних інтерактивних застосунків, де важлива швидкість навігації, підійде CSR. Сучасні фреймворки дають змогу поєднувати обидва підходи — наприклад, використовувати SSR для перших сторінок і CSR для внутрішніх.","// An example of CSR: the server delivers an empty div, React fills it\\n// index.html\\n<div id=\\"root\\"></div>\\n<script src=\\"bundle.js\\"><\/script>\\n\\n// App.js\\nReactDOM.render(<App />, document.getElementById('root'));\\n\\n// An example of SSR with Express and React\\napp.get('/', (req, res) => {\\n  const html = ReactDOMServer.renderToString(<App />);\\n  res.send(\`<div id=\\"root\\">\${html}</div>\`);\\n});"],[2660,"Hydration mismatch виникає, коли HTML, згенерований на сервері, відрізняється від того, що React очікує на рендері на клієнті. Це відбувається через нестабільні дані, випадкові значення, різницю в часових поясах або API переглядача. Проблеми включають помилки в консолі, втрату інтерактивності, скидання стану й повторний рендеринг. Щоб це розв'язати, треба синхронізувати дані між сервером і клієнтом, використовувати стабільні значення й перевіряти середовище.","Що таке hydration mismatch?\\nІз серверним рендерингом (SSR) React генерує HTML на сервері й надсилає його клієнтові. Далі на клієнті React «оживляє» цей HTML, приєднуючи обробники подій і створюючи віртуальне дерево. Якщо розмітка, створена на сервері, не відповідає тому, що React очікує на першому рендері на клієнті, виникає помилка гідрації — hydration mismatch.\\n\\nПричини\\nОсновні причини — використання нестабільних даних, які можуть відрізнятися між сервером і клієнтом. Наприклад, виклик \`Date.now()\` або \`Math.random()\` дасть різні значення. Різниця в часових поясах або в локалі, а також використання API переглядача, недоступних на сервері (наприклад, \`window\` чи \`document\`), також призводять до розбіжностей. Інша часта причина — умовний рендеринг, який залежить від стану, ініціалізованого по-різному на сервері й на клієнті.\\n\\nПроблеми, пов'язані з гідрацією\\n\\n- Помилки в консолі переглядача, які попереджають про невідповідність.\\n- Втрата інтерактивності: React може не приєднати обробники подій до правильних елементів.\\n- Скидання стану: якщо компонент перемалюється, введення користувача може втратитися.\\n- Повторний рендеринг: React може перемалювати дерево повністю, що знижує продуктивність.\\n\\nПриклад коду з проблемою\\n\\nЯк цього уникати\\nВикористовуйте стабільні дані, однакові на сервері й на клієнті. Для випадкових або часових значень застосовуйте відкладений рендер після гідрації — наприклад, за допомогою \`useEffect\`. Перевіряйте середовище через \`typeof window !== 'undefined'\` й уникайте прямого доступу до API переглядача під час рендера. Також можна використати бібліотеки, щоб синхронізувати стан, як-от Redux із серверним сховищем.\\n\\nВисновок\\nHydration mismatch — поширена проблема в SSR-застосунках, яку важливо розуміти, щоб створювати надійні, швидкі інтерфейси. Застосовуйте стабільні дані й відкладену ініціалізацію, аби уникати помилок і забезпечити плавну гідрацію.","function App() {\\n  const [time, setTime] = React.useState(new Date().toISOString());\\n  return <div>{time}</div>;\\n}\\n// The server: the time = 2025-01-01T00:00:00Z\\n// The client: the time = 2025-01-01T00:00:01Z (a difference of seconds)\\n// A mismatch arises"],[2661,"Щоб таблиця з важкими формулами не зависала, треба розбити обчислення на частини, використати віртуалізацію, щоб малювати лише видимі рядки, кешувати результати формул і виконувати складні обчислення у фоновому потоці (Web Worker). Також варто застосувати мемоїзацію й відкладене обчислення, щоб обчислювати заново лише ті осередки, які змінилися.","Проблема продуктивності таблиць\\nКоли таблиця містить тисячі рядків і складні формули, кожна операція введення або прокручування може спричиняти повторне обчислення всіх залежних осередків. Це призводить до блокування головного потоку переглядача, через що інтерфейс «зависає». Основна задача — мінімізувати обсяг роботи, яку виконують синхронно в UI-потоці.\\n\\nКлючові підходи\\n\\n- Віртуалізація: рендерте лише видимі рядки й стовпці, використовуючи бібліотеки на кшталт react-virtualized або tanstack-virtual. Це зменшує кількість DOM-вузлів і прискорює прокручування.\\n- Мемоїзація: кешуйте результати формул для кожного осередку, щоб на повторному обчисленні використати збережене значення, якщо вхідні дані не змінилися.\\n- Відкладене обчислення: обчислюйте формули заново лише для тих осередків, які змінилися, й для їхніх залежностей, а не для всієї таблиці.\\n- Web Workers: виконуйте важкі обчислення в окремому потоці, аби не блокувати UI. Головний потік отримує результат асинхронно.\\n\\nПриклад реалізації з мемоїзацією\\n\\nПриклад із Web Worker\\n\\nВисновок\\nЩоб таблиця з важкими формулами працювала плавно, поєднуйте віртуалізацію, мемоїзацію й фонове обчислення. Це особливо важливо для фінансових застосунків, редакторів даних й аналітичних панелей, де користувач очікує негайної реакції на своє введення.","const cache = new Map();\\nfunction computeCell(row, col, data) {\\n  const key = \`\${row}-\${col}\`;\\n  if (cache.has(key)) return cache.get(key);\\n  // A heavy formula — the sum of a range, for example\\n  const result = data.slice(0, row).reduce((sum, r) => sum + r[col], 0);\\n  cache.set(key, result);\\n  return result;\\n}\\n\\n// worker.js\\nself.onmessage = (e) => {\\n  const { rows, formula } = e.data;\\n  const result = rows.map(row => formula(row));\\n  self.postMessage(result);\\n};\\n\\n// main.js\\nconst worker = new Worker('worker.js');\\nworker.postMessage({ rows: data, formula: (r) => r.a + r.b });\\nworker.onmessage = (e) => updateTable(e.data);"],[2662,"Готова дизайн-система прискорює розробку, забезпечує узгодженість і зменшує вартість підтримки, але обмежує гнучкість і може не відповідати унікальним вимогам продукту. Власні компоненти дають повний контроль над дизайном і поведінкою, але вимагають більше часу й ресурсів і на розробку, і на підтримку. Вибір залежить від термінів, бюджету, специфіки продукту й довгострокових цілей команди.","Вступ\\nВибір між готовою дизайн-системою та розробкою власних компонентів — стратегічне рішення, яке впливає на швидкість розробки, якість продукту й вартість підтримки. Готові рішення, як-от Material UI, Ant Design або Bootstrap, пропонують перевірені компоненти й стилі, а власні компоненти дозволяють створити унікальний користувацький інтерфейс, який точно відповідає бренду та вимогам.\\nПереваги готових дизайн-систем\\nВикористання готової дизайн-системи дає швидкий старт: компоненти вже реалізовані, протестовані й задокументовані. Це скорочує час розробки й дозволяє команді зосередитися на бізнес-логіці. Такі системи також гарантують узгоджений інтерфейс, оскільки кожен компонент дотримується однакових правил. Наприклад, Material UI надає готові кнопки, форми, модальні вікна й тематизацію, що полегшує побудову адаптивних інтерфейсів.\\n\\nОбмеження готових рішень\\nОсновний недолік — обмежена гнучкість. Якщо продукт вимагає нестандартного дизайну або специфічної поведінки, доводиться перевизначати стилі й розширювати компоненти, що може призвести до конфліктів і ускладнити код. Готові системи також часто великі, що впливає на продуктивність, якщо не використовувати tree shaking.\\nПереваги власних компонентів\\nРозробка власних компонентів дає повний контроль над дизайном, доступністю й продуктивністю. Це ідеально для продуктів з унікальним брендом або складними вимогами. Наприклад, ви можете створити компонент, який досконало відповідає конкретному користувацькому сценарію, і оптимізувати його під конкретні потреби.\\n\\nНедоліки власних компонентів\\nЦе вимагає значного часу й ресурсів: кожен компонент потрібно спроєктувати, реалізувати, протестувати й підтримувати. Також зростає ризик не дотягнути до стандартів доступності й кросбраузерності, якщо команда не має достатнього досвіду.\\nВисновок\\nВикористання готової дизайн-системи виправдане для проєктів з обмеженими термінами й бюджетом, де мають значення швидкість і узгодженість. Власні компоненти варто розробляти, коли продукт вимагає унікального дизайну або високого ступеня кастомізації, а команда готова інвестувати в довготривалу підтримку. Оптимальним рішенням часто є гібридний підхід: використовувати готову систему як основу й розширювати її власними компонентами для специфічних задач.","// An example of using Material UI\\nimport Button from '@mui/material/Button';\\n\\nfunction App() {\\n  return <Button variant=\\"contained\\">Click me</Button>;\\n}\\n\\n// An example of a custom button component\\nfunction CustomButton({ children, onClick }) {\\n  return (\\n    <button onClick={onClick} style={{ padding: '10px', borderRadius: '8px' }}>\\n      {children}\\n    </button>\\n  );\\n}"],[2663,"Віртуальний DOM — легка копія реального DOM, яку React зберігає в пам'яті. Коли стан змінюється, React оновлює віртуальний DOM, порівнює його з попередньою версією (diffing) і застосовує до реального DOM лише мінімальні зміни. Це зменшує кількість дорогих операцій над реальним DOM і прискорює рендеринг.","Для чого потрібний віртуальний DOM?\\nПрямі зміни реального DOM справді затратні, адже щоразу, коли ви змінюєте елемент, переглядач обчислює стилі заново, перемальовує сторінку й оновлює дерево. Якщо робити багато таких змін підряд, це може призводити до відчутних затримок. Віртуальний DOM розв'язує цю проблему, даючи React змогу оптимізувати оновлення.\\n\\nReact зберігає віртуальний DOM як звичайний JavaScript-об'єкт, який описує структуру інтерфейсу. Коли стан компонента змінюється, React створює новий віртуальний DOM і порівнює його з попереднім. Цей процес називають звіренням. У результаті React визначає, які саме елементи змінилися, й оновлює в реальному DOM лише їх, а не перемальовує всю сторінку.\\n\\nЯк це працює на практиці?\\nУявіть, що у вас список із 1000 елементів, і ви хочете змінити лише один. Без віртуального DOM вам довелося б знайти цей елемент вручну й оновити його, що складно й схильно до помилок. Із React ви просто змінюєте стан, і React сам обчислює, що треба оновити.\\n\\nТут React порівнює старий і новий віртуальний DOM, знаходить елемент, який змінився, за його ключем й оновлює в реальному DOM лише його. Решта елементів залишаються незайманими.\\n\\nКоли використовувати віртуальний DOM?\\nВіртуальний DOM особливо корисний у застосунках із динамічним інтерфейсом, де дані змінюються часто: чатах, інформаційних панелях, формах із валідацією. Він також полегшує розробку, адже ви не думаєте про те, як ефективно оновити DOM вручну — React робить це за вас.\\n\\nПідсумовуючи: віртуальний DOM — шар оптимізації, який дає React змогу мінімізувати дорогі операції над реальним DOM, роблячи застосунки швидшими, а код простішим. Його варто використовувати в будь-якому React-застосунку, особливо в роботі з великими, часто оновлюваними інтерфейсами.","// An example: the update of one element in a list\\nfunction List({ items }) {\\n  const [list, setList] = useState(items);\\n\\n  const updateItem = (id, newText) => {\\n    setList(prev => prev.map(item => \\n      item.id === id ? { ...item, text: newText } : item\\n    ));\\n  };\\n\\n  return (\\n    <ul>\\n      {list.map(item => (\\n        <li key={item.id}>{item.text}</li>\\n      ))}\\n    </ul>\\n  );\\n}"],[2664,"UI-kit — набір компонентів інтерфейсу, які можна використовувати повторно, об'єднаних єдиним дизайном і логікою. Підходи включають класичні бібліотеки з готовими стилями, CSS-фреймворки й headless-компоненти, які відділяють логіку від візуального подання. Headless-компоненти надають лише поведінку й стан, а розмітку й стилі задає сам розробник, що дає гнучкість і контроль.","Що таке UI-kit і для чого він потрібний\\nUI-kit — колекція готових елементів інтерфейсу (кнопок, полів введення, модальних вікон тощо), які використовують, щоб прискорити розробку й підтримувати візуальну узгодженість. Він може включати не лише компоненти, а й дизайн-токени (кольори, шрифти, відступи) плюс документацію щодо використання.\\n\\nОсновні підходи до розробки UI-kit\\n\\n- Класичні бібліотеки компонентів — наприклад, Material UI або Ant Design. Вони надають готові стилі й поведінку, але часто обмежують кастомізацію.\\n- CSS-фреймворки — Bootstrap, Tailwind. Вони дають набір класів й утиліт, але не завжди покривають складну логіку.\\n- Headless-компоненти — вони відділяють логіку від подання. Бібліотека повертає лише стан й обробники, а розробник пише розмітку й стилі.\\n\\nЩо таке headless-компоненти\\nHeadless-компонент — функція або хук, який керує станом і поведінкою, але не рендерить розмітки. Наприклад, headless-хук для списку, що розкривається, може повертати \`isOpen\`, \`toggle\` й \`selectedItem\`, а розробник вирішує, як відобразити список — через \`div\`, \`ul\` чи щось інше.\\n\\nПереваги headless-підходу\\n\\n- Повна свобода в розмітці й стилях — легко адаптувати до бренду.\\n- Логіку використовують повторно між різними проєктами.\\n- Тестування стає легшим, адже залежності від DOM немає.\\n- Він зручний, щоб створювати дизайн-системи, де візуальна частина змінюється часто.\\n\\nВисновок\\nHeadless-компоненти варто застосовувати, коли потрібні максимальна гнучкість і контроль над виглядом, особливо у великих проєктах з унікальним дизайном. Класичні UI-kit придатні для швидкого старту, але headless-підхід кращий задля довгострокової підтримки й масштабування.","// An example of a headless hook for a modal window\\nfunction useModal() {\\n  const [isOpen, setIsOpen] = useState(false);\\n  const open = () => setIsOpen(true);\\n  const close = () => setIsOpen(false);\\n  return { isOpen, open, close };\\n}\\n\\n// The usage in a component\\nfunction MyModal() {\\n  const { isOpen, open, close } = useModal();\\n  return (\\n    <>\\n      <button onClick={open}>Open</button>\\n      {isOpen && (\\n        <div className=\\"custom-overlay\\">\\n          <div className=\\"custom-content\\">\\n            <p>The content</p>\\n            <button onClick={close}>Close</button>\\n          </div>\\n        </div>\\n      )}\\n    </>\\n  );\\n}"],[2665,"Так, якщо функцію оголошено всередині компонента й використовують у залежностях useEffect, її треба обгорнути в useCallback. Це запобігає створенню функції заново на кожному рендері, що інакше призвело б до нескінченного циклу викликів ефекту. Без useCallback функція буде новою на кожному рендері, й useEffect спрацьовуватиме щоразу.","Проблема з функціями в залежностях\\nУ React, коли ви використовуєте функцію в масиві залежностей useEffect, важливо, щоб ця функція була стабільною (щоб вона мала те саме посилання між рендерами). Якщо функцію оголошено всередині компонента, її створюють заново на кожному рендері. Це означає, що її посилання змінюється, й useEffect вважатиме, що залежність змінилася, спричиняючи виконання ефекту після кожного рендера. Це може призводити до нескінченного циклу, якщо ефект змінює стан.\\n\\nРішення з useCallback\\nuseCallback повертає мемоїзовану версію функції, яка змінюється лише тоді, коли змінюються її власні залежності. Обгорнувши функцію в useCallback, ви гарантуєте, що посилання на функцію залишається стабільним між рендерами, якщо її залежності не змінилися. Це дає useEffect змогу належно визначити, коли ефект справді треба перезапустити.\\n\\nУ цьому прикладі handleClick обгорнутий у useCallback із порожнім масивом залежностей, тому його створюють один раз, і він залишається стабільним. useEffect буде викликано лише на першому рендері, а не на кожному кліку.\\n\\nКоли useCallback використовувати не треба\\nЯкщо функцію не використовують у залежностях useEffect або в інших хуках на кшталт useMemo, обгортати її в useCallback не обов'язково. Також, якщо функцію оголошено поза компонентом або це чиста функція, яка не залежить від пропсів чи стану, її можна використовувати напряму без мемоїзації.\\n\\nВисновок\\nВикористовуйте useCallback для функцій, які передають у залежності useEffect чи useMemo або в дочірні компоненти, аби уникати зайвих повторних викликів і оптимізувати продуктивність. Це особливо важливо у великих застосунках, де надлишкові рендери можуть сповільнювати роботу.","import React, { useState, useEffect, useCallback } from 'react';\\n\\nfunction Component() {\\n  const [count, setCount] = useState(0);\\n\\n  // The function is stable until count changes\\n  const handleClick = useCallback(() => {\\n    setCount(c => c + 1);\\n  }, []);\\n\\n  useEffect(() => {\\n    console.log('Effect runs');\\n  }, [handleClick]);\\n\\n  return <button onClick={handleClick}>Click</button>;\\n}"],[2666,"Пряма мутація масиву в стані React порушує принцип немутабельності, що призводить до пропущених повторних рендерів, до непередбачуваної поведінки компонентів і до труднощів у зневадженні. React порівнює посилання на об'єкти стану, й, якщо посилання не змінилося, він вважає, що стан не змінився. Це також порушує роботу React.memo, PureComponent і хуків на кшталт useEffect, які залежать від ідентичності стану.","Проблема прямої мутації стану\\nУ React стан треба оновлювати немутабельно — тобто створенням нового об'єкта чи масиву, а не зміною наявного. Пряма мутація, наприклад через \`push\` або через зміну елемента за індексом, призводить до того, що посилання на об'єкт стану залишається тим самим. React використовує порівняння посилань (поверхневе порівняння), щоб визначати зміни, тому на мутації він не виявляє зміни й не запускає повторного рендера компонента.\\n\\nНаслідки\\n\\n- Компонент не перемальовується, й користувач бачить застарілі дані.\\n- Порушується робота \`React.memo\` і \`PureComponent\`, які оптимізують рендер на основі порівняння пропсів і стану.\\n- Хуки на кшталт \`useEffect\` із залежностями від стану не спрацьовують, адже посилання не змінилося.\\n- Зневадження й тестування стають складнішими, адже стан можна змінити в кількох місцях без контролю.\\n\\nНалежний підхід\\nЗамість мутації треба створити новий масив. Наприклад, щоб додати елемент, використовуйте \`concat\` або оператор розгортання; щоб вилучити — \`filter\`; щоб оновити — \`map\`.\\n\\nВисновок\\nНемутабельне оновлення стану — фундаментальний принцип React, який забезпечує передбачуваність, продуктивність і правильну роботу оптимізацій. Завжди створюйте нові об'єкти й масиви, коли змінюєте стан, аби уникати багів, які важко відловити, й забезпечити коректний рендер.","// Wrong (a mutation)\\nconst addItem = (item) => {\\n  state.push(item);\\n  setState(state);\\n};\\n\\n// Right (immutably)\\nconst addItem = (item) => {\\n  setState([...state, item]);\\n};\\n\\n// The update of an element\\nconst updateItem = (id, newValue) => {\\n  setState(state.map(item => item.id === id ? { ...item, ...newValue } : item));\\n};\\n\\n// The removal of an element\\nconst removeItem = (id) => {\\n  setState(state.filter(item => item.id !== id));\\n};"],[2667,"Високонавантажений інтерфейс — інтерфейс, який зберігає відгукливість і стабільність із великою кількістю одночасних користувачів, інтенсивною взаємодією й великими обсягами даних. Цього досягають через оптимізацію рендерингу, ефективне керування станом, кешування, віртуалізацію списків і мінімізацію мережевих запитів. Також важливо враховувати серверну інфраструктуру й балансування навантаження.","Що таке високонавантажений інтерфейс\\nВисоконавантажений інтерфейс — не просто гарний UI, а система, здатна обробляти тисячі запитів на секунду, не втрачаючи продуктивності. Основна мета — забезпечити плавну роботу (60 FPS), мінімальний час відгуку й відсутність блокувань під час взаємодії. Цього досягають комплексним підходом: від архітектури фронтенду до серверної оптимізації.\\n\\nКлючові аспекти\\n\\n- Оптимізація рендерингу: використання віртуалізації для списків (наприклад, react-window), мемоїзація компонентів, уникання надлишкових перемалювань.\\n- Керування станом: ефективне використання Redux або Context API, поділ стану на глобальний і локальний, використання селекторів, щоб мінімізувати обчислення.\\n- Мережеві запити: кешування відповідей, debouncing і throttling, використання WebSockets для реального часу, пагінація й поступове завантаження даних.\\n- Серверний бік: балансування навантаження, горизонтальне масштабування, використання CDN для статичних файлів, оптимізація API (GraphQL, gRPC).\\n\\nПрактичний приклад\\n\\nЦей код рендерить лише видимі рядки, а не всі 10 000, що значно зменшує навантаження на DOM.\\n\\nВисновок\\nСтворення високонавантажених інтерфейсів потребує системного підходу: оптимізації клієнтського боку, ефективного керування даними й масштабованої серверної інфраструктури. Це потрібно для продуктів із масовим використанням, як-от соціальних мереж, онлайн-банків або торгових платформ, де навіть невелика затримка може призводити до втрати користувачів.","// The virtualization of a list with react-window\\nimport { FixedSizeList as List } from 'react-window';\\n\\nconst Row = ({ index, style }) => (\\n  <div style={style}>Row {index}</div>\\n);\\n\\nconst Example = () => (\\n  <List height={600} itemCount={10000} itemSize={35} width=\\"100%\\">\\n    {Row}\\n  </List>\\n);"],[2668,"React.lazy обов'язково треба використовувати з компонентом Suspense. Suspense дає змогу показати запасний UI (наприклад, спінер), поки ліниво завантажуваний компонент ще не готовий. Без Suspense React видасть помилку, адже він не зможе обробити стан очікування завантаження.","Що таке React.lazy і для чого він потрібний\\nReact.lazy — функція, вбудована в React, яка дає змогу завантажувати компоненти лише тоді, коли вони справді потрібні. Це називають відкладеним завантаженням, або розділенням коду. Замість того щоб включати весь код в один великий бандл, ви розбиваєте застосунок на частини, які завантажують на вимогу. Це зменшує початковий розмір завантаження й прискорює старт застосунку.\\n\\nРоль Suspense\\nSuspense — компонент-обгортка, який повідомляє React, що всередині нього є асинхронна операція (наприклад, завантаження ліниво завантажуваного компонента). Поки завантаження не завершилося, Suspense відображає запасний вміст, переданий через проп \`fallback\`. Без Suspense React не знає, що показати під час очікування, й кидає помилку. Тому React.lazy завжди використовують у парі зі Suspense.\\n\\nПриклад використання\\n\\nУ цьому прикладі компонент Dashboard буде завантажено лише після того, як App відрендерили. Поки Dashboard завантажується, користувач побачить текст «Завантаження...».\\n\\nДе це застосовують\\nReact.lazy і Suspense корисні у великих застосунках, у яких є маршрути або важкі компоненти, не потрібні на старті. Наприклад, адміністративну сторінку, графіки або редактор коду можна завантажувати ліниво. Це покращує продуктивність і зменшує навантаження на мережу.\\n\\nПідсумовуючи\\nВикористовуйте React.lazy разом зі Suspense задля відкладеного завантаження компонентів. Це стандартний спосіб реалізувати розділення коду в React й обов'язкова умова, щоб ліниве завантаження працювало належно.","import React, { Suspense, lazy } from 'react';\\n\\nconst Dashboard = lazy(() => import('./Dashboard'));\\n\\nfunction App() {\\n  return (\\n    <Suspense fallback={<div>Loading...</div>}>\\n      <Dashboard />\\n    </Suspense>\\n  );\\n}"],[2669,"React.lazy дає змогу завантажувати компоненти лише тоді, коли вони справді потрібні, зменшуючи початковий розмір бандла. Задля цього використовують динамічний імпорт плюс обгортку в Suspense, яка показує запасний вміст під час завантаження. Це покращує продуктивність застосунку, особливо з великою кількістю маршрутів або з важкими компонентами.","Що таке React.lazy?\\nReact.lazy — функція, вбудована в React, яка дає змогу відкласти завантаження компонента до моменту його першого рендерингу. Замість того щоб включати весь код компонента в основний бандл застосунку, React.lazy використовує динамічний імпорт, який створює окрему частину. Цю частину завантажують асинхронно, коли компонент потрібний уперше.\\n\\nОсновна мета — зменшити початковий час завантаження, особливо для великих застосунків із безліччю маршрутів або з рідко використовуваними функціями. Це частина техніки розділення коду, яка розбиває код на частини й завантажує їх у міру потреби.\\n\\nЯк застосовувати React.lazy?\\nЩоб використати React.lazy, треба імпортувати компонент через динамічний імпорт й обгорнути його в компонент Suspense. Suspense приймає проп fallback, який відображають, поки лінивий компонент завантажується. Звичайно це спінер або заповнювач.\\n\\nУ цьому прикладі HeavyComponent буде завантажено лише після того, як App відрендериться. Якщо компонент не використовують одразу, його код не потрапляє в основний бандл.\\n\\nДе це застосовувати?\\nReact.lazy особливо корисний разом із React Router, задля лінивого завантаження сторінок. Наприклад, можна завантажувати кожну сторінку окремо, щоб користувач не завантажував увесь код застосунку одразу.\\n\\nТакий підхід скорочує початковий розмір бандла й прискорює завантаження першої сторінки.\\n\\nВисновок\\nReact.lazy — простий, ефективний спосіб оптимізувати продуктивність React-застосунків. Його варто застосовувати для великих компонентів, не потрібних на першому рендері, особливо для маршрутів або модальних вікон. Це допомагає зменшити час завантаження й покращити користувацький досвід.","import React, { Suspense, lazy } from 'react';\\n\\nconst HeavyComponent = lazy(() => import('./HeavyComponent'));\\n\\nfunction App() {\\n  return (\\n    <Suspense fallback={<div>Loading...</div>}>\\n      <HeavyComponent />\\n    </Suspense>\\n  );\\n}\\n\\nimport { BrowserRouter, Routes, Route } from 'react-router-dom';\\nimport { lazy, Suspense } from 'react';\\n\\nconst Home = lazy(() => import('./pages/Home'));\\nconst About = lazy(() => import('./pages/About'));\\n\\nfunction App() {\\n  return (\\n    <BrowserRouter>\\n      <Suspense fallback={<div>Loading page...</div>}>\\n        <Routes>\\n          <Route path=\\"/\\" element={<Home />} />\\n          <Route path=\\"/about\\" element={<About />} />\\n        </Routes>\\n      </Suspense>\\n    </BrowserRouter>\\n  );\\n}"],[2670,"React Hook Form дає змогу легко додати валідацію через правила, які передають у register. Можна використати вбудовані правила (required, minLength, pattern) або власні функції validate. Помилки доступні в об'єкті errors, а повідомлення виводять через errors.field.message. Для складних сценаріїв застосовують resolver із Yup або Zod.","Основи валідації в React Hook Form\\nReact Hook Form — бібліотека, щоб керувати формами в React, яка мінімізує кількість повторних рендерів і полегшує валідацію. Валідацію налаштовують безпосередньо в методі register, який прив'язує поле до стану форми. Ви передаєте об'єкт із правилами, й бібліотека перевіряє значення автоматично на надсиланні або на зміні.\\n\\nВбудовані правила покривають більшість базових випадків: required (обов'язкове поле), minLength/maxLength (довжина), pattern (регулярний вираз), min/max (числові межі). Для складнішої логіки використовують функцію validate, яка повертає true або рядок із помилкою.\\n\\nПриклад базової валідації\\n\\nВласна валідація через validate\\nЯкщо треба перевірити, наприклад, що пароль містить цифру, використовуйте функцію validate. Вона отримує поточне значення поля й має повернути true або рядок із помилкою.\\n\\nІнтеграція з Yup або Zod\\nДля складних схем валідації зручно використовувати resolver. Установіть @hookform/resolvers й оберіть схему Yup або Zod. Це дає змогу перенести правила в окремий файл і використовувати їх повторно.\\n\\nВисновок\\nReact Hook Form надає гнучкі, продуктивні інструменти задля валідації. Для простих форм достатньо вбудованих правил, а для складних використовуйте resolver із Yup або Zod. Це робить код чистим і таким, що легко підтримувати, особливо у великих проєктах.","import { useForm } from 'react-hook-form';\\n\\nfunction MyForm() {\\n  const { register, handleSubmit, formState: { errors } } = useForm();\\n\\n  const onSubmit = (data) => console.log(data);\\n\\n  return (\\n    <form onSubmit={handleSubmit(onSubmit)}>\\n      <input {...register('email', {\\n        required: 'The email is required',\\n        pattern: {\\n          value: /^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$/,\\n          message: 'An incorrect email'\\n        }\\n      })} />\\n      {errors.email && <p>{errors.email.message}</p>}\\n\\n      <input {...register('age', {\\n        min: { value: 18, message: 'The age has to be ≥ 18' }\\n      })} />\\n      {errors.age && <p>{errors.age.message}</p>}\\n\\n      <button type=\\"submit\\">Send</button>\\n    </form>\\n  );\\n}\\n\\nregister('password', {\\n  validate: (value) =>\\n    /\\\\d/.test(value) || 'The password has to contain a digit'\\n})\\n\\nimport { yupResolver } from '@hookform/resolvers/yup';\\nimport * as yup from 'yup';\\n\\nconst schema = yup.object({\\n  email: yup.string().email().required(),\\n  age: yup.number().min(18).required()\\n});\\n\\nuseForm({ resolver: yupResolver(schema) });"],[2671,"Так, підхід змінюється. Для об'єктів із глибокою вкладеністю поверхнева копія (наприклад, через розгортання) копіює лише верхній рівень, а вкладені об'єкти залишаються спільними посиланнями. Щоб повністю зберегти початкове значення, треба використати глибоку копію: JSON.parse(JSON.stringify(obj)) або structuredClone(). Вибір залежить від того, чи є там функції, дати або інші несеріалізовувані дані.","Проблема поверхневого копіювання\\nКоли об'єкт має вкладені структури (об'єкти всередині об'єктів, масиви об'єктів), просте копіювання через оператор розгортання або Object.assign створює новий об'єкт, але внутрішні посилання залишаються тими самими. Це означає, що зміна вкладеної властивості в копії змінить і оригінал, що часто призводить до неочікуваних багів.\\n\\nГлибоке копіювання\\nЩоб повністю зберегти початкове значення, треба рекурсивно скопіювати всі вкладені об'єкти. У JavaScript є кілька способів:\\n- Методи JSON: JSON.parse(JSON.stringify(obj)) — просто, але це втрачає функції, undefined, символи й дати (перетворюючи їх на рядки).\\n- structuredClone(): сучасний вбудований метод; він підтримує більшість типів, включно з Date, Map і Set, але не функції.\\n- Рекурсивна функція: повний контроль; можна обробити будь-які типи, але це потребує ручної реалізації.\\n\\nКоли який підхід використовувати\\nЯкщо об'єкт містить лише серіалізовувані дані (рядки, числа, масиви, прості об'єкти), придатний метод JSON. Якщо там є Date, Map, Set або інші особливі типи, використовуйте structuredClone. Задля максимальної гнучкості (якщо треба, наприклад, зберегти функції) напишіть власну рекурсивну функцію. У реальних проєктах глибоке копіювання часто застосовують у роботі зі станом у Redux, де мутацій треба уникати, або коли клонують складні конфігурації.\\n\\nПідсумовуючи: коли вкладеність зростає, обов'язково переходьте від поверхневого копіювання до глибокого, обираючи метод за типами даних. Це запобігає випадковим змінам початкових об'єктів і робить код передбачуваним.","const original = { user: { name: 'Alice', address: { city: 'NYC' } } };\\nconst shallowCopy = { ...original };\\nshallowCopy.user.address.city = 'LA';\\nconsole.log(original.user.address.city); // 'LA' — the original has been changed!\\n\\n// structuredClone — the modern way\\nconst deepCopy = structuredClone(original);\\ndeepCopy.user.address.city = 'Boston';\\nconsole.log(original.user.address.city); // 'NYC' — the original is untouched\\n\\n// A recursive function for complete control\\nfunction deepClone(obj) {\\n  if (obj === null || typeof obj !== 'object') return obj;\\n  if (Array.isArray(obj)) return obj.map(deepClone);\\n  const cloned = {};\\n  for (let key in obj) {\\n    cloned[key] = deepClone(obj[key]);\\n  }\\n  return cloned;\\n}"],[2672,"Так, селектор іншого модуля викликати можна, якщо він приймає весь стан або його частину. Краще організувати це через композицію селекторів: експортуйте базові селектори з модуля й використовуйте їх в інших модулях, передаючи потрібний зріз стану. Це зберігає інкапсуляцію й полегшує тестування.","Вступ\\nУ Redux селектори — чисті функції, які приймають стан і повертають похідні дані. Вони допомагають уникати дубльованої логіки й полегшують тестування. Питання виклику селектора одного модуля з іншого виникає, коли проєктують великі застосунки, де стан розбивають на кілька зрізів.\\n\\nБазова концепція\\nСелектори можуть бути двох типів: глобальні (вони приймають весь стан) і локальні (вони приймають лише власний зріз). Якщо селектор модуля написано як локальний, він очікує на вході лише власний підоб'єкт стану. Щоб використати його в іншому модулі, треба передати відповідний зріз із глобального стану. Це роблять через композицію: в іншому модулі створюють новий селектор, який спочатку видобуває потрібний зріз, а потім викликає локальний селектор.\\n\\nПриклад\\nНехай є модуль \`users\` із селектором \`selectUserById\`, який приймає зріз \`state.users\` плюс id:\\n\\nУ модулі \`posts\` треба отримати автора посту. Ми можемо імпортувати цей селектор і передати йому зріз із глобального стану:\\n\\nТут \`selectPostAuthor\` використовує селектор з іншого модуля, передаючи йому \`state.users\`. Це можливо, адже селектор \`selectUserById\` не залежить від глобального стану, а працює зі зрізом, який йому дають.\\n\\nНайкращі практики\\n\\n- Експортуйте локальні селектори з кожного модуля, щоб їх можна було використовувати повторно.\\n- Уникайте створення селекторів, які звертаються до глобального стану напряму всередині модуля — це ускладнює тестування й повторне використання.\\n- Використовуйте композицію селекторів, щоб створювати нові селектори на основі наявних.\\n- Для складних залежностей можна використати бібліотеку \`reselect\`, яка підтримує мемоїзацію й полегшує композицію.\\n\\nВисновок\\nВиклик селектора іншого модуля — звичайна практика, якщо селектори написано як чисті функції, що приймають зріз стану. Організуйте модулі так, щоб кожний експортував власні локальні селектори, й поєднуйте їх в інших модулях, передаючи потрібний зріз. Це зберігає чистоту архітектури й полегшує підтримку коду.","// users/selectors.js\\nexport const selectUserById = (usersState, id) =>\\n  usersState.entities[id];\\n\\n// posts/selectors.js\\nimport { selectUserById } from '../users/selectors';\\n\\nexport const selectPostAuthor = (state, postId) => {\\n  const post = state.posts.entities[postId];\\n  return selectUserById(state.users, post.authorId);\\n};"],[2673,"Slice у Redux Toolkit об'єднує редюсери, actions і селектори для одного фрагмента стану. Найкращі практики включають: поділ стану на логічні модулі, використання createSlice, щоб зменшити шаблонний код, уникання мутацій через Immer, нормалізацію даних, виділення селекторів в окремі функції й використання createAsyncThunk для асинхронних операцій.","Вступ до slice\\nSlice — ключова концепція Redux Toolkit, яка дає змогу об'єднати редюсер, actions і селектори для певної частини стану. Це полегшує розробку, зменшує обсяг шаблонного коду й робить код читнішим. Однак, щоб використовувати slice ефективно, важливо дотримуватися певних практик.\\n\\nОсновні найкращі практики\\n\\n- Розділяйте стан на логічні модулі: кожний slice має відповідати за одну функціональну область (наприклад, користувачів, кошик, фільтри). Це полегшує підтримку й тестування.\\n- Використовуйте createSlice: він генерує actions і редюсери автоматично, що зменшує дублювання коду. Наприклад, замість того щоб створювати типи actions й action creators вручну, ви просто описуєте редюсери.\\n- Уникайте мутацій напряму: Redux Toolkit використовує Immer, тому в редюсерах можна писати мутуючий код, але це не означає, що ним варто зловживати. Намагайтеся повертати нові об'єкти там, де це можливо, щоб зберегти передбачуваність.\\n- Нормалізуйте дані: для складних вкладених структур використовуйте нормалізацію (наприклад, за допомогою createEntityAdapter). Це полегшує оновлення й пошук елементів.\\n- Виділяйте селектори: визначайте селектори у файлі slice або окремо, щоб використовувати їх повторно в компонентах. Це покращує продуктивність і читність.\\n- Використовуйте createAsyncThunk для асинхронних операцій: це стандартний спосіб обробляти запити до API, який керує станами pending, fulfilled і rejected автоматично.\\n\\nПриклад коду\\n\\nДе це застосовувати\\nЦі практики корисні в будь-якому React-застосунку, який використовує Redux, особливо коли стан стає складним. Вони допомагають тримати чистоту коду й полегшують тестування й масштабування.\\n\\nВисновок\\nДотримуючись цих найкращих практик, ви створюєте передбачуваний стан, який легко підтримувати. Використовуйте slice задля модульності, createAsyncThunk задля асинхронності, а нормалізацію — для складних даних; це зробить ваш застосунок надійнішим і зручнішим у розробці.","import { createSlice, createAsyncThunk, createEntityAdapter } from '@reduxjs/toolkit';\\n\\nconst usersAdapter = createEntityAdapter();\\n\\n// An asynchronous thunk for loading the users\\nexport const fetchUsers = createAsyncThunk('users/fetchUsers', async () => {\\n  const response = await fetch('/api/users');\\n  return response.json();\\n});\\n\\nconst usersSlice = createSlice({\\n  name: 'users',\\n  initialState: usersAdapter.getInitialState({ status: 'idle' }),\\n  reducers: {\\n    // The synchronous reducers\\n    userAdded: usersAdapter.addOne,\\n    userRemoved: usersAdapter.removeOne,\\n  },\\n  extraReducers: (builder) => {\\n    builder\\n      .addCase(fetchUsers.pending, (state) => { state.status = 'loading'; })\\n      .addCase(fetchUsers.fulfilled, (state, action) => {\\n        state.status = 'succeeded';\\n        usersAdapter.setAll(state, action.payload);\\n      })\\n      .addCase(fetchUsers.rejected, (state) => { state.status = 'failed'; });\\n  },\\n});\\n\\n// The selectors\\nexport const { selectAll: selectAllUsers, selectById: selectUserById } = usersAdapter.getSelectors((state) => state.users);\\nexport const selectUsersStatus = (state) => state.users.status;\\n\\nexport const { userAdded, userRemoved } = usersSlice.actions;\\nexport default usersSlice.reducer;"],[2674,"Щоб useEffect реагував на зміни окремих полів об'єкта, треба передавати в масив залежностей самі поля, а не об'єкт загалом. Наприклад, замість об'єкта user передавайте user.name і user.age. Якщо поля динамічні, можна використати useMemo, щоб створити стабільне посилання на об'єкт із потрібними полями.","Проблема з об'єктами в залежностях\\nУ React, коли ви передаєте об'єкт у масив залежностей useEffect, ефект спрацьовує лише тоді, коли посилання на цей об'єкт змінюється. Якщо ви мутуєте об'єкт (наприклад, змінюєте одне з його полів), посилання залишається тим самим, й ефект не запускають. Це часта причина багів, коли розробники очікують реакції на зміну полів.\\n\\nРішення: передавайте окремі поля\\nНайпростіший спосіб — зазначити в залежностях конкретні поля об'єкта. Наприклад:\\n\\nТакий підхід працює, якщо ви знаєте, які поля важливі. Якщо полів багато або вони динамічні, можна використати useMemo, щоб створити об'єкт із потрібними полями:\\n\\nТут useMemo повертає новий об'єкт лише тоді, коли зазначені поля змінюються, тому ефект спрацює належно.\\n\\nПрактичні рекомендації\\n\\n- Уникайте передавання всього об'єкта в залежності, якщо потрібна реакція на окремі поля.\\n- Використовуйте useMemo, щоб стабілізувати посилання на об'єкти, які залежать від кількох полів.\\n- Пам'ятайте, що мутація об'єкта без зміни посилання не спричинить ефекту — завжди створюйте новий об'єкт через setState.\\n\\nВисновок: щоб useEffect працював належно з об'єктами, завжди зазначайте в залежностях конкретні поля або використовуйте useMemo, щоб створити стабільне посилання. Це робить код передбачуваним й уникає надлишкових спрацювань ефекту.","const [user, setUser] = useState({ name: 'Alice', age: 25 });\\n\\nuseEffect(() => {\\n  console.log('Name changed:', user.name);\\n}, [user.name]); // it responds only to a change of name\\n\\nconst importantFields = useMemo(() => ({ name: user.name, age: user.age }), [user.name, user.age]);\\n\\nuseEffect(() => {\\n  console.log('Important fields changed:', importantFields);\\n}, [importantFields]);"],[2675,"У Redux дані рухаються строго в одному напрямі. Компонент викликає dispatch(action), action доходить до редюсера, який повертає новий стан. Сховище зберігає стан і сповіщає підписані компоненти, які перемальовуються з новими даними. Це робить потік передбачуваним і легким для відстежування.","Основна ідея\\nRedux — бібліотека, щоб керувати станом, яка використовує однонапрямлений потік даних. Це означає, що дані завжди рухаються по одному колу: компонент → action → редюсер → сховище → компонент. Такий підхід полегшує зневадження й робить поведінку застосунку передбачуваною.\\n\\nПовний цикл\\n\\n- Компонент викликає \`dispatch(action)\` — це єдиний спосіб змінити стан.\\n- Action — простий об'єкт із полем \`type\` й, за потреби, \`payload\`.\\n- Редюсер — чиста функція, яка приймає поточний стан й action і повертає новий стан.\\n- Сховище зберігає новий стан і сповіщає всіх підписників через \`subscribe\`.\\n- Компоненти, під'єднані через \`connect\` або \`useSelector\`, отримують оновлені дані й перемальовуються.\\n\\nПриклад коду\\n\\nЧому це важливо\\nОднонапрямлений потік полегшує відстежування змін: ви завжди знаєте, звідки дані прийшли і як вони змінилися. Це особливо корисно у великих застосунках, де багато компонентів поділяють стан. Redux також підтримує middleware (наприклад, Redux Thunk або Saga) для асинхронних actions, але базовий потік залишається незмінним.\\n\\nПідсумовуючи: Redux варто застосовувати, коли стан застосунку стає складним і потребує передбачуваного керування. Він особливо корисний у великих проєктах із безліччю взаємодіючих компонентів, де важливі централізоване зберігання даних і зрозуміла логіка їхньої зміни.","// An action creator\\nconst addTodo = (text) => ({\\n  type: 'ADD_TODO',\\n  payload: text\\n});\\n\\n// A reducer\\nconst todosReducer = (state = [], action) => {\\n  switch (action.type) {\\n    case 'ADD_TODO':\\n      return [...state, { text: action.payload, done: false }];\\n    default:\\n      return state;\\n  }\\n};\\n\\n// A component\\nconst TodoInput = ({ dispatch }) => {\\n  const handleSubmit = (e) => {\\n    e.preventDefault();\\n    dispatch(addTodo(inputValue));\\n  };\\n  return <form onSubmit={handleSubmit}>...</form>;\\n};\\n\\n// The connection\\nconst mapDispatchToProps = { addTodo };\\nexport default connect(null, mapDispatchToProps)(TodoInput);"],[2676,"Ні, дані в редюсері мутувати не можна. Redux вимагає, щоб стан оновлювали немутабельно, повертаючи новий об'єкт. Для масивів використовуйте оператор розгортання, map, filter або concat. Для об'єктів — оператор розгортання чи Object.assign. Це гарантує передбачуваність і належну роботу перемалювань React.","Чому немутабельність критична в Redux\\nRedux побудований на принципі, що стан — немутабельний об'єкт. Щоразу, коли ви хочете змінити стан, ви створюєте новий об'єкт, а не модифікуєте старий. Це дає Redux змогу відстежувати зміни через порівняння посилань, що робить застосунок передбачуваним і полегшує зневадження. Якщо ви мутуєте стан напряму, React може не виявити зміни, й UI не оновиться.\\n\\nЯк належно оновлювати масиви\\nДля масивів використовуйте методи, які повертають новий масив: \`map\`, \`filter\`, \`concat\` або оператор розгортання. Наприклад, щоб додати елемент:\\n\\nЩоб вилучити елемент, використовуйте \`filter\`:\\n\\nЩоб оновити певний елемент — \`map\`:\\n\\nЯк належно оновлювати об'єкти\\nДля об'єктів використовуйте оператор розгортання або \`Object.assign\`. Наприклад:\\n\\nЯкщо об'єкт вкладений, оновлюйте кожний рівень окремо, аби не втратити інші поля.\\n\\nПрактичні рекомендації\\n\\n- Ніколи не використовуйте \`push\`, \`splice\` або пряме присвоювання властивостей.\\n- Для складних структур можна використати бібліотеки на кшталт Immer, які дають змогу писати мутабельний код, але створюють немутабельні оновлення автоматично.\\n- Пам'ятайте, що немутабельність — не лише правило Redux, а й добра практика для будь-якого складного стану.\\n\\nВисновок: немутабельність у Redux — фундаментальна вимога, яка забезпечує передбачуваність і продуктивність. Завжди повертайте новий об'єкт стану, використовуючи оператор розгортання або методи, які повертають нові масиви. Щоб полегшити роботу з глибокими структурами, можна застосувати Immer.","case 'ADD_TODO':\\n  return {\\n    ...state,\\n    todos: [...state.todos, action.payload]\\n  };\\n\\ncase 'REMOVE_TODO':\\n  return {\\n    ...state,\\n    todos: state.todos.filter(todo => todo.id !== action.payload)\\n  };\\n\\ncase 'TOGGLE_TODO':\\n  return {\\n    ...state,\\n    todos: state.todos.map(todo =>\\n      todo.id === action.payload ? { ...todo, completed: !todo.completed } : todo\\n    )\\n  };\\n\\ncase 'UPDATE_USER':\\n  return {\\n    ...state,\\n    user: {\\n      ...state.user,\\n      name: action.payload.name\\n    }\\n  };"],[2677,"Функцію передають у useState задля лінивої ініціалізації стану. React викликає її лише на першому рендері компонента, а не на кожному оновленні. Це корисно, коли початкове значення потребує складного обчислення або читання з localStorage, аби не виконувати цього повторно. Замість того щоб значення обчислювали на кожному рендері, функція виконується один раз.","Що таке лінива ініціалізація в useState\\nКоли ви передаєте функцію як початкове значення в \`useState\`, React викликає її лише один раз — на першому рендері компонента. Це називають лінивою ініціалізацією. На відміну від передавання звичайного значення, яке обчислюють на кожному рендері (навіть якщо результат не використовують), функція гарантує, що дорогі операції виконують лише один раз.\\n\\nПриклад зі звичайним значенням\\n\\nТут \`expensiveFunction()\` буде викликано на кожному рендері, навіть якщо стан уже ініціалізовано. Це може призводити до непотрібних обчислень.\\n\\nПриклад із лінивою ініціалізацією\\n\\nТепер функція виконується лише на першому рендері. Це особливо корисно для складних обчислень, задля читання з localStorage або задля парсингу великих даних.\\n\\nКоли це застосовувати\\n\\n- Коли початкове значення потребує важких обчислень.\\n- Коли дані треба прочитати з localStorage або sessionStorage.\\n- Коли початкове значення залежить від зовнішніх даних, які не змінюються.\\n\\nВисновок\\nВикористовуйте функцію в \`useState\`, щоб оптимізувати продуктивність, коли ініціалізація стану потребує значних ресурсів. Це проста практика, яка допомагає уникати надлишкових обчислень і робить код передбачуванішим.","const [state, setState] = useState(expensiveFunction()); // it is called on every render\\n\\nconst [state, setState] = useState(() => expensiveFunction()); // it is called only once"],[2678,"useCallback повертає мемоїзовану версію функції, яка змінюється лише тоді, коли змінюються залежності. Це допомагає уникати надлишкових повторних рендерів дочірніх компонентів, обгорнутих у React.memo, і стабілізувати посилання на функції задля ефектів. Його використовують задля оптимізації, але він не гарантує прискорення, якщо залежності змінюються часто.","Що таке useCallback\\nuseCallback — хук React, який повертає мемоїзовану (закешовану) версію функції. Він приймає два аргументи: саму функцію й масив залежностей. React запам'ятовує функцію й повертає те саме посилання, доки залежності не зміняться. Це дає змогу уникати створення нової функції на кожному рендері, що важливо задля продуктивності в деяких сценаріях.\\n\\nДля чого він потрібний\\nУ React на кожному рендері компонента всі функції, оголошені всередині нього, створюють заново. Якщо таку функцію передають у дочірній компонент, обгорнутий у React.memo, мемоїзація дочірнього компонента не спрацює, адже пропси (посилання на функцію) будуть новими щоразу. useCallback розв'язує цю проблему, зберігаючи стабільне посилання. Він також корисний для ефектів, які залежать від функції, аби не викликати їх зайвий раз.\\n\\nПриклад використання\\n\\nУ цьому прикладі Child не рендериться повторно, коли count змінюється, адже handleClick не змінюється. Без useCallback Child рендерився б повторно щоразу, адже посилання на функцію було б новим.\\n\\nКоли це застосовувати\\nuseCallback варто використовувати, коли функцію передають у мемоїзовані дочірні компоненти або використовують у залежностях useEffect. Однак обгортати кожну функцію не варто — це може додавати надлишкові обчислення. Оптимізація виправдана, якщо компонент важкий або рендериться часто.\\n\\nПідсумовуючи: useCallback допомагає стабілізувати посилання на функції й покращити продуктивність React-застосунків, але його варто застосовувати свідомо, лише там, де він справді дає виграш.","import React, { useCallback, useState } from 'react';\\n\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n\\n  const handleClick = useCallback(() => {\\n    setCount(c => c + 1);\\n  }, []); // empty dependencies — the function is stable\\n\\n  return <Child onClick={handleClick} />;\\n}\\n\\nconst Child = React.memo(({ onClick }) => {\\n  console.log('Child re-rendered');\\n  return <button onClick={onClick}>Click</button>;\\n});"],[2679,"Мікрофронтенди — архітектурний підхід, який розбиває застосунок на незалежні частини, що розробляють і розгортають окремо, але збирають в єдиний інтерфейс. Вебкомпоненти — стандарт переглядача, щоб створювати UI-елементи для повторного використання з інкапсуляцією стилів і логіки. Мікрофронтенди розв'язують проблему масштабування команди й незалежного розгортання, а вебкомпоненти — проблему ізоляції й повторного використання коду.","Вступ\\nКоли застосунок зростає, команди часто стикаються з потребою використати різні технології або фреймворки в одному продукті. Два популярні способи розв'язати цю задачу — мікрофронтенди й вебкомпоненти. Вони розв'язують різні проблеми, хоч іноді їх плутають.\\n\\nМікрофронтенди\\nМікрофронтенди — архітектурний патерн, у якому фронтенд розбивають на кілька незалежних модулів (мікрофронтендів). Кожний модуль може розробляти окрема команда, він може використовувати власний технологічний стек і розгортатися незалежно. Інтеграція відбувається на рівні застосунку: або через iframe, або через JavaScript-контракт, або через серверне збирання.\\n\\nПриклад: у вас є інтернет-крамниця. Модуль каталогу написано в React, модуль кошика — у Vue, а модуль оплати — в Angular. Усі вони збираються в єдиний інтерфейс, але працюють як окремі застосунки.\\n\\nВебкомпоненти\\nВебкомпоненти — набір стандартів переглядача (Custom Elements, Shadow DOM, HTML Templates), які дають змогу створювати власні HTML-теги з інкапсульованою логікою й стилями. Вони не залежать від фреймворка, і їх можна використовувати в будь-якому застосунку, написаному в будь-якому стеку.\\n\\nПриклад: ви створюєте компонент \`<user-card>\`, який відображає картку користувача. Цей компонент можна використовувати в React, у Vue й у чистому JavaScript.\\n\\nКлючові відмінності\\n\\n- Рівень інтеграції: мікрофронтенди інтегрують цілі застосунки, а вебкомпоненти — окремі елементи інтерфейсу.\\n- Незалежність: мікрофронтенди дають змогу розробляти й розгортати цілі модулі незалежно, а вебкомпоненти — лише UI-частини для повторного використання.\\n- Технології: мікрофронтенди можуть використовувати різні фреймворки, а вебкомпоненти — стандарт переглядача, незалежний від будь-якого фреймворка.\\n- Складність: мікрофронтенди потребують складної інфраструктури (оркестрації, спільної маршрутизації), а вебкомпоненти простіше використовувати.\\n\\nКоли що обирати\\nМікрофронтенди придатні для великих продуктів із кількома командами, де потрібна незалежність розробки й розгортання. Вебкомпоненти придатні, щоб створити бібліотеку UI-елементів для повторного використання, які мають працювати в будь-якому середовищі.\\n\\nВисновок\\nМікрофронтенди й вебкомпоненти розв'язують різні задачі: перші — організаційні й архітектурні, другі — технічні й на рівні UI. Їх можна поєднувати: наприклад, усередині мікрофронтенду можна використовувати вебкомпоненти, щоб ізолювати частини інтерфейсу. Вибір залежить від масштабу проєкту й від потреб команди.","// An example of the integration through a JavaScript contract\\n// The catalogue micro-frontend (React)\\nwindow.microfrontendCatalog = {\\n  mount: (container) => {\\n    ReactDOM.render(<Catalog />, container);\\n  },\\n  unmount: (container) => {\\n    ReactDOM.unmountComponentAtNode(container);\\n  }\\n};\\n\\n// The main application calls mount when it is needed\\nwindow.microfrontendCatalog.mount(document.getElementById('catalog-root'));\\n\\n// The definition of a Web Component\\nclass UserCard extends HTMLElement {\\n  connectedCallback() {\\n    this.innerHTML = \`<div class=\\"card\\">\${this.getAttribute('name')}</div>\`;\\n  }\\n}\\ncustomElements.define('user-card', UserCard);\\n\\n// The usage in any application\\n<user-card name=\\"Ivan\\"></user-card>"],[2680,"У класових компонентах методи React не прив'язують до екземпляра класу автоматично. Коли метод передають як обробник подій, контекст this втрачається, тому метод треба прив'язати явно через bind, через стрілкову функцію або оголосивши метод стрілковою функцією, щоб зберегти доступ до this і до стану компонента.","Проблема втрати контексту\\nУ JavaScript методи класу не прив'язують до екземпляра автоматично. Коли ви передаєте метод як колбек (наприклад, в обробник подій), його викликають без контексту, й this стає undefined (у строгому режимі) або глобальним об'єктом. У React це призводить до помилок, коли ви намагаєтеся звернутися до this.state або this.props.\\n\\nСпособи розв'язання\\n\\n- Використання \`bind\` у конструкторі: \`this.handleClick = this.handleClick.bind(this)\`.\\n- Стрілкові функції в JSX: \`onClick={() => this.handleClick()}\`.\\n- Оголошення методів стрілковими функціями (поля класу): \`handleClick = () => { ... }\`.\\n\\nПриклад коду\\n\\nБез bind у конструкторі this.increment втратив би контекст, і виклик this.setState спричинив би помилку.\\n\\nВисновок\\nЯвне прив'язування методів потрібне, щоб зберегти доступ до стану й пропсів компонента. У сучасному React краще використовувати функційні компоненти з хуками, де цієї проблеми немає, але в роботі з класовими компонентами важливо пам'ятати про прив'язування.","class Counter extends React.Component {\\n  constructor(props) {\\n    super(props);\\n    this.state = { count: 0 };\\n    // The explicit binding\\n    this.increment = this.increment.bind(this);\\n  }\\n\\n  increment() {\\n    this.setState({ count: this.state.count + 1 });\\n  }\\n\\n  render() {\\n    return <button onClick={this.increment}>+1</button>;\\n  }\\n}"],[2681,"Stale closure виникає, коли колбек захоплює застаріле значення із замикання. Щоб виправити це, не додаючи залежностей, можна використати useRef, щоб зберігати поточне значення, і звертатися до нього всередині колбека. Це дає змогу зберегти стабільне посилання на функцію, завжди використовуючи свіжі дані.","Що таке stale closure?\\nStale closure — ситуація, у якій функція, створена всередині хука (наприклад, useCallback), запам'ятовує значення змінних із того рендера, у якому її створили. Якщо ці змінні змінюються на наступних рендерах, колбек далі використовує старі значення, що призводить до багів.\\n\\nПроблема з масивом залежностей\\nЗвичайно, щоб розв'язати цю проблему, змінну додають у масив залежностей useCallback. Однак це призводить до того, що функцію створюють заново на кожній зміні змінної, що може бути небажаним задля продуктивності або задля стабільності посилань (коли її передають у мемоїзовані дочірні компоненти).\\n\\nРішення через useRef\\nВикористовуйте useRef, щоб зберігати поточне значення. Створіть ref, оновлюйте його на кожному рендері (наприклад, через useEffect) і звертайтеся до ref.current усередині колбека. Отже, колбек завжди бачитиме свіже значення, а його посилання залишатиметься стабільним.\\n\\nКоли це корисно?\\nЦей підхід корисний, коли стабільну функцію треба передати в мемоїзований компонент (React.memo) або в useEffect із порожніми залежностями, однак функція все одно має використовувати поточні дані. Наприклад, для обробників подій або підписок.\\n\\nВисновок\\nВикористання useRef — елегантний спосіб уникнути stale closure, не створюючи функцію заново. Він придатний для випадків, у яких важлива стабільність посилання, а потрібні свіжі дані. Однак не зловживайте ним: якщо залежностей мало й вони змінюються рідко, простіше додати їх у масив залежностей.","const [count, setCount] = useState(0);\\nconst countRef = useRef(count);\\n\\nuseEffect(() => {\\n  countRef.current = count;\\n}, [count]);\\n\\nconst handleClick = useCallback(() => {\\n  console.log(countRef.current); // always the current value\\n}, []); // empty dependencies"],[2682,"useEffectEvent — експериментальний хук React, який дає змогу викликати функції всередині ефектів, не додаючи їх у залежності. Він потрібний, щоб відділити логіку, яка не має спричиняти повторного виконання ефекту, від реактивних значень. Це полегшує роботу з ефектами й зменшує кількість багів, пов'язаних із залежностями.","Що таке useEffectEvent?\\nuseEffectEvent — новий хук, представлений у React 19 (раніше відомий як useEffectEvent в експериментальній версії). Він призначений, щоб розв'язати проблему, за якої всередині useEffect треба викликати функцію, яка залежить від зовнішніх значень, але не має спричиняти повторного виконання ефекту, коли вони змінюються. Звичайно такі функції додають у масив залежностей, що призводить до надлишкових викликів ефекту. useEffectEvent дає змогу вивести цю функцію із залежностей, зберігаючи доступ до поточних значень.\\n\\nЯк це працює?\\nХук повертає стабільну функцію, яка завжди має доступ до найновіших значень пропсів і стану, але не є реактивною. Це означає, що ефект не перезапуститься, коли ці значення змінюються, а функція всередині ефекту використовуватиме свіжі дані. Це особливо корисно для обробників подій, підписок або журналювання.\\n\\nПриклад використання\\n\\nУ цьому прикладі onMessage не додають у залежності, але, коли його викликають, він використовує поточну theme. Якби ми використали звичайну функцію, нам довелося б додати її в залежності, що спричиняло б повторне під'єднання на кожній зміні теми.\\n\\nКоли це застосовувати?\\nuseEffectEvent варто використовувати, коли всередині ефекту викликають функцію, яка залежить від зовнішніх значень, але не має впливати на перезапуск ефекту. Це покращує читність і продуктивність, уникаючи надлишкових викликів. Однак хук досі експериментальний, тому в production варто дочекатися стабільної версії або використати альтернативні підходи — наприклад, useRef, щоб зберігати поточні значення.\\n\\nПідсумовуючи: useEffectEvent — потужний інструмент, щоб керувати ефектами в React, який допомагає відділити реактивну логіку від нереактивної, роблячи код чистішим і передбачуванішим.","import { useEffect, useEffectEvent } from 'react';\\n\\nfunction Chat({ roomId, theme }) {\\n  const onMessage = useEffectEvent((msg) => {\\n    console.log(theme, msg); // always the current theme\\n  });\\n\\n  useEffect(() => {\\n    const connection = createConnection(roomId);\\n    connection.on('message', onMessage);\\n    return () => connection.disconnect();\\n  }, [roomId]); // onMessage is not in the dependencies\\n}"],[2683,"Розділення коду дає змогу розбити один великий застосунок на кілька частин, які завантажують у міру потреби. У React це роблять за допомогою динамічних імпортів і React.lazy. Основний принцип — розділяти за маршрутом або за великим компонентом, щоб користувач отримував лише потрібний код. Це прискорює початкове завантаження й зберігає трафік.","Що таке розділення коду і для чого воно потрібне\\nКоли React-застосунок зібрано в один чанк, увесь код — бібліотеки, компоненти, утиліти — потрапляє в один файл. На першому відвідуванні сайту переглядач завантажує цей файл цілком, навіть якщо користувач бачить лише сторінку входу. Це сповільнює завантаження й збільшує споживання трафіку. Розділення коду розв'язує цю проблему: застосунок розбивають на кілька частин, які завантажують лише тоді, коли вони справді потрібні.\\n\\nЯк це працює в React\\nОсновний інструмент — динамічний імпорт. Замість статичного \`import Component from './Component'\` використовують \`const Component = React.lazy(() => import('./Component'))\`. React.lazy дає змогу відкласти завантаження компонента до моменту його рендерингу. Щоб обробити стан завантаження, використовують компонент \`Suspense\`, який показує заповнювач, поки чанк завантажується.\\n\\nПринципи розділення\\nКод треба розділяти за логічними межами застосунку. Найпоширеніший підхід — розділення за маршрутом: кожна сторінка стає окремим чанком. Також можна виділити важкі бібліотеки (наприклад, графіки або редактори) в окремі чанки, щоб вони не сповільнювали початкового завантаження. Важливо не фрагментувати код надто дрібно — кожний чанк має накладні витрати на HTTP-запит, тому оптимально, щоб розмір чанка був не менший за 10-20 КБ.\\n\\nНалаштування у Webpack\\nWebpack створює окремі чанки для динамічних імпортів автоматично. Додатково можна налаштувати \`splitChunks\`, щоб виділити спільні залежності (наприклад, React) в окремий vendor-чанк. Це дає переглядачеві змогу кешувати незмінні бібліотеки окремо від коду застосунку.\\n\\nВисновок\\nРозділення коду — стандартна практика для великих React-застосунків. Воно прискорює перше завантаження, зменшує навантаження на мережу й покращує користувацький досвід. Застосовуйте його всюди, де застосунок містить кілька маршрутів або важкі компоненти, не потрібні на старті.","import React, { Suspense, lazy } from 'react';\\nconst Dashboard = lazy(() => import('./Dashboard'));\\nconst Settings = lazy(() => import('./Settings'));\\n\\nfunction App() {\\n  return (\\n    <Suspense fallback={<div>Loading...</div>}>\\n      <Dashboard />\\n      <Settings />\\n    </Suspense>\\n  );\\n}\\n\\n// webpack.config.js\\nmodule.exports = {\\n  optimization: {\\n    splitChunks: {\\n      chunks: 'all',\\n      cacheGroups: {\\n        vendor: {\\n          test: /[\\\\\\\\/]node_modules[\\\\\\\\/]/,\\n          name: 'vendors',\\n          chunks: 'all',\\n        },\\n      },\\n    },\\n  },\\n};"],[2684,"Локалізація (i18n) — процес адаптації застосунку для різних мов і регіонів. Реалізація включає виведення всіх текстів у файли перекладів, використання бібліотек на кшталт i18next або react-intl і перемикання мови через контекст чи через глобальний стан. Важливо враховувати форматування дат, чисел і валют.","Що таке локалізація?\\nЛокалізація (скорочено i18n — від слова internationalization, де 18 — кількість літер між першою й останньою) — процес адаптації програмного продукту задля використання в різних країнах і культурах. Вона включає не лише переклад текстів, а й належне відображення дат, чисел і валют, напрям тексту (наприклад, для арабської) й інші регіональні особливості.\\n\\nОсновні підходи до реалізації\\nУ сучасних вебзастосунках локалізацію звичайно будують на таких принципах:\\n- Усі рядки, які бачить користувач, виводять в окремі файли (JSON, YAML, PO) із ключами.\\n- Бібліотека локалізації (наприклад, i18next, react-intl, vue-i18n) завантажує потрібний файл залежно від обраної мови.\\n- Перемикання мови відбувається через глобальний стан (Redux, Context API) або через параметр URL.\\n\\nПриклад у JavaScript з i18next\\n\\nПрактичні аспекти\\nКоли реалізують локалізацію, важливо враховувати таке:\\n- Плюралізацію (форми множини) — у російській їх три, в англійській дві.\\n- Інтерполяцію змінних усередині рядків.\\n- Форматування дат і чисел з оглядом на локаль (наприклад, через Intl API).\\n- Зберігання обраної мови в localStorage або в cookie, щоб зберегти налаштування користувача.\\n\\nВисновок\\nЛокалізація потрібна, щоб розширити аудиторію застосунку на міжнародний ринок. Використання готових бібліотек і виведення рядків в окремі файли робить процес перекладу простим і таким, що легко підтримувати, а також дає змогу залучати перекладачів без знання коду.","// locales/en.json\\n{\\n  \\"greeting\\": \\"Hello, {{name}}!\\"\\n}\\n\\n// locales/fr.json\\n{\\n  \\"greeting\\": \\"Bonjour, {{name}} !\\"\\n}\\n\\n// main.js\\nimport i18next from 'i18next';\\nimport en from './locales/en.json';\\nimport fr from './locales/fr.json';\\n\\ni18next.init({\\n  lng: 'fr',\\n  resources: {\\n    en: { translation: en },\\n    fr: { translation: fr }\\n  }\\n});\\n\\nconsole.log(i18next.t('greeting', { name: 'Anna' })); // Bonjour, Anna !"],[2685,"Рольову модель доступу на фронтенді реалізують через зберігання ролей і дозволів користувача (звичайно в токені або в окремому запиті) й умовне відображення UI-елементів на основі цих даних. Визначення прав відбувається через перевірку наявності певної ролі або дозволу в коді компонента. Важливо пам'ятати, що перевірки на фронтенді — не безпека, а лише покращення UX; справжній захист завжди на бекенді.","Базова концепція\\nРольова модель доступу (RBAC) на фронтенді — спосіб керувати видимістю й доступністю інтерфейсу залежно від прав поточного користувача. Суть у тому, що після автентифікації фронтенд отримує інформацію про ролі й дозволи користувача, зберігає її у стані застосунку (наприклад, у Redux або в контексті React) і використовує задля умовного рендерингу компонентів, кнопок, маршрутів й інших елементів.\\n\\nВизначення прав звичайно відбувається через перевірку наявності певної ролі (наприклад, 'admin') або певного дозволу (наприклад, 'canEditPost') в об'єкті користувача. Задля цього створюють допоміжні функції або хуки, які інкапсулюють логіку перевірки.\\n\\nПрактична реалізація\\nПодивімося на приклад у React. Нехай після входу ми отримуємо об'єкт користувача з масивом ролей і дозволів:\\n\\nСтворімо хук, щоб перевіряти права:\\n\\nТепер у компоненті кнопку можна відображати умовно:\\n\\nДля маршрутів можна використати захищені обгортки, які перевіряють роль і переспрямовують на сторінку входу або на 403, якщо доступ заборонено.\\n\\nДе це застосовують\\nТакий підхід використовують в адміністративних панелях, CRM-системах, корпоративних порталах і будь-якому застосунку, у якому різні категорії користувачів мають різні рівні доступу. Він покращує користувацький досвід, приховуючи нерелевантні функції, й полегшує навігацію.\\n\\nВажливе попередження\\nПеревірки на фронтенді — не захист від зловмисних дій. Нападник може обійти їх, змінивши код або запити. Тому всі критичні операції треба перевіряти на сервері. Фронтенд лише створює видимість обмежень для звичайного користувача.\\n\\nВисновок\\nРольова модель на фронтенді — зручний інструмент, щоб адаптувати інтерфейс до прав користувача. Використовуйте її, щоб покращити UX, але завжди дублюйте перевірки на бекенді, аби забезпечити справжню безпеку даних і функціональності.","const user = {\\n  roles: ['admin', 'editor'],\\n  permissions: ['createPost', 'deletePost']\\n};\\n\\nfunction usePermission(permission) {\\n  const { user } = useAuth();\\n  return user?.permissions?.includes(permission) ?? false;\\n}\\n\\nfunction PostActions({ postId }) {\\n  const canDelete = usePermission('deletePost');\\n  return (\\n    <div>\\n      <button>Edit</button>\\n      {canDelete && <button>Delete</button>}\\n    </div>\\n  );\\n}"],[2686,"Власну бібліотеку компонентів підтримують через узгоджені принципи її API та стилів. Тематизацію реалізують за допомогою CSS-змінних або контексту теми, а кастомізацію — через props і слоти. Важливо документувати компоненти й версіонувати зміни.","Основи підтримки бібліотеки компонентів\\nПідтримка власної бібліотеки компонентів вимагає суворої дисципліни: узгодженого API, версіонування, документації й тестування. Без цього компоненти швидко перетворюються на хаос, де кожен розробник додає власні props і стилі. Ключовий принцип — інкапсуляція: компонент має керувати власною логікою та стилями, надаючи при цьому гнучкі точки розширення.\\nТематизація через CSS-змінні\\nНайпростіший і найпотужніший спосіб тематизації — використовувати CSS-змінні (custom properties). Вони успадковуються й можуть бути перевизначені на рівні контейнера, що дозволяє змінювати тему без перезбирання. Наприклад, визначте змінні на кореневому елементі й перевизначте їх для темної теми.\\n\\nУ JavaScript можна перемикати атрибут \`data-theme\` на кореневому елементі. Це працює в будь-якому фреймворку й не потребує додаткових бібліотек.\\nКастомізація через props і слоти\\nКастомізація компонентів досягається через props (варіанти, розміри, стани) і через слоти/children для вставлення довільного вмісту. Наприклад, кнопка може приймати props \`variant\` і \`size\`, а також дозволяти перевизначати іконку через children.\\n\\nДля глибшої кастомізації можна використовувати render props або контекст, але це ускладнює API. Краще дотримуватися принципу, що 80% випадків покривають props, а решту — CSS-змінні й слоти.\\nПрактичні рекомендації\\n\\n- Версіонуйте свої зміни за SemVer, щоб споживачі могли безпечно оновлюватися.\\n- Пишіть документацію з прикладами для кожної теми й варіанта.\\n- Використовуйте тести візуальної регресії (наприклад, Storybook + Chromatic).\\n- Уникайте жорстких залежностей від конкретного фреймворку, якщо планується багатоплатформна підтримка.\\nВисновок\\nПідтримка бібліотеки компонентів — це баланс між гнучкістю та стабільністю. Тематизація через CSS-змінні й кастомізація через props — стандартний підхід, і його легко підтримувати й розширювати. Застосовуйте його, якщо вам потрібна повторно використовна дизайн-система в кількох проєктах.",":root {\\n  --color-primary: #3498db;\\n  --spacing-unit: 8px;\\n}\\n\\n[data-theme=\\"dark\\"] {\\n  --color-primary: #2980b9;\\n}\\n\\n.button {\\n  background: var(--color-primary);\\n  padding: calc(var(--spacing-unit) * 2);\\n}\\n\\nfunction Button({ variant = 'primary', size = 'md', children }) {\\n  return <button className={'btn btn--' + variant + ' btn--' + size}>{children}</button>;\\n}"],[2687,"Compound Components — патерн, у якому група компонентів працює разом як єдине ціле, поділяючи стан через контекст або через cloneElement. Він дає змогу створювати гнучкі API — наприклад, \`<Select>\` і \`<Select.Option>\`. Коли використовують cloneElement, важливо передавати пропси уважно, аби не перезаписати власні пропси користувача. Context кращий для складних випадків, адже він уникає проблем із вкладеністю.","Що таке Compound Components?\\nCompound Components — патерн у React, у якому кілька компонентів об'єднують в єдине API: вони працюють разом і поділяють внутрішній стан. Класичний приклад — \`<Select>\` і \`<Select.Option>\`, де батько керує вибором, а дочірні елементи відображають опції. Цей підхід покращує читність і повторне використання коду, даючи розробникам змогу поєднувати компоненти без явного передавання пропсів на кожному рівні.\\n\\nРеалізація через Context\\nНайнадійніший спосіб — використати React Context. Батьківський компонент створює контекст і передає через нього стан і функції. Дочірні компоненти отримують доступ до контексту через хук \`useContext\`. Це знімає проблеми з вкладеністю й дає змогу легко розширювати API.\\n\\nРеалізація через cloneElement\\nАльтернативний спосіб — використати \`React.cloneElement\`, щоб передати пропси дочірнім елементам. Це простіше, але менш гнучко: якщо дочірній елемент уже має проп із тим самим іменем, його перезапишуть. Також важко працювати з глибоко вкладеними компонентами.\\n\\nНа що звернути увагу\\n\\n- Коли використовуєте \`cloneElement\`, не перезаписуйте пропси користувача без потреби — краще зливати їх.\\n- Context краще придатний для складних ієрархій, адже він не залежить від структури дерева.\\n- Завжди перевіряйте, що дочірні елементи — саме ті компоненти, яких ви очікуєте, аби уникати помилок.\\n\\nВисновок\\nCompound Components — потужний патерн, щоб створювати гнучкі, інтуїтивні API. Використовуйте Context задля масштабованих рішень, а \`cloneElement\` — для простих випадків, де треба швидко передати кілька пропсів. Це особливо корисно в бібліотеках компонентів й у складних формах.","const SelectContext = React.createContext();\\n\\nfunction Select({ children }) {\\n  const [value, setValue] = React.useState('');\\n  return (\\n    <SelectContext.Provider value={{ value, setValue }}>\\n      {children}\\n    </SelectContext.Provider>\\n  );\\n}\\n\\nfunction Option({ value, children }) {\\n  const { value: selected, setValue } = React.useContext(SelectContext);\\n  return (\\n    <div onClick={() => setValue(value)}>\\n      {children} {selected === value ? '✓' : ''}\\n    </div>\\n  );\\n}\\n\\nSelect.Option = Option;\\n\\nfunction Select({ children }) {\\n  const [value, setValue] = React.useState('');\\n  return React.Children.map(children, child =>\\n    React.cloneElement(child, { value, setValue })\\n  );\\n}\\n\\nfunction Option({ value, setValue, selected, children }) {\\n  return <div onClick={() => setValue(value)}>{children}</div>;\\n}"],[2688,"Таку функцію звичайно називають pick або pickKeys. Вона приймає масив ключів й об'єкт, а далі за допомогою reduce створює новий об'єкт, який включає лише зазначені властивості. Це зручно, щоб відібрати потрібні дані з великих об'єктів.","Що робить функція pick\\nФункція \`pick\` — поширений утилітний метод, який дає змогу видобути з об'єкта лише ті властивості, які перелічено в масиві ключів. Вона корисна, коли в компонент або у функцію треба передати лише частину даних, не копіюючи всього об'єкта.\\n\\nРеалізація через reduce\\nМетод \`reduce\` ідеальний для цієї задачі, адже він дає змогу накопичувати результат у новому об'єкті крок за кроком. На кожній ітерації ми перевіряємо, чи існує поточний ключ у початковому об'єкті, і, якщо так, додаємо його в накопичувач.\\n\\nДе це застосовують\\nТаку функцію часто використовують у Redux, щоб відібрати частину стану, у React — щоб передати лише потрібні пропси, а в шарах API — щоб фільтрувати вхідні дані. Вона допомагає уникати надлишкових даних і полегшує зневадження.\\n\\nВисновок\\nВикористовуйте \`pick\` усюди, де треба отримати підмножину властивостей об'єкта — це робить код чистішим і запобігає випадковому передаванню надлишкових полів.","function pick(obj, keys) {\\n  return keys.reduce((acc, key) => {\\n    if (key in obj) {\\n      acc[key] = obj[key];\\n    }\\n    return acc;\\n  }, {});\\n}\\n\\nconst user = { name: 'Alice', age: 30, city: 'NYC' };\\nconst picked = pick(user, ['name', 'city']);\\nconsole.log(picked); // { name: 'Alice', city: 'NYC' }"],[2689,"Задля спілкування між вкладками можна використати BroadcastChannel API, який дає змогу надсилати повідомлення всім вкладкам того самого походження. Також придатний localStorage із подією storage, яка спрацьовує в інших вкладках, коли дані змінюються. Обидва способи прості й не потребують сервера.","Вступ\\nКоли користувач відкриває кілька вкладок одного сайту, кожна з них працює в ізолованому процесі. Щоб синхронізувати дії — наприклад, зупинку плеєра, — треба використати механізм спілкування між вкладками. Основні варіанти: BroadcastChannel, localStorage і postMessage.\\n\\nBroadcastChannel\\nBroadcastChannel створює канал, через який можна надсилати повідомлення всім вкладкам, підписаним на цей канал. Це сучасний, зручний спосіб.\\n\\nlocalStorage і подія storage\\nЯкщо треба підтримувати старіші переглядачі, можна використати localStorage. Коли значення змінюється в одній вкладці, в інших вкладках спрацьовує подія storage.\\n\\npostMessage із window.open\\nЯкщо вкладки відкрили через window.open, можна використати postMessage задля прямого спілкування між вікнами. Однак це потребує, щоб посилання на вікна зберігали.\\n\\nВисновок\\nЗадля простої синхронізації між вкладками найкраще придатний BroadcastChannel — він чистий і не залишає слідів у сховищі. Якщо потрібна підтримка старіших переглядачів, використовуйте localStorage. Вибір залежить від цільової аудиторії й від складності застосунку.","// Tab 1: sending a message\\nconst channel = new BroadcastChannel('player');\\nchannel.postMessage({ action: 'stop' });\\n\\n// Tab 2: receiving the message\\nconst channel = new BroadcastChannel('player');\\nchannel.onmessage = (event) => {\\n  if (event.data.action === 'stop') {\\n    player.pause();\\n  }\\n};\\n\\n// Tab 1\\nlocalStorage.setItem('playerState', 'stopped');\\n\\n// Tab 2\\nwindow.addEventListener('storage', (event) => {\\n  if (event.key === 'playerState' && event.newValue === 'stopped') {\\n    player.pause();\\n  }\\n});"],[2690,"Зависання відбувається тому, що головний потік переглядача блокують, поки великий масив даних обробляють і рендерять. Рішення включає розбиття даних на частини (chunking), використання віртуалізації списків, відкладене завантаження або Web Workers задля важких обчислень.","Причина зависання\\nКоли на фронтенд приходить великий масив даних, переглядач виконує JavaScript в єдиному головному потоці. Якщо цей потік зайнятий обробкою даних (наприклад, створенням тисяч DOM-елементів або виконанням складних обчислень), він не може обробляти події користувача, як-от кліки або прокручування. Це призводить до зависання інтерфейсу.\\n\\nЯк це розв'язати\\nЄ кілька підходів, які можна поєднувати:\\n- Розбиття на частини (chunking) — обробляйте дані порціями, використовуючи \`setTimeout\` або \`requestAnimationFrame\`, щоб дати переглядачеві час намалювати кадри.\\n- Віртуалізація списків — рендерте лише видимі елементи списку, а не всі одразу. Із цим допомагають бібліотеки на кшталт \`react-window\` або \`react-virtualized\`.\\n- Web Workers — виконуйте важкі обчислення в окремому потоці, аби не блокувати головний.\\n- Пагінація або ліниве завантаження — запитуйте дані частинами, у міру того як користувач прокручує.\\n\\nПриклад із chunking\\n\\nВисновок\\nВикористовуйте поєднання віртуалізації й chunking для великих масивів, щоб зберегти відгукливість інтерфейсу. Задля складних обчислень застосовуйте Web Workers. Це особливо важливо в роботі з таблицями, лентами або графіками.","function processLargeArray(data) {\\n  const chunkSize = 100;\\n  let index = 0;\\n\\n  function processChunk() {\\n    const chunk = data.slice(index, index + chunkSize);\\n    // The processing of the chunk — adding it to the DOM, for example\\n    index += chunkSize;\\n    if (index < data.length) {\\n      requestAnimationFrame(processChunk);\\n    }\\n  }\\n\\n  processChunk();\\n}"],[2691,"Час рендера компонента можна подивитися за допомогою React DevTools, у вкладці Profiler. Запишіть сесію профілювання, виконайте дії, які спричиняють рендер, і ви побачите тривалість для кожного компонента. Також можна використати Profiler API від React, обгорнувши компонент у \`<Profiler>\` і передавши колбек onRender.","Чому варто вимірювати час рендера\\nУ React рендеринг — процес обчислення віртуального DOM й оновлення реального DOM. Якщо компонент рендериться надто довго, це може спричиняти затримки в інтерфейсі. Розуміння того, де саме витрачають час, допомагає оптимізувати застосунок.\\n\\nСпособи вимірювання\\nПерший спосіб — Profiler, вбудований у React DevTools. Відкрийте вкладку Profiler, натисніть кнопку запису, виконайте потрібні вам дії (наприклад, клік або введення тексту), потім зупиніть запис. Ви побачите діаграму, де кожний компонент показано з його часом рендера. Це найнаочніший спосіб це проаналізувати.\\n\\nДругий спосіб — програмний \`Profiler\` API від React. Обгорніть компонент у \`<Profiler>\` і передайте колбек \`onRender\`, який отримує інформацію про час рендера. Це зручно задля автоматичного збирання метрик у production.\\n\\nТакож можна використати \`console.time\` навколо рендера, але це менш точно, адже React може групувати оновлення.\\n\\nПрактичне застосування\\nВимірювання часу рендера корисне, коли оптимізують складні списки, форми або компоненти з важкими обчисленнями. Якщо ви бачите, що компонент рендериться надто часто або надто довго, можна застосувати мемоїзацію (\`React.memo\`, \`useMemo\`) чи розбити компонент на дрібніші частини.\\n\\nВисновок: використовуйте React DevTools Profiler задля швидкого наочного аналізу, а \`Profiler\` API — задля автоматичного збирання метрик у тестах чи в моніторингу. Це допоможе виявити вузькі місця й зробити застосунок відгукливішим.","import { Profiler } from 'react';\\n\\nfunction onRenderCallback(id, phase, actualDuration, baseDuration, startTime, commitTime) {\\n  console.log(\`The component \${id} rendered in \${actualDuration} ms\`);\\n}\\n\\nfunction App() {\\n  return (\\n    <Profiler id=\\"MyComponent\\" onRender={onRenderCallback}>\\n      <MyComponent />\\n    </Profiler>\\n  );\\n}"],[2692,"Хук useRef дає змогу зберігати мутабельне значення, яке не спричиняє повторного рендера компонента, коли його оновлюють. Він повертає об'єкт із властивістю current, яку можна змінювати напряму. Це корисно, щоб зберігати посилання на DOM-елементи або будь-які дані, які не мають впливати на малювання.","Що таке useRef?\\nХук \`useRef\` у React створює мутабельний об'єкт, який зберігається між рендерами компонента. На відміну від \`useState\`, зміна значення в \`useRef\` не спричиняє повторного рендера. Це ключова відмінність: якщо треба зберігати дані, які не впливають на UI, але мають бути доступні будь-якої миті, \`useRef\` — правильний вибір.\\n\\nЯк це працює?\\nНа виклику \`useRef(initialValue)\` повертають об'єкт вигляду \`{ current: initialValue }\`. Ви можете вільно змінювати \`current\`, і React про це не знатиме, тому компонент не перемалюється. Це особливо корисно, щоб:\\n- Зберігати посилання на DOM-елементи (наприклад, задля фокусу або щоб виміряти розміри).\\n- Зберігати попередні значення пропсів або стану.\\n- Зберігати таймери або ідентифікатори інтервалів.\\n\\nПриклад коду\\n\\nУ прикладі вище натискання другої кнопки збільшує \`countRef.current\`, але компонент не перемалюється, тому на екрані нічого не змінюється. Це демонструє, що \`useRef\` не впливає на рендер.\\n\\nКоли це використовувати?\\nВикористовуйте \`useRef\`, коли треба зберігати дані, які не мають спричиняти оновлення UI. Наприклад, щоб зберігати попереднє значення пропа й порівняти його в \`useEffect\`, або щоб керувати фокусом на input. Якщо дані треба відображати на екрані, використовуйте \`useState\`.\\n\\nПідсумовуючи: \`useRef\` — інструмент, щоб зберігати мутабельні значення без повторних рендерів. Він незамінний у роботі з DOM й задля оптимізації продуктивності, коли оновлення стану не потрібне.","import React, { useRef, useState } from 'react';\\n\\nfunction Counter() {\\n  const countRef = useRef(0); // we hold the counter without a re-render\\n  const [count, setCount] = useState(0); // ordinary state\\n\\n  const incrementRef = () => {\\n    countRef.current += 1;\\n    console.log('Ref count:', countRef.current);\\n  };\\n\\n  const incrementState = () => {\\n    setCount(count + 1);\\n  };\\n\\n  return (\\n    <div>\\n      <p>State count: {count}</p>\\n      <button onClick={incrementState}>Increment state</button>\\n      <button onClick={incrementRef}>Increment ref (no re-render)</button>\\n    </div>\\n  );\\n}"],[2693,"У React, щоб зберігати локальний стан, використовують хуки useState і useReducer. useState придатний для простих значень, а useReducer — для складної логіки стану. Обидва хуки дають компонентові змогу зберігати й оновлювати дані без зовнішніх бібліотек.","Вступ до локального стану\\nЛокальний стан у React — дані, які належать певному компонентові й якими він керує безпосередньо. Його використовують, щоб зберігати тимчасові значення, як-от введення користувача, прапорці видимості або обрані елементи. Щоб працювати з таким станом, React надає вбудовані хуки, які роблять керування простим і передбачуваним.\\n\\nХук useState\\nХук \`useState\` — найпоширеніший спосіб зберігати локальний стан. Він приймає початкове значення й повертає масив із двох елементів: поточне значення й функцію, щоб його оновити. Оновлення стану спричиняє повторний рендер компонента з новими даними.\\n\\nЦей приклад показує, як просто можна зберігати й змінювати число. \`useState\` ідеальний для одиничних значень або простих об'єктів, коли логіка оновлення не надто складна.\\n\\nХук useReducer\\nКоли стан стає складним — наприклад, коли він містить кілька полів або потребує послідовних оновлень, — краще використати \`useReducer\`. Він працює за принципом редюсера Redux: він приймає функцію-редюсер плюс початковий стан і повертає поточний стан плюс функцію \`dispatch\`, щоб надсилати actions.\\n\\n\`useReducer\` зручний, щоб керувати формами, кошиками або будь-яким станом, у якому оновлення залежать від попередніх значень й від actions.\\n\\nКоли що використовувати\\n\\n- useState — для простих незалежних значень (рядків, чисел, булевих).\\n- useReducer — для складних об'єктів, коли кілька actions змінюють стан, або коли логіка оновлення повторюється.\\n\\nОбидва хуки — частина ядра React, і вони не потребують додаткових бібліотек. Вони покривають більшість потреб у локальному стані, а для глобального стану використовують інші інструменти, як-от Context або Redux.\\n\\nВисновок\\nЩоб зберігати локальний стан у React, використовуйте \`useState\` для простих випадків і \`useReducer\` для складнішої логіки. Це базові інструменти, які має знати кожний розробник, який працює з React, адже вони лежать в основі будь-якого інтерактивного інтерфейсу.","import React, { useState } from 'react';\\n\\nfunction Counter() {\\n  const [count, setCount] = useState(0);\\n\\n  return (\\n    <div>\\n      <p>The counter: {count}</p>\\n      <button onClick={() => setCount(count + 1)}>Increment</button>\\n    </div>\\n  );\\n}\\n\\nimport React, { useReducer } from 'react';\\n\\nconst initialState = { count: 0 };\\n\\nfunction reducer(state, action) {\\n  switch (action.type) {\\n    case 'increment':\\n      return { count: state.count + 1 };\\n    case 'decrement':\\n      return { count: state.count - 1 };\\n    default:\\n      return state;\\n  }\\n}\\n\\nfunction Counter() {\\n  const [state, dispatch] = useReducer(reducer, initialState);\\n\\n  return (\\n    <div>\\n      <p>The counter: {state.count}</p>\\n      <button onClick={() => dispatch({ type: 'increment' })}>+</button>\\n      <button onClick={() => dispatch({ type: 'decrement' })}>-</button>\\n    </div>\\n  );\\n}"],[2694,"Синтетична подія — обгортка React над нативною подією переглядача. Вона забезпечує однакову поведінку в кожному переглядачі й очищується автоматично після того, як обробка завершилася. React передає її в обробники — наприклад, onClick. Подія має ті самі властивості, що й нативна, але асинхронний доступ до неї обмежений через пулінг.","Що таке синтетична подія?\\nСинтетична подія — кросбраузерна обгортка, яку React створює навколо нативної події переглядача. Коли ви пишете \`onClick\` або \`onChange\`, React не прив'язує обробник до DOM-елемента напряму, а делегує його кореневому контейнерові й передає у ваш обробник об'єкт синтетичної події. Це роблять задля однаковості: незалежно від переглядача, властивості події (наприклад, \`target\`, \`preventDefault\`) працюють однаково.\\n\\nДля чого вона потрібна?\\nОсновні причини: уніфікація API, покращення продуктивності через делегування й автоматичне очищення пам'яті. React використовує пулінг подій: після того як обробник викликали, властивості події занулюють, щоб повторно використати об'єкт. Тому ви не можете зберегти подію й використати її пізніше — наприклад, у \`setTimeout\`; потрібні дані треба скопіювати заздалегідь.\\n\\nПриклад використання\\n\\nЯкщо подію треба використати асинхронно, збережіть потрібні поля заздалегідь: \`const type = event.type;\`.\\n\\nВисновок\\nСинтетичні події — стандартний механізм React, щоб обробляти дії користувача. Вони полегшують розробку, приховуючи різницю між переглядачами, але потребують обережності в асинхронній роботі. Розуміння цієї концепції важливе задля зневадження й оптимізації React-застосунків.","function Button() {\\n  const handleClick = (event) => {\\n    console.log(event.type); // 'click'\\n    console.log(event.target); // the DOM element\\n    // event is available only synchronously\\n    setTimeout(() => {\\n      console.log(event.type); // an error, or null, because of the pooling\\n    }, 0);\\n  };\\n  return <button onClick={handleClick}>Click</button>;\\n}"],[2695,"Ні, пропси в React немутабельні. Дочірній компонент не може змінити пропси, передані від батька, напряму. Замість цього треба використати колбеки, передані через пропси, щоб батько оновив стан, або підняти стан вище. Це забезпечує однонапрямлений потік даних і передбачуваність.","Базова концепція\\nУ React пропси — механізм, щоб передавати дані з батьківського компонента в дочірній. Вони призначені лише для читання. Це фундаментальний принцип, який гарантує, що дані в застосунку рухаються в одному напрямі: згори вниз. Якби дочірній компонент міг змінювати пропси, це призводило б до непередбачуваних змін стану батька й порушувало б цілісність даних.\\n\\nЧому це важливо\\nНемутабельність пропсів дає React змогу ефективно визначати, коли компонент треба перемалювати. Якщо пропси не змінюються, React може пропустити рендеринг дочірнього компонента. Крім того, це полегшує зневадження: ви завжди знаєте, звідки дані прийшли й хто може їх змінити.\\n\\nЯк належно оновлювати дані\\nЯкщо дочірній компонент має змінити дані, він має викликати функцію, передану через пропси від батька. Батько, зі свого боку, оновлює свій стан, і нові пропси передають униз автоматично. Це називають «підняттям стану».\\n\\nУ цьому прикладі дочірній компонент не змінює пропа \`count\` напряму. Замість цього він викликає \`onIncrement\`, який оновлює стан у батькові.\\n\\nВинятки й нюанси\\nІноді можна зустріти спроби змінити пропси — наприклад, присвоїти \`props.value = 5\`. Це не працюватиме й спричинить помилку в строгому режимі. Якщо вам потрібне локальне мутабельне значення, використовуйте \`useState\` усередині дочірнього компонента, ініціалізувавши його з пропа.\\n\\nВисновок\\nПропси в React немутабельні за задумом. Щоб оновити дані, використовуйте колбеки й підняття стану. Це робить потік даних передбачуваним і полегшує підтримку застосунку. Якщо ви помічаєте, що намагаєтеся змінити пропси, перегляньте архітектуру: можливо, стан має жити вище або в самому компоненті.","// The parent component\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n\\n  const increment = () => setCount(count + 1);\\n\\n  return <Child count={count} onIncrement={increment} />;\\n}\\n\\n// The child component\\nfunction Child({ count, onIncrement }) {\\n  return (\\n    <div>\\n      <p>The counter: {count}</p>\\n      <button onClick={onIncrement}>Increment</button>\\n    </div>\\n  );\\n}"],[2696,"Обробка подій у React — спосіб відповідати на дії користувача, як-от кліки, введення тексту або надсилання форм. Замість нативних DOM-подій React використовує синтетичні події, які працюють однаково в кожному переглядачі. Обробники передають як пропси в JSX — наприклад, onClick={handleClick}. Важливо пам'ятати, що в класових компонентах треба прив'язувати контекст this, а у функційних використовують замикання.","Що таке обробка подій у React?\\nУ React обробка подій — механізм, який дає компонентам змогу відповідати на дії користувача, як-от кліки, наведення мишею, введення тексту або надсилання форм. Замість того щоб використовувати нативні DOM-події напряму, React створює власну обгортку — синтетичні події. Це роблять, щоб забезпечити кросбраузерну сумісність і покращити продуктивність через делегування подій кореневому елементові.\\n\\nЯк це працює?\\nСинтетичні події мають той самий інтерфейс, що й нативні, але працюють однаково в кожному переглядачі. Обробники передають як пропси в JSX — наприклад, \`onClick\`, \`onChange\`, \`onSubmit\`. У функційних компонентах обробники — звичайні функції, які отримують об'єкт події. У класових компонентах треба бути уважним із контекстом \`this\`, адже методи класу не прив'язують автоматично.\\n\\nПриклади коду\\nФункційний компонент з обробником кліку:\\n\\nКласовий компонент із прив'язуванням контексту:\\n\\nОсобливості й нюанси\\n\\n- Синтетичні події пулять (використовують повторно) задля продуктивності, тому до їхніх властивостей не можна звертатися асинхронно без \`event.persist()\` (у старіших версіях React).\\n- У React не можна повернути \`false\` з обробника, щоб запобігти типовій поведінці — треба викликати \`event.preventDefault()\`.\\n- Обробники подій у React — не рядки, а функції, що робить код типово безпечнішим і зручнішим у тестуванні.\\n\\nВисновок\\nОбробка подій у React — стандартний спосіб взаємодіяти з користувачем, який полегшує роботу з DOM і забезпечує передбачувану поведінку. Використовуйте синтетичні події, щоб створювати інтерактивні інтерфейси, пам'ятайте про прив'язування контексту в класах і про те, що обробники — звичайні функції, які можна використовувати повторно й тестувати.","function Button() {\\n  const handleClick = (event) => {\\n    console.log('The button has been pressed', event);\\n  };\\n\\n  return <button onClick={handleClick}>Click me</button>;\\n}\\n\\nclass Button extends React.Component {\\n  constructor(props) {\\n    super(props);\\n    this.handleClick = this.handleClick.bind(this);\\n  }\\n\\n  handleClick(event) {\\n    console.log('The button has been pressed', event);\\n  }\\n\\n  render() {\\n    return <button onClick={this.handleClick}>Click me</button>;\\n  }\\n}"],[2697,"Subject у RxJS — особливий тип Observable, який водночас і спостережуваний, і спостерігач. Він дає змогу розсилати значення безлічі підписників. Основні види: звичайний Subject (він не зберігає значень), BehaviorSubject (він зберігає останнє значення), ReplaySubject (він зберігає буфер останніх значень) й AsyncSubject (він видає лише останнє значення після того, як потік завершився).","Що таке Subject?\\nSubject у RxJS — гібрид Observable й Observer. Він дає змогу не лише підписатися на потік даних, а й активно видавати в нього значення. Це робить його зручним інструментом, щоб організувати обмін даними між компонентами або модулями застосунку, особливо в реактивних архітектурах.\\n\\nОсновні види Subject\\n\\n- Subject — базовий тип; він не зберігає попередніх значень. Новий підписник отримує лише ті значення, які видадуть після його підписки.\\n- BehaviorSubject — він зберігає останнє значення й передає його новому підписникові одразу, на підписці. Він потребує початкового значення, коли його створюють.\\n- ReplaySubject — він зберігає буфер останніх N значень (або значень із певного інтервалу часу) й передає їх новим підписникам.\\n- AsyncSubject — він видає лише останнє значення, але лише після того, як потік завершився. Він корисний для операцій, результат яких відомий лише в кінці.\\n\\nПриклад використання\\n\\nДе це застосовують\\nSubject часто використовують, щоб створювати сервіси задля обміну даними в Angular (наприклад, щоб керувати станом), щоб обробляти події користувацького інтерфейсу й щоб реалізувати шину подій у застосунках. BehaviorSubject зручний, щоб зберігати поточний стан (наприклад, авторизацію користувача), ReplaySubject — щоб кешувати найновіші дані, а AsyncSubject — щоб отримати результат асинхронної операції.\\n\\nВисновок: вибір конкретного типу Subject залежить від задачі: якщо треба передавати лише нові значення, використовуйте Subject; якщо треба зберігати поточний стан — BehaviorSubject; якщо треба відтворити історію — ReplaySubject; а якщо важливий лише фінальний результат — AsyncSubject.","import { Subject, BehaviorSubject, ReplaySubject, AsyncSubject } from 'rxjs';\\n\\n// An ordinary Subject\\nconst subject = new Subject();\\nsubject.subscribe(v => console.log('Subject:', v));\\nsubject.next(1); // the subscriber will receive 1\\n\\n// A BehaviorSubject\\nconst behavior = new BehaviorSubject(0);\\nbehavior.subscribe(v => console.log('Behavior:', v)); // it will receive 0 at once\\nbehavior.next(1); // it will receive 1\\n\\n// A ReplaySubject with a buffer of 2 values\\nconst replay = new ReplaySubject(2);\\nreplay.next(1);\\nreplay.next(2);\\nreplay.subscribe(v => console.log('Replay:', v)); // it will receive 1 and 2\\n\\n// An AsyncSubject\\nconst async = new AsyncSubject();\\nasync.subscribe(v => console.log('Async:', v));\\nasync.next(1);\\nasync.next(2);\\nasync.complete(); // the subscriber will receive only 2"],[2698,"Гідрація — процес приєднання обробників подій до HTML, відрендереного на сервері. Типові помилки виникають через розбіжність у розмітці між сервером і клієнтом — наприклад, через використання випадкових значень, дат або API переглядача. Щоб їх уникати, треба забезпечити детермінований рендеринг і використовувати ефекти задля клієнтських операцій.","Що таке гідрація і чому виникають помилки\\nГідрація — процес, у якому React бере HTML, згенерований на сервері (SSR), і додає до нього інтерактивність: він прив'язує обробники подій, створює внутрішній стан і готує дерево компонентів. Помилки гідрації виникають, коли HTML із сервера не відповідає тому, що React очікує відрендерити на клієнті. Це призводить до попереджень у консолі й до некоректної поведінки інтерфейсу.\\n\\nТипові помилки й їхні причини\\n\\n- Використання випадкових значень: наприклад, \`Math.random()\` або \`Date.now()\` у рендері. Сервер і клієнт отримують різні значення, що спричиняє розбіжність.\\n- Залежність від API переглядача: доступ до \`window\`, \`document\` або \`localStorage\` під час рендерингу. На сервері цих об'єктів немає, тому код або падає, або повертає інші дані.\\n- Різні версії бібліотек: якщо сервер і клієнт використовують різні версії React або інших залежностей, розмітка може відрізнятися.\\n- Ігнорування пробілів і розривів рядків: незначні відмінності у форматуванні HTML можуть призводити до помилки.\\n\\nЯк уникати помилок\\nОсновний принцип — зробити рендеринг детермінованим. Усі дані, які залежать від часу, від випадковості або від середовища, треба обчислювати лише на клієнті — наприклад, усередині \`useEffect\`. Також можна використати особливі бібліотеки, як-от \`@react-hook/media-query\` або \`use-sync-external-store\`, щоб безпечно працювати з API переглядача.\\n\\nТакож важливо перевірити, що серверний і клієнтський рендеринг використовують ті самі дані. Якщо ви передаєте дані із сервера через \`window.__INITIAL_STATE__\`, переконайтеся, що їх серіалізують однаково.\\n\\nВисновок\\nГідрація — потужний інструмент, щоб покращити продуктивність і SEO, але вона потребує обережності. Уникайте недетермінованих значень у рендері, використовуйте ефекти задля клієнтських операцій і слідкуйте за узгодженістю даних. Це дасть змогу уникнути більшості помилок і забезпечить стабільну роботу застосунку.","// Bad: a random value in the render\\nfunction Component() {\\n  return <div>{Math.random()}</div>;\\n}\\n\\n// Good: the value is computed after the hydration\\nfunction Component() {\\n  const [value, setValue] = React.useState(null);\\n  React.useEffect(() => {\\n    setValue(Math.random());\\n  }, []);\\n  return <div>{value}</div>;\\n}"],[2699,"Stateful-компоненти зберігають власний стан і керують ним через useState або через класи, що дає їм змогу змінювати дані й відповідати на події. Stateless-компоненти не мають внутрішнього стану й цілковито залежать від своїх пропсів, що робить їх передбачуваними й легкими задля тестування. У сучасному React віддають перевагу функційним компонентам, а стан переносять у хуки або в глобальні сховища.","Базова концепція\\nУ React компоненти поділяють на два типи: stateful (зі станом) і stateless (без стану). Stateful-компоненти можуть зберігати й змінювати дані всередині себе, використовуючи механізми на кшталт useState або методів класу. Stateless-компоненти — чисті функції, які отримують дані через пропси й просто відображають їх, не маючи власного стану.\\n\\nПриклади коду\\nПодивімося на простий приклад. Stateless-компонент відображає вітання:\\n\\nStateful-компонент може змінювати свій стан — наприклад, лічильник:\\n\\nПрактичне застосування\\nStateless-компоненти корисні, щоб відображати статичні дані, як-от списки, картки або заголовки. Їх простіше зрозуміти й використовувати повторно. Stateful-компоненти застосовують для інтерактивних елементів: форм, модальних вікон, таймерів. У великих застосунках стан часто переносять у глобальні сховища (Redux, Context), щоб зменшити кількість stateful-компонентів і зробити архітектуру передбачуванішою.\\n\\nВисновок\\nВикористовуйте stateless-компоненти всюди, де це можливо, щоб зробити код і тестування простішими. Stateful-компоненти виправдані, коли локальний стан справді потрібний, але намагайтеся мінімізувати їхню кількість, переносячи складну логіку в хуки або в зовнішні сховища.","function Greeting({ name }) {\\n  return <h1>Hello, {name}!</h1>;\\n}\\n\\nimport { useState } from 'react';\\n\\nfunction Counter() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={() => setCount(count + 1)}>Increment</button>\\n    </div>\\n  );\\n}"],[2700,"Зберігання різнорідних даних у єдиному глобальному Redux-сторі — поширена практика, але вона потребує уважного структурування. Redux передбачає одне сховище для всього стану, що полегшує зневадження й синхронізацію; однак, коли застосунок зростає, це може призводити до надмірного зчеплення й складності. Рекомендують розділяти дані на зрізи (редюсери) й використовувати селектори, щоб ізолювати логіку.","Концепція єдиного сховища в Redux\\nRedux за своєю філософією використовує єдине глобальне сховище, яке зберігає весь стан застосунку. Це дає змогу мати єдине джерело істини, полегшує зневадження (наприклад, із Redux DevTools) і робить стан передбачуваним. Однак зберігання різнорідних даних, як-от профілю користувача й кошика, в одному сховищі не є помилкою — це стандартний підхід. Проблеми виникають тоді, коли структуру сховища не організовано належно.\\n\\nВплив на архітектуру\\nЯкщо всі дані лежать в одному сховищі без чіткого поділу, це може призводити до таких проблем: складності підтримки, труднощів із масштабуванням, надлишкових перемалювань компонентів і зчеплення між непов'язаними модулями. Аби цього уникати, Redux дає змогу розбити стан на зрізи за допомогою поєднання редюсерів. Кожний зріз відповідає за власну предметну область — наприклад, \`user\` і \`cart\`. Це зберігає єдине сховище, роблячи його структурованим.\\n\\nПрактичний приклад\\n\\nТакий підхід дає кожному модулю змогу працювати лише з власною частиною сховища, а селектори допомагають ізолювати дані. Наприклад, компонент кошика використовує \`state.cart\`, а профілю — \`state.user\`.\\n\\nКоли це виправдано\\nЄдине сховище виправдане для середніх і великих застосунків, де важливе централізоване керування станом. Для дуже великих проєктів можна розглянути альтернативи, як-от модульний стан (наприклад, Zustand), але Redux залишається надійним вибором завдяки своїй передбачуваності й своїм інструментам.\\n\\nПідсумовуючи: зберігання різнорідних даних в одному Redux-сторі — добра практика, якщо стан належно структуровано через зрізи й селектори. Це робить архітектуру простішою й масштабованою й полегшує зневадження, але потребує дисципліни в організації коду.","// store.js\\nimport { combineReducers, createStore } from 'redux';\\nimport userReducer from './userReducer';\\nimport cartReducer from './cartReducer';\\n\\nconst rootReducer = combineReducers({\\n  user: userReducer,\\n  cart: cartReducer\\n});\\n\\nconst store = createStore(rootReducer);\\n// Now the state is: { user: {...}, cart: {...} }"]]`);export{e as default};